window.DTCX=window.DTCX||{};DTCX.P3=[{"c":"P3400","t":"Zylinderabschaltsystem Bank 1","e":"Cylinder Deactivation System Bank 1","d":"Mit P3400 urteilt das Steuergerät über die ganze Bank 1: Die Zylinderabschaltung dort arbeitet nicht wie befohlen, ein bestimmter Stromkreis wird aber nicht benannt. Die Hersteller belegen den Code unterschiedlich. GM vergleicht beim LT4 der Corvette (2019) ein Saugrohrdruck-Modell mit allen Zylindern gegen dasselbe Modell bei abgeschalteten Zylindern; 100 Fehlproben von 200 ergeben einen Type-B-Code. Mazda kennt ihn bei den 2,5-l-Vierzylindern, wenn ein Ölsteuerventil der Abschaltung verstopft ist, etwa durch Plastikfetzen der Filterhülle (SA-061/20). Bei Honda hängt er am Öldruckschalter der VCM-Kipphebel, Ram bietet für den Hemi ein PCM-Update. Bank 2 meldet P3497. Die Leuchte geht an, oft mit Fehlzündungen oder unrundem Lauf.","u":[["h","Ölsteuerventil der Abschaltung oder sein Sieb durch Fremdkörper verstopft"],["h","Zu wenig Öl, falsche Sorte oder überfälliger Ölwechsel"],["m","Schaltbarer Kipphebel oder Stößel gebrochen, verrutscht oder rastet nicht"],["l","Zu hoher Öldruck beim Kaltstart, etwa durch schwache Überdruckventilfeder"],["l","Motorsteuergeräte-Software, die ein Update braucht"]],"s":["Motorkontrollleuchte an","Unruhiger Leerlauf oder Fehlzündungscodes auf den abschaltbaren Zylindern","Ticken oder Klappern aus dem Ventiltrieb","Teilzylinderbetrieb entfällt, höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","lifter","oil_control_valve"],"r":["hard",0,[80,4000],[0.5,12]],"f":"MED","x":["P3497","P3401","P3498","P349B","P2652","P341A","P0300"]},{"c":"P3401","t":"Zylinder 1 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 1 Deactivation/Intake Valve Control Circuit/Open","d":"P3401 weist auf einen unterbrochenen Steuerweg zum Magnetventil hin, das Zylinder 1 abschaltet – diesen Zylinder legen die V8 von GM und Chrysler ebenso still wie Fords 1,5-l-Dreizylinder-EcoBoost. GM prüft bei den V8-Motoren L84 und L86 (2019) die Low-Side-Endstufe im ausgeschalteten Zustand: Mehr als 200 Kiloohm nach Masse gelten als Unterbrechung, 20 Fehler unter 25 Messungen im Abstand von 250 ms setzen einen Type-B-Code; manche Steuergeräte legen dabei zusätzlich P3403 ab. Ford entscheidet über den Fehlerstatus der Smart-Endstufe binnen 5 Sekunden. Beim 5,7-l-Hemi beschreibt ein STAR-Fall ein verbogenes Krümmer-Hitzeschild, das den Kabelbaum der MDS-Ventile durchscheuert. Kurzschlüsse sind P3403/P3404, die Mechanik P3402. Die Abschaltung bleibt gesperrt.","u":[["h","Steuerleitung gerissen oder durchgescheuert, etwa am Abgas-Hitzeschild"],["m","Lockerer, korrodierter oder verölter Stecker am Magnetventil"],["m","Unterbrochene Spule im Abschalt-Magnetventil von Zylinder 1"],["l","Defekte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an, bei GM nach der zweiten Fahrt","Motor bleibt im Vollzylinderbetrieb","Etwas höherer Kraftstoffverbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3402","P3403","P3404","P3405","P3400","P3498"]},{"c":"P3402","t":"Zylinder 1 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 1 Deactivation/Intake Valve Control Performance","d":"P3402 meldet, dass Zylinder 1 beim Ab- oder Zuschalten nicht wie erwartet reagiert, obwohl der Steuerkreis elektrisch in Ordnung ist. Ford führt den Code in seiner Überwachung „Variable Displacement Engine“ der Benziner 2020–2023: Sie läuft während der Abschaltung sowie beim Ein- und Ausstieg, zwischen 400 und 4500 U/min und erst, wenn der Öldruck rund zwei Sekunden Zeit zum Aufbau hatte. GM prüft dieselbe Mechanik bei Zylinder 1 unter dem eigenen Code P3498. Leitungsfehler desselben Kanals laufen als P3401, P3403 oder P3404. Im Alltag zeigen sich Warnleuchte, Ruckeln beim Moduswechsel oder Fehlzündungen auf Zylinder 1.","u":[["h","Zu wenig, falsches oder gealtertes Öl verzögert das hydraulische Umschalten"],["m","Schaltbarer Stößel oder Kipphebel an Zylinder 1 klemmt oder rastet nicht ein"],["m","Abschalt-Magnetventil klemmt oder sein Ölsieb ist zugesetzt"],["l","Undichte Ventildichtung lässt den Steuerdruck abfallen"]],"s":["Motorkontrollleuchte an","Ruckeln beim Wechsel in den oder aus dem Teilzylinderbetrieb","Fehlzündungen auf Zylinder 1 (P0301)","Zylinderabschaltung wird nicht mehr genutzt, höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3401","P3403","P3404","P3406","P3400","P3498","P0301"]},{"c":"P3403","t":"Zylinder 1 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 1 Deactivation/Intake Valve Control Circuit Low","d":"Das Steuergerät schaltet das Abschaltventil von Zylinder 1 über eine Endstufe, die ihre Leitung selbst prüft. P3403 heißt: Diese Prüfung hat einen Masseschluss der Steuerleitung gefunden. GM beschreibt das für die V8-Motoren L84 und L86 (Modelljahr 2019): Bei ausgeschalteter Endstufe gilt ein Widerstand unter 0,5 Ohm nach Masse als Fehler; 20 Treffer aus 25 Messungen im 250-ms-Takt ergeben einen Type-B-Code, die Lampe geht also nach der zweiten Fahrt an. Fords VDE-Überwachung erkennt denselben Schluss über ihre Smart-Endstufe binnen 5 Sekunden. Unterbrechung ist P3401, Plusschluss P3404, ein mechanischer Fehler P3402. Der Motor läuft dann dauerhaft mit allen Zylindern und verbraucht mehr.","u":[["h","Steuerleitung am Motor durchgescheuert, Schluss nach Masse"],["m","Innerer Schluss im Abschalt-Magnetventil von Zylinder 1"],["l","Öl oder Wasser im Stecker des Magnetventils"],["l","Defekte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten an","Motor wechselt nicht mehr in den Teilzylinderbetrieb","Etwas höherer Kraftstoffverbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3401","P3402","P3404","P3407","P3400"]},{"c":"P3404","t":"Zylinder 1 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 1 Deactivation/Intake Valve Control Circuit High","d":"P3404 ist innerhalb der Gruppe von Zylinder 1 der Code für einen Schluss nach Plus. GM prüft ihn bei eingeschalteter Low-Side-Endstufe: Zeigt der Ausgang dann weniger als 0,5 Ohm zur Versorgungsspannung, fließt der Strom nicht ordentlich über die Spule, und 20 von 25 Messungen im 250-ms-Raster setzen einen Type-B-Fehler. Gemessen wird nur bei mindestens 11 V am Powertrain-Relais und rund 425 U/min (L84; beim L86 400 U/min). Ford nennt P3404 für den einzigen abschaltbaren Zylinder seiner VDE-Motoren. Meist berührt die Steuerleitung eine Plusleitung oder die Spule hat Windungsschluss. Abgrenzung: P3403 ist der Masseschluss, P3401 die Unterbrechung.","u":[["h","Steuerleitung im Kabelbaum mit einer Plusleitung verbunden"],["m","Windungsschluss im Abschalt-Magnetventil von Zylinder 1"],["l","Beschädigte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung abgeschaltet","Möglicherweise weitere Kreiscodes an anderen Ventilen, wenn eine gemeinsame Versorgung betroffen ist"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3401","P3402","P3403","P3408","P3400"]},{"c":"P3405","t":"Zylinder 1 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 1 Exhaust Valve Control Circuit/Open","d":"J2012 sieht P3405 für einen unterbrochenen Steuerkreis eines eigenen Auslassventil-Stellglieds an Zylinder 1 vor. Kein Hersteller dokumentiert diesen Code öffentlich. Die verbreiteten Systeme brauchen ihn nicht: Bei GMs Dynamic Fuel Management versorgt ein Magnetventil je Zylinder Einlass- und Auslassstößel gemeinsam, und Fords VDE führt für Zylinder 1 nur Einlass-Codes. Eine GM-Patentanmeldung nutzt ein gemeinsames Hydraulikventil und legt nur die Reihenfolge fest: Auslassventile schalten vor den Einlassventilen ab und auch vor ihnen wieder zu. Ein Ford-Patent überwacht das Auslassventil am Abgasdruck. Ein eigenes Auslass-Stellglied fiele unter die CARB-Vorgabe mit Durchgangsprüfung. Wo er genutzt wird, steht P3405 für eine offene Spule oder Leitung; P3401 betrifft die Einlassseite, P3406–P3408 die übrigen Auslassfehler.","u":[["m","Leitungsbruch oder lockerer Kontakt zum Auslassventil-Stellglied"],["m","Unterbrochene Spule im Auslassventil-Stellglied von Zylinder 1"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung bzw. Ventilumschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3406","P3407","P3408","P3401","P3400"]},{"c":"P3406","t":"Zylinder 1 Auslassventil Steuerung Funktion","e":"Cylinder 1 Exhaust Valve Control Performance","d":"Steuert ein Motor die Auslassventile von Zylinder 1 gesondert, stünde P3406 dafür, dass die Auslassseite dem Befehl nicht folgt, obwohl der Kreis elektrisch in Ordnung ist. Kein Hersteller dokumentiert diesen Code öffentlich. Ein Ford-Patent erkennt ein nach der Abschaltung weiter öffnendes Auslassventil an Druckschwankungen im Abgas, ein GM-Patent schaltet mit einem gemeinsamen Steuerventil die Auslassventile vor den Einlassventilen ab und auch vor ihnen wieder zu – eine nachhinkende Auslassseite ist also ein realer Fehlerfall. Serienmotoren von GM und Ford prüfen stattdessen den ganzen Zylinder (GM P3498, Ford P3402). Elektrische Fehler dieses Kanals sind P3405, P3407 und P3408. Spürbar wäre unruhiger Lauf im Teilzylinderbetrieb.","u":[["m","Zu wenig oder verbrauchtes Öl verzögert das Umschalten auf der Auslassseite"],["m","Auslass-Stößel oder -Kipphebel von Zylinder 1 rastet nicht ein oder aus"],["l","Auslassventil-Stellglied klemmt"]],"s":["Motorkontrollleuchte an","Unrunder Lauf oder Vibrationen im Teilzylinderbetrieb","Zylinderabschaltung ausgesetzt"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3405","P3407","P3408","P3402","P3400"]},{"c":"P3407","t":"Zylinder 1 Auslassventil Steuerkreis niedrig","e":"Cylinder 1 Exhaust Valve Control Circuit Low","d":"P3407 steht für einen Masseschluss im Steuerkreis eines eigenen Auslassventil-Stellglieds an Zylinder 1. Kein Hersteller dokumentiert diesen Code öffentlich, veröffentlichte Schwellen gibt es daher nicht. Zum Vergleich: GM wertet beim einlassseitigen P3403 weniger als 0,5 Ohm nach Masse bei ausgeschalteter Endstufe als Fehler. CARB verlangt, solche Ausgangskreise auf Kurzschlüsse zu prüfen. Motoren mit einem gemeinsamen Ventil je Zylinder wie GMs AFM- und DFM-V8 melden diesen Fehler stattdessen über die Einlass-Codes. Eine Unterbrechung auf der Auslassseite wäre P3405, ein Plusschluss P3408. Das Auto fährt meist normal auf allen Zylindern weiter, mit Warnleuchte.","u":[["m","Steuerleitung des Stellglieds mit Masse verbunden"],["m","Innerer Schluss im Auslassventil-Stellglied"],["l","Fehler in der Endstufe des Motorsteuergeräts"]],"s":["Motorkontrollleuchte an","Kein Wechsel in den Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3405","P3406","P3408","P3403","P3400"]},{"c":"P3408","t":"Zylinder 1 Auslassventil Steuerkreis hoch","e":"Cylinder 1 Exhaust Valve Control Circuit High","d":"Hat ein Motor ein eigenes Stellglied für die Auslassventile von Zylinder 1, kennzeichnet P3408 einen zu hohen Pegel im Steuerkreis, meist einen Schluss nach Batteriespannung. Kein Hersteller dokumentiert diesen Code öffentlich. Zum Vergleich prüft GM das einlassseitige P3404 bei eingeschalteter Endstufe und meldet unter 0,5 Ohm zur Versorgung. Auch eine GM-Patentanmeldung schaltet Ein- und Auslassventile gemeinsam über ein Hydraulikventil, die Auslassseite zuerst, und kennt keinen eigenen Auslasskanal. Mit einem Ventil je Zylinder wie bei GMs DFM entfällt der Code. Geschwister: P3405 Unterbrechung, P3406 Funktion, P3407 Masseschluss; P3404 ist das Gegenstück auf der Einlassseite.","u":[["m","Steuerleitung mit einer Versorgungsspannung verbunden"],["m","Windungsschluss im Auslassventil-Stellglied"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3405","P3406","P3407","P3404","P3400"]},{"c":"P3409","t":"Zylinder 2 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 2 Deactivation/Intake Valve Control Circuit/Open","d":"P3409 ist der Unterbrechungs-Code der Abschaltsteuerung von Zylinder 2. GM nutzt ihn an zwei sehr unterschiedlichen Motoren. Beim 3,6-l-V6 (LGX, LGZ) gehört Zylinder 2 zu den beiden abschaltbaren Zylindern; eine Engineering-Information verbindet P3409 mit Öl, das am Kipphebel-Ölsteuerventil im Nockenwellendeckel austritt. Beim V8 L84 mit Dynamic Fuel Management hat jeder Zylinder ein Magnetventil; GM erkennt eine Unterbrechung an mehr als 200 kOhm bei ausgeschalteter Endstufe, 20 von 25 Messungen im 250-ms-Takt, Type B. Schlüsse laufen als P3411 und P3412, ein mechanischer Fehler als P3410. Der Fahrer sieht die Warnleuchte, die Spar-Betriebsart entfällt.","u":[["h","Öl tritt am Steuerventil aus und durchnässt dessen Stecker (GM 3,6-l-V6)"],["m","Leitungsbruch oder lockerer Pin im Kreis des Magnetventils von Zylinder 2"],["m","Unterbrochene Spule im Abschalt-Magnetventil von Zylinder 2"],["l","Fehler der Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Ölspuren am Steuerventil im Ventildeckel (V6)","Kein Teilzylinderbetrieb, höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3410","P3411","P3412","P3413","P3433","P3497","P0302"]},{"c":"P340A","t":"Abschaltung/Einlassventil Steuerkreis Bank 1","e":"Deactivation/Intake Valve Control Circuit Bank 1","d":"P340A ist für Motoren gedacht, die die Einlassventile einer ganzen Bank über einen gemeinsamen Steuerkreis schalten statt über je ein Magnetventil pro Zylinder. Der Code meldet einen elektrischen Fehler in diesem Kreis von Bank 1, ohne zwischen Unterbrechung und Kurzschluss zu trennen. Kein Hersteller dokumentiert ihn öffentlich, veröffentlichte Schwellen fehlen daher; CARB verlangt lediglich, solche Ausgangskreise auf Unterbrechung und Kurzschluss zu prüfen. Die verbreiteten Systeme arbeiten zylinderweise: GMs DFM-V8 hat im V des Blocks ein Ventil je Zylinder und meldet Fehler etwa als P3401, Hondas VCM-V6 legt Bankfehler als P3400 ab. Bank 2 ist P340B, die Auslassseite P340C, die Funktionsprüfung P341A. Zu erwarten: Warnleuchte, kein Teilzylinderbetrieb.","u":[["m","Beschädigte, unterbrochene oder kurzgeschlossene Leitung im Steuerkreis von Bank 1"],["m","Korrodierter oder lockerer Stecker am Stellglied von Bank 1"],["m","Einlass-Abschaltstellglied von Bank 1 mit unterbrochener oder kurzgeschlossener Spule"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung auf Bank 1 gesperrt","Höherer Verbrauch bei geringer Last"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P340B","P340C","P341A","P3400","P3401"]},{"c":"P340B","t":"Abschaltung/Einlassventil Steuerkreis Bank 2","e":"Deactivation/Intake Valve Control Circuit Bank 2","d":"P340B ist das Gegenstück zu P340A für Bank 2, also die Bank ohne Zylinder 1 – er betrifft nur V- oder Boxermotoren. Gemeldet wird ein elektrischer Fehler in einem Steuerkreis, der die Einlassventile dieser ganzen Bank gemeinsam schaltet. Kein Hersteller dokumentiert den Code öffentlich. Die verbreiteten V8-Systeme versorgen die abschaltbaren Zylinder der Bank 2, bei GM und Chrysler die Zylinder 4 und 6, mit eigenen Ventilen und melden sie als P3425 oder P3441. Hondas VCM-V6 überwacht Bank 2 über einen Öldruckschalter der Kipphebel und speichert dann P3497. CARB fordert für solche Ausgänge eine Kreisprüfung. Bank 1 ist P340A, der Auslasskreis von Bank 2 P340D, der Funktionscode P341B. Meist bleibt es bei Leuchte und Mehrverbrauch.","u":[["m","Durchgescheuerte, unterbrochene oder kurzgeschlossene Leitung zum Stellglied von Bank 2"],["m","Öl oder Feuchtigkeit im Stecker des Stellglieds von Bank 2"],["m","Defekte Spule des Einlass-Abschaltstellglieds von Bank 2"],["l","Fehler in der Endstufe des Motorsteuergeräts"]],"s":["Motorkontrollleuchte an","Motor läuft dauerhaft mit allen Zylindern","Leicht erhöhter Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P340A","P340D","P341B","P3497","P3425"]},{"c":"P340C","t":"Abschaltung/Auslassventil Steuerkreis Bank 1","e":"Deactivation/Exhaust Valve Control Circuit Bank 1","d":"P340C betrifft einen eigenen Stromkreis, der die Auslassventile von Bank 1 gemeinsam abschaltet. Ein Fehler in Leitung, Stecker oder Spule des Stellglieds setzt den Code. Kein Hersteller dokumentiert ihn öffentlich, und die bekannten Serienlösungen kommen ohne ihn aus: GMs DFM-Motoren steuern Ein- und Auslassventil eines Zylinders über ein gemeinsames Magnetventil, und eine GM-Patentanmeldung beschreibt ein Hydraulikventil je Zylinderpaar, bei dem allein die Nockenstellung dafür sorgt, dass die Auslassventile vor den Einlassventilen stillgelegt werden. CARB verlangt für jeden solchen Ausgang eine Prüfung auf Unterbrechung und Kurzschluss. Einlassseitig gilt P340A, Bank 2 Auslass P340D, die Funktion auf Bank 1 P341C. Spürbar ist meist nur die Leuchte, die Abschaltung ruht.","u":[["m","Unterbrochene oder kurzgeschlossene Leitung im Kreis des Auslass-Stellglieds von Bank 1"],["m","Spule des Auslass-Abschaltstellglieds unterbrochen oder kurzgeschlossen"],["l","Stecker oder Leitung durch Hitze an der Auslassseite beschädigt"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P340A","P340D","P341C","P3400","P3405"]},{"c":"P340D","t":"Abschaltung/Auslassventil Steuerkreis Bank 2","e":"Deactivation/Exhaust Valve Control Circuit Bank 2","d":"P340D ist die Bank-2-Fassung des auslassseitigen Sammelkreises: Das Steuergerät erkennt einen elektrischen Fehler an der Leitung, die die Auslassventile der Bank ohne Zylinder 1 stilllegen soll. Kein Hersteller dokumentiert den Code öffentlich. Eine eigene Auslasssteuerung ist von Bedeutung, weil ein Zylinder nur dann als Gasfeder arbeitet, wenn auch seine Auslassventile geschlossen bleiben; ein Ford-Patent zeigt, wie sich ein weiter öffnendes Auslassventil am Abgasdruck erkennen lässt. Bei bekannten Motoren werden Ein- und Auslass jedoch je Zylinder gemeinsam geschaltet, so bei GMs DFM. CARB verlangt die Überwachung solcher Ausgangskreise. Verwandt: P340C für Bank 1, P340B für den Einlass von Bank 2, P341D für die Funktion. Die Abschaltung bleibt aus.","u":[["m","Beschädigte Leitung zum Auslass-Abschaltstellglied von Bank 2"],["m","Defekte Spule im Auslass-Stellglied von Bank 2"],["l","Fehler in der Endstufe des Motorsteuergeräts"]],"s":["Motorkontrollleuchte an","Motor schaltet bei geringer Last keine Zylinder mehr ab"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P340C","P340B","P341D","P3497"]},{"c":"P3410","t":"Zylinder 2 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 2 Deactivation/Intake Valve Control Performance","d":"P3410 betrifft eine Abschaltung von Zylinder 2, die elektrisch intakt ist, aber nicht tut, was befohlen wird – etwa Ventile, die weiter öffnen oder nicht zurückschalten. Kein Hersteller dokumentiert diesen Code öffentlich. GM prüft dieses Verhalten beim L84 unter dem eigenen Code P3499 über den Saugrohrdruck, solange Zylinder 2 abgeschaltet sein soll; Ford nutzt das Pendant für Zylinder 1, P3402. Wie solche Fehler in der Praxis aussehen, zeigt GMs Bulletin 21-NA-036 zu 3,6-l-V6-Motoren: Öl, das am Steuerventil vorbeiläuft, oder nicht einrastende Kipphebel führen zu Fehlzündungen auf Zylinder 2 (P0302). Kreisfehler gehören zu P3409, P3411 und P3412. Zu erwarten sind unruhiger Lauf und Mehrverbrauch.","u":[["h","Öl läuft an der Dichtung des Steuerventils vorbei, Druck geht verloren"],["m","Kipphebel oder Stößel von Zylinder 2 rastet nicht ein"],["m","Zu wenig oder gealtertes Öl"],["l","Abgebrochene Ventilspitze in der Bohrung lässt ein neues Ventil nicht sitzen"]],"s":["Fehlzündungen auf Zylinder 2, oft nach einer Teilzylinderphase","Motorkontrollleuchte an","Vibrationen bei geringer Last"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3409","P3411","P3412","P3414","P3499","P0302","P3497"]},{"c":"P3411","t":"Zylinder 2 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 2 Deactivation/Intake Valve Control Circuit Low","d":"P3411 bedeutet, dass der Steuerausgang für das Abschaltventil von Zylinder 2 einen Masseschluss sieht. GM führt den Code beim V8 L84 (2019), dessen Dynamic Fuel Management jeden Zylinder abschalten kann: weniger als 0,5 Ohm nach Masse bei ausgeschalteter Low-Side-Endstufe, 20 Fehler in 25 Messungen alle 250 ms, mindestens 11 V am Powertrain-Relais und 425 U/min. Als Type-B-Fehler geht die Lampe nach zwei aufeinanderfolgenden Fahrten an. Laut GM setzen manche Steuergeräte dabei zusätzlich P3409. Wo Zylinder 2 nicht abschaltbar ist, kommt der Code nicht vor. Ursache liegt meist in der Leitung oder im Magnetventil im Motor-V; P3412 ist der Plusschluss.","u":[["h","Beschädigte Isolierung, Steuerleitung berührt Masse"],["m","Magnetventil von Zylinder 2 innen kurzgeschlossen"],["l","Defekte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten","Dynamic Fuel Management inaktiv, Motor bleibt auf allen Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3409","P3410","P3412","P3415","P3497"]},{"c":"P3412","t":"Zylinder 2 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 2 Deactivation/Intake Valve Control Circuit High","d":"Beim GM-V8 L84 sitzt für jeden Zylinder, auch für Zylinder 2, ein Stößel-Öl-Magnetventil im Motor-V. Die NHTSA-Beschreibung des Systems nennt eine Ansteuerung mit Anzugs- und Haltestrom für schnelles Schalten. P3412 wird gesetzt, wenn die Steuerleitung von Zylinder 2 Schluss nach Versorgungsspannung hat: GM prüft bei eingeschalteter Endstufe und wertet unter 0,5 Ohm zur Versorgung als Fehler, 20 von 25 Messungen im 250-ms-Takt, Type B. Dann kann das Steuergerät das Ventil nicht sauber schalten und nimmt Zylinder 2 aus der Abschaltung. Verwandt sind P3409 für Unterbrechung, P3411 für Masseschluss und P3410, wenn der Kreis stimmt, der Zylinder aber nicht reagiert.","u":[["h","Steuerleitung im Kabelbaum mit einer Spannungsversorgung verbunden"],["m","Zu niederohmige Spule im Magnetventil von Zylinder 2"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung nicht mehr aktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3409","P3410","P3411","P3416","P3497"]},{"c":"P3413","t":"Zylinder 2 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 2 Exhaust Valve Control Circuit/Open","d":"P3413 gehört zur Auslass-Hälfte des Blocks für Zylinder 2 und meldet einen unterbrochenen Steuerkreis eines gesondert angesteuerten Auslassventil-Stellglieds. Kein Hersteller dokumentiert diesen Code öffentlich. Die Motoren, die Zylinder 2 nachweislich abschalten – GMs V8 L84 und der 3,6-l-V6 –, schalten Ein- und Auslassventile über ein gemeinsames Steuerventil je Zylinder und melden Kreisfehler deshalb als P3409. Gelten würde der Code nur für Bauarten mit eigenem Steuerventil für die Auslassseite; eine GM-Patentanmeldung schaltet dagegen beide Seiten über ein gemeinsames Ventil und staffelt sie nur, die Auslassseite zuerst. CARB verlangt für solche Ausgangskomponenten eine Durchgangsprüfung. P3414 bis P3416 vervollständigen die Auslassgruppe. Für den Fahrer: Warnleuchte, keine Abschaltung.","u":[["m","Unterbrochene Leitung oder Stecker zum Auslass-Stellglied von Zylinder 2"],["m","Spule des Stellglieds unterbrochen"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3414","P3415","P3416","P3409","P3497"]},{"c":"P3414","t":"Zylinder 2 Auslassventil Steuerung Funktion","e":"Cylinder 2 Exhaust Valve Control Performance","d":"P3414 würde gesetzt, wenn die Auslassventile von Zylinder 2 an einem Motor mit gesonderter Auslasssteuerung einem Ab- oder Zuschaltbefehl nicht folgen. Kein Hersteller dokumentiert diesen Code öffentlich. Das zugrunde liegende Problem beschreibt ein Ford-Patent: Ein Auslassventil, das nach der Abschaltung weiter öffnet, zeigt sich als Druckschwankung im Abgas, worauf das Steuergerät den Zylinder wieder zuschalten oder weitere Abschaltungen sperren kann. GMs DFM-Motoren melden einen Zylinder, dessen Ein- und Auslassventile aktiv bleiben, stattdessen unter dem eigenen Code P3499. Elektrische Fehler dieses Kanals sind P3413, P3415 und P3416; der Funktionscode der Einlassseite ist P3410.","u":[["m","Auslassseitiger Stößel oder Kipphebel von Zylinder 2 schaltet nicht"],["m","Zu geringer Öldruck oder aufgeschäumtes Öl"],["l","Ventil des Auslass-Stellglieds klemmt"]],"s":["Motorkontrollleuchte an","Unrunder Lauf bei abgeschalteten Zylindern","Abschaltung vom Steuergerät ausgesetzt"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3413","P3415","P3416","P3410","P3499"]},{"c":"P3415","t":"Zylinder 2 Auslassventil Steuerkreis niedrig","e":"Cylinder 2 Exhaust Valve Control Circuit Low","d":"P3415 beschreibt einen Steuerkreis für ein eigenes Auslassventil-Stellglied an Zylinder 2, der nach Masse gezogen wird. Kein Hersteller dokumentiert diesen Code öffentlich. Zylinder 2 selbst wird oft abgeschaltet: GM legt ihn bei den 3,6- und 3,0-l-V6 (Bulletin 21-NA-036) und bei den DFM-V8 still, dort bedient aber ein Ölsteuerventil den ganzen Zylinder, Leitungsfehler erscheinen deshalb als Einlass-Codes P3409, P3411 und P3412. Beim L84 wertet GM weniger als 0,5 Ohm nach Masse bei abgeschalteter Endstufe als Kurzschluss. CARB verlangt, solche Ausgangskreise auf Schlüsse zu prüfen. Geschwister: P3413 Unterbrechung, P3414 Funktion, P3416 Plusschluss; Zylinder 1 nutzt P3407. Der Motor läuft auf allen Zylindern weiter.","u":[["m","Steuerleitung des Auslass-Stellglieds von Zylinder 2 hat Masseschluss"],["m","Innerer Kurzschluss im Auslass-Stellglied von Zylinder 2"],["l","Beschädigte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung unterbunden"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3413","P3414","P3416","P3411","P3407"]},{"c":"P3416","t":"Zylinder 2 Auslassventil Steuerkreis hoch","e":"Cylinder 2 Exhaust Valve Control Circuit High","d":"P3416 bedeutet, dass die Steuerleitung eines eigenen Auslassventil-Stellglieds an Zylinder 2 zu hoch liegt, meist weil sie eine Versorgungsspannung berührt oder die Spule Windungsschluss hat. Kein Hersteller dokumentiert diesen Code öffentlich. Die nächstliegende veröffentlichte Prüfung ist GMs Test für das einlassseitige P3412 am L84: Bei eingeschalteter Endstufe gelten weniger als 0,5 Ohm zur Versorgung als Fehler, 20 von 25 Messungen setzen einen Type-B-Code. Die NHTSA-Untersuchung zu GMs DFM-V8 beschreibt je Zylinder ein Stößel-Öl-Magnetventil, das Ein- und Auslass gleichermaßen bedient – deshalb brauchen solche Motoren keinen reinen Auslass-Code. CARB verlangt, Kurzschlüsse an Ausgängen zu erkennen. Verwandt: P3413 Unterbrechung, P3415 Masseschluss, P3408 für Zylinder 1.","u":[["m","Steuerleitung des Stellglieds mit einer Versorgungsleitung verbunden"],["m","Windungsschluss in der Spule des Auslass-Stellglieds von Zylinder 2"],["l","Fehler in der Endstufe des Motorsteuergeräts"]],"s":["Motorkontrollleuchte an","Motor bleibt im Vollzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3413","P3414","P3415","P3412","P3408"]},{"c":"P3417","t":"Zylinder 3 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 3 Deactivation/Intake Valve Control Circuit/Open","d":"P3417 meldet einen unterbrochenen Ansteuerkreis des Abschalt-Magnetventils von Zylinder 3. GM belegt den Code zweimal: Die Tabelle 2007 für Displacement on Demand deckt die Ventilkreise an Zylinder 1, 3 und 5 ab und wertet 30 fehlerhafte Messungen aus 100 oberhalb von 800 U/min. Für den DFM-Motor L84 (2019) erwartet das Steuergerät über 200 kOhm, solange sein Low-Side-Treiber ruht, 20 von 25 Prüfungen, Type B. Dasselbe Steuergerät überwacht zusätzlich einen High-Side-Treiber dieses Ventils unter eigenen Codes, und GM weist darauf hin, dass P3419 mit auftreten kann. Auch die V8 LTA und LT2 legen Zylinder 3 still (Bulletin 20-NA-038). Bei offenem Kreis läuft der Motor dauerhaft mit allen Zylindern.","u":[["h","Gebrochene oder durchgescheuerte Leitung zwischen Steuergerät und Ventil von Zylinder 3"],["m","Unterbrochene Wicklung im Abschalt-Magnetventil von Zylinder 3"],["m","Lockerer, verölter oder korrodierter Ventilstecker"],["l","Ausgefallene Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb schaltet nicht mehr zu","Etwas höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3418","P3419","P3420","P3421","P349A","P3401","P3433","P3400"]},{"c":"P3418","t":"Zylinder 3 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 3 Deactivation/Intake Valve Control Performance","d":"P3418 ist für eine Abschaltung von Zylinder 3 gedacht, die elektrisch in Ordnung ist, aber nicht wie verlangt reagiert: Der Zylinder atmet weiter, wenn er ruhen soll, oder kommt nicht zurück. Kein Hersteller dokumentiert diesen Code öffentlich. Die Mechanik von Zylinder 3 testet GM stattdessen unter P349A; Bulletin 20-NA-204 zu L84 und L87 (2021) beschreibt, dass ein Spannungseinbruch beim Anlassen die Ausgänge kurz abschalten und diesen Code ohne echten Defekt setzen kann. Honda zeigt dasselbe Fehlerbild in anderer Form: Laut Bulletin 13-055 drückte zu hoher Öldruck beim Kaltstart die Zylinder 1 bis 4 ungewollt in die Abschaltung, gemeldet als P3400/P3497 mit Fehlzündungen. Kreisfehler gehören zu P3417, P3419 und P3420. Typisch sind unruhiger Lauf und ein Fehlzündungscode.","u":[["h","Zu wenig Öl, falsche Viskosität oder gealtertes Öl"],["m","Stößel oder Kipphebel von Zylinder 3 verriegelt oder entriegelt nicht"],["m","Steuerventil von Zylinder 3 klemmt oder sein Sieb ist zugesetzt"],["l","Öldruck zu hoch oder zu niedrig für das Schaltfenster"]],"s":["Fehlzündungscode für Zylinder 3 (P0303)","Ruckeln beim Wechsel der Betriebsart","Motorkontrollleuchte an"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3417","P3419","P3420","P3422","P349A","P0303","P3400","P3426"]},{"c":"P3419","t":"Zylinder 3 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 3 Deactivation/Intake Valve Control Circuit Low","d":"P3419 besagt, dass die Leitung zum Abschalt-Magnetventil von Zylinder 3 nach Masse gezogen wird. Wie GM das beim V8 L84 prüft, steht in den OBD-Unterlagen 2019: Ruht der Low-Side-Ausgang, ist ein Widerstand unter einem halben Ohm zur Masse unzulässig, sobald 20 von 25 Proben im 250-ms-Takt übereinstimmen – vorausgesetzt, das Antriebsrelais liefert mindestens 11 V und der Motor dreht mit 425 U/min oder mehr. Es entsteht ein Type-B-Code, die Leuchte geht also nach zwei Fahrten an; bei manchen Steuergeräten wird P3417 mit abgelegt. Die ältere Tabelle 2007 für Displacement on Demand fasste Schluss und Unterbrechung für Zylinder 3 noch in einem Ventiltest zusammen. P3420 ist der Gegenfehler, P3427 das Pendant für Zylinder 4. Fahren lässt sich normal, nur die Spritersparnis entfällt.","u":[["h","Isolierung der Steuerleitung von Zylinder 3 bis auf Masse durchgescheuert"],["m","Innerer Schluss des Ventils von Zylinder 3 gegen das Gehäuse"],["l","Öl oder Wasser überbrückt Kontakte im Stecker"],["l","Defekter Treiber im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten","Motor schaltet bei geringer Last keine Zylinder mehr ab"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3417","P3418","P3420","P3423","P3427","P3411"]},{"c":"P341A","t":"Abschaltung/Einlassventil Steuerkreis Funktion Bank 1","e":"Deactivation/Intake Valve Control Circuit Performance Bank 1","d":"P341A ist die Funktionsprüfung hinter P340A: Der Einlass-Abschaltkreis von Bank 1 ist elektrisch in Ordnung, die Ventile landen aber nicht dort, wo sie hinsollen. Kein Hersteller dokumentiert den Code öffentlich. Vergleichbare Prüfungen gibt es unter anderen Nummern: GM vergleicht beim LT4 gemessenen und berechneten Saugrohrdruck mit und ohne Abschaltung und meldet das Ergebnis für die Bank als P3400; zylinderweise Fehler der DFM-Motoren laufen ab P3498. Ein Delphi-Patent erklärt, warum ein gemittelter Saugrohrdruck allein funktionierende und gestörte Einlassabschaltung nur schlecht trennt und den Zylinder nicht benennen kann. Die Ursachen sind meist hydraulisch: wenig oder verschmutztes Öl, ein klemmendes Steuerventil, nicht einrastende Stößel. Fehlzündungen und unrunder Lauf sind möglich.","u":[["h","Zu wenig Öl oder gealtertes, verschmutztes Öl"],["m","Abschalt-Steuerventil von Bank 1 klemmt oder Sieb zugesetzt"],["m","Schaltbare Stößel oder Kipphebel auf Bank 1 rasten nicht ein oder aus"],["l","Zu geringer Öldruck durch verschlissene Pumpe oder undichte Dichtung"]],"s":["Motorkontrollleuchte an","Ruck oder Vibration beim Ab- und Zuschalten der Zylinder","Fehlzündungscodes auf Bank 1"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P340A","P341B","P341C","P3400","P3498"]},{"c":"P341B","t":"Abschaltung/Einlassventil Steuerkreis Funktion Bank 2","e":"Deactivation/Intake Valve Control Circuit Performance Bank 2","d":"Bei P341B kommt das Steuergerät zu dem Schluss, dass die Einlassabschaltung auf Bank 2 ihre Aufgabe nicht erfüllt, obwohl kein Kreisfehler vorliegt: Zylinder atmen weiter, obwohl sie dicht sein sollten, oder bleiben nach dem Zuschalten verschlossen. Kein Hersteller dokumentiert den Code öffentlich. Ein Erkennungsweg steht in einem Delphi-Patent: Druckpulse im Ansaugtrakt werden gegen den Kurbelwinkel getaktet, und ein fehlender oder zusätzlicher Puls verrät den betroffenen Zylinder. In der Praxis nehmen die Hersteller eigene Codes, etwa GMs Reihe ab P3498 je Zylinder oder Hondas Bankcode P3497. CARB verlangt eine Funktionsprüfung solcher Stellglieder. Elektrische Fehler derselben Bank laufen unter P340B, Bank 1 unter P341A. Zuerst Ölstand und Ölzustand prüfen.","u":[["h","Ölstand zu niedrig oder Öl über die Wechselfrist hinaus"],["m","Stößel oder Kipphebel auf Bank 2 hängt in einer Schaltstellung"],["m","Steuerventil auf Bank 2 klemmt oder ist an der Dichtung undicht"]],"s":["Motorkontrollleuchte an","Unrunder Lauf, vor allem bei geringer Last","Fehlzündungscodes auf Bank 2"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P340B","P341A","P341D","P3497","P3499"]},{"c":"P341C","t":"Abschaltung/Auslassventil Steuerkreis Funktion Bank 1","e":"Deactivation/Exhaust Valve Control Circuit Performance Bank 1","d":"P341C erfasst Auslassventile auf Bank 1, die einem Abschaltbefehl nicht folgen, obwohl ihr Steuerkreis elektrisch einwandfrei ist. Kein Hersteller dokumentiert den Code öffentlich. Warum das zählt und wie man es bemerkt, zeigt ein Ford-Patent: Öffnet an einem eigentlich verschlossenen Zylinder das Auslassventil weiter, zeichnet sich das im Abgasdruck ab; das Steuergerät kann den Zylinder dann wieder zuschalten, weitere Abschaltungen sperren und einen Fehler speichern. Bekannte Motoren schalten beide Ventile eines Zylinders gemeinsam, GM etwa legt solche Fehler unter eigenen Zylindercodes ab P3498 ab. Elektrisch gehört zu diesem Kreis P340C, die Funktion der Einlassseite ist P341A, Bank 2 P341D.","u":[["m","Auslassseitiger Stößel oder Kipphebel auf Bank 1 schaltet nicht"],["m","Zu wenig Öldruck oder aufgeschäumtes Öl"],["l","Auslass-Abschaltstellglied von Bank 1 klemmt"]],"s":["Motorkontrollleuchte an","Unruhiger Abgasklang im Teilzylinderbetrieb","Abschaltung ausgesetzt"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P340C","P341A","P341D","P3400","P3498"]},{"c":"P341D","t":"Abschaltung/Auslassventil Steuerkreis Funktion Bank 2","e":"Deactivation/Exhaust Valve Control Circuit Performance Bank 2","d":"P341D wird gesetzt, wenn die Auslassventile von Bank 2 falsch auf eine Ab- oder Zuschaltanforderung reagieren, obwohl die elektrische Seite intakt ist. Kein Hersteller dokumentiert den Code öffentlich. Entscheidend ist die Reihenfolge: In einer GM-Patentanmeldung hören die Auslassventile beim Abschalten vor den Einlassventilen auf zu arbeiten und setzen beim Zuschalten auch vor ihnen wieder ein, damit verbranntes Gas hinausgeschoben und keine Frischladung eingesperrt wird. GMs DFM-V8 legt laut NHTSA umgekehrt zuerst die Einlassseite still. Hinkt die Auslassseite hinterher, gerät die geplante Abfolge durcheinander. CARB verlangt eine Funktionsprüfung solcher Stellglieder. Der Kreiscode dieser Bank ist P340D, Bank 1 P341C, die Einlassfunktion auf Bank 2 P341B. Zu erwarten sind Leuchte, harte Moduswechsel und Mehrverbrauch.","u":[["m","Auslassstößel oder -kipphebel auf Bank 2 schaltet spät oder gar nicht"],["m","Öl zu dünn, zu alt oder zu wenig für schnelles Umschalten"],["l","Träges Ventil des Auslass-Stellglieds von Bank 2"]],"s":["Motorkontrollleuchte an","Stoß oder Schütteln beim Moduswechsel","Höherer Kraftstoffverbrauch"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P340D","P341C","P341B","P3497"]},{"c":"P3420","t":"Zylinder 3 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 3 Deactivation/Intake Valve Control Circuit High","d":"P3420 meldet, dass an der Steuerleitung für die Abschaltung von Zylinder 3 Versorgungsspannung liegt, wo das Steuergerät sie nach Masse ziehen will. Beim L84 von GM läuft der Test nur bei eingeschaltetem Low-Side-Ausgang: Eine Verbindung zur Batteriespannung unter 0,5 Ohm, bestätigt in 20 von 25 Proben, setzt einen Type-B-Code. Laut NHTSA-Untersuchung 2025 zu GMs DFM-V8 hat jeder Zylinder genau ein Öl-Magnetventil für die Stößel, angesteuert nach dem Peak-and-Hold-Prinzip; ein einziger Schluss legt also die Umschaltung des ganzen Zylinders lahm. Das Gen-IV-Steuergerät hat für dieses Ventil zusätzlich eine High-Side-Stufe mit eigenen Codes, was hilft, die defekte Kreishälfte einzugrenzen. P3419 deckt den Masseschluss ab. Der Motor arbeitet einfach mit allen acht Zylindern weiter.","u":[["h","Steuerleitung von Zylinder 3 berührt einen spannungsführenden Leiter"],["m","Windungsschluss in der Wicklung des Ventils von Zylinder 3"],["l","Ausgangstransistor im Motorsteuergerät beschädigt"]],"s":["Motorkontrollleuchte an","Sparbetrieb nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3417","P3418","P3419","P3424","P3428","P3412"]},{"c":"P3421","t":"Zylinder 3 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 3 Exhaust Valve Control Circuit/Open","d":"P3421 eröffnet die Auslassgruppe von Zylinder 3 und steht für einen unterbrochenen Kreis zu einem Stellglied, das nur die Auslassventile schaltet. Kein Hersteller dokumentiert diesen Code öffentlich. Motoren, die Zylinder 3 nachweislich stilllegen – etwa GMs V8 LTA und LT2 (Bulletin 20-NA-038) und der L84 –, lassen beide Ventile des Zylinders über einen Stößel schalten; eine Unterbrechung erscheint dort als P3417. Eine GM-Patentanmeldung zur Abschalt-Hardware behält ein einziges Öl-Schaltventil und legt nur die Nockensteuerzeiten so, dass die Auslassseite zuerst aussetzt und zuerst wiederkommt. Ein eigenes Auslass-Stellglied bräuchte die Durchgangsprüfung, die CARB für Ausgänge verlangt. Der Fahrer sähe eine Warnleuchte, und der Sparbetrieb fiele weg.","u":[["m","Gebrochene Ader oder lockerer Kontakt am Auslass-Stellglied von Zylinder 3"],["m","Wicklung des Auslass-Stellglieds unterbrochen"],["l","Fehler im Ausgang des Steuergeräts"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3422","P3423","P3424","P3417","P3413","P3429"]},{"c":"P3422","t":"Zylinder 3 Auslassventil Steuerung Funktion","e":"Cylinder 3 Exhaust Valve Control Performance","d":"P3422 käme zum Zug, falls bei Zylinder 3 die Auslassventile einen Befehl zum Abschalten oder Zuschalten übergehen, obwohl der Kreis fehlerfrei arbeitet. Kein Hersteller dokumentiert diesen Code öffentlich. Wie sich ein solcher Fehler erkennen lässt, zeigen Patente: In einem Ford-Patent verrät sich ein Auslassventil, das trotz Abschaltung weiter hebt, über den Verlauf des Abgasdrucks; die Steuerung schaltet den Zylinder dann wieder zu, sperrt weitere Abschaltungen und kann einen Code ablegen. Ein Delphi-Patent macht Ähnliches für die Einlassseite, indem es Druckpulse zeitlich mit dem Kurbelwinkel vergleicht. GM fasst beide Ventile von Zylinder 3 in einer mechanischen Prüfung zusammen, P349A. Ein undichtes Auslassventil pumpt Luft durch den kalten Zylinder, stört so die Gemischregelung und kann Fehlzündungen auf Zylinder 3 zählen lassen.","u":[["m","Auslassseitiger Schaltstößel oder Kipphebel von Zylinder 3 hängt"],["m","Ölstand oder Ölqualität außerhalb der Vorgabe"],["l","Verengter Ölkanal zum Auslass-Schaltelement"]],"s":["Unrunder Lauf im Teilzylinderbetrieb","Gemischregel- oder Fehlzündungscodes zusätzlich","Motorkontrollleuchte an"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3421","P3423","P3424","P3418","P349A","P0303","P3430"]},{"c":"P3423","t":"Zylinder 3 Auslassventil Steuerkreis niedrig","e":"Cylinder 3 Exhaust Valve Control Circuit Low","d":"P3423 weist auf einen Masseschluss in der Steuerleitung eines eigenen Auslass-Stellglieds an Zylinder 3 hin. Kein Hersteller dokumentiert diesen Code öffentlich; den Grund zeigt die NHTSA-Untersuchung 2025 zu GMs DFM-V8: Ein einziges Stößel-Öl-Magnetventil je Zylinder versorgt beide Stößel, Einlass und Auslass, einen getrennten Auslass-Ausgang gibt es also nicht. Für eben dieses Ventil an Zylinder 3 wertet GMs L84-Tabelle einen Widerstand unter einem halben Ohm zur Masse bei ruhendem Treiber als Fehler und nutzt dafür P3419. Auch GMs Displacement-on-Demand-Tabelle aus dem Jahr 2007 führt für Zylinder 3 nur einen Ventilkreis. Eine Bauart mit eigenem Auslass-Ausgang fiele unter die CARB-Pflicht, Kurzschlüsse zu erkennen. Folge: Warnleuchte, Zylinder 3 bleibt aktiv.","u":[["m","Leitung des Auslass-Stellglieds von Zylinder 3 mit Motormasse verbunden"],["m","Wicklung des Stellglieds hat Schluss zum Gehäuse"],["l","Fehlerhafte Endstufe im Steuergerät"]],"s":["Motorkontrollleuchte an","Kein Wechsel in den Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3421","P3422","P3424","P3419","P3431","P3415"]},{"c":"P3424","t":"Zylinder 3 Auslassventil Steuerkreis hoch","e":"Cylinder 3 Exhaust Valve Control Circuit High","d":"P3424 ist der Schlusspunkt für Zylinder 3 und steht für eine Steuerleitung eines Auslass-Stellglieds, die auf Versorgungsspannung liegt. Kein Hersteller dokumentiert diesen Code öffentlich. Am L84 von GM sieht man, wie weit sich ein gemeinsames Ventil auch ohne ihn überwachen lässt: Für Zylinder 3 prüft das Steuergerät einen Low-Side-Treiber unter P3417, P3419 und P3420 und einen High-Side-Treiber unter weiteren eigenen Codes – keiner davon betrifft nur den Auslass. Eine GM-Patentanmeldung erklärt den Grund: Ein hydraulisches Schaltventil je Zylinderpaar bedient Ein- und Auslass, die Reihenfolge legen die Nocken fest. Die nächstliegende dokumentierte Prüfung ist die hinter P3420, bei der eine Verbindung zur Versorgung unter einem halben Ohm bei aktivem Ausgang als Schluss gilt. Bemerkbar wäre nur die Leuchte.","u":[["m","Leitung des Auslass-Stellglieds an einer Versorgungsleitung durchgescheuert"],["m","Windungsschluss im Auslass-Stellglied von Zylinder 3"],["l","Ausgangsfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Motor läuft dauerhaft auf allen Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3421","P3422","P3423","P3420","P3432","P3416"]},{"c":"P3425","t":"Zylinder 4 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 4 Deactivation/Intake Valve Control Circuit/Open","d":"Zylinder 4 gehört bei der klassischen V8-Abschaltung zu den vier stillgelegten Zylindern, zusammen mit 1, 6 und 7 – bei GM (Active Fuel Management) ebenso wie beim Chrysler 5,7-l-Hemi mit MDS. Damit ist P3425 einer der am besten belegten Codes dieses Bereichs. GMs Tabellen 2019 für L84 und L86 melden eine Unterbrechung, wenn der Ausgang im ausgeschalteten Zustand mehr als 200 kOhm zeigt, 20 von 25 Messungen, Type B. Chrysler führt ihn als Abschalt-Steuerkreis Zylinder 4; ein STAR-Fall beschreibt, wie das Hitzeschild des fahrerseitigen Abgaskrümmers den Kabelbaum der Magnetventile durchscheuert, und verlangt mindestens 15 mm Abstand. P3427 und P3428 decken Schlüsse im selben Kreis ab.","u":[["h","Kabelbaum der Magnetventile vom Krümmer-Hitzeschild durchgescheuert (5,7-l-Hemi)"],["m","Unterbrochene Spule im Abschalt-Magnetventil von Zylinder 4"],["m","Korrodierter oder lockerer Stecker am Magnetventil"],["l","Steuergeräte-Software mit Update-Bedarf (Chrysler TSB 18-002-25)"]],"s":["Motorkontrollleuchte an","Motor bleibt im Achtzylinderbetrieb","Weitere Kreiscodes für Zylinder 1, 6 und 7, wenn der gemeinsame Kabelbaum beschädigt ist"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3426","P3427","P3428","P3401","P3441","P3449","P3497"]},{"c":"P3426","t":"Zylinder 4 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 4 Deactivation/Intake Valve Control Performance","d":"P3426 gehört zu den wenigen Funktionscodes dieses Bereichs, die Hersteller tatsächlich verwenden. FCA nennt ihn beim 6,4-l-Heavy-Duty-Hemi mit MDS Cylinder 4 Deactivation Control Performance; die Bulletins 18-082-16 und 18-036-20 führen ihn zusammen mit P3402, P3442 und P3450 und beheben ihn mit neuer PCM-Software. Ford legt ihn beim F-150 5,0 l (2025) ab: Bulletin 25-2487, ersetzt durch 26-2093, führt P3402 und P3426 auf ein verengtes Ölzulaufrohr der Abschaltventile der rechten Bank zurück, das unter dem Ventildeckel getauscht wird. GM prüft Zylinder 4 mechanisch stattdessen unter P349B. Kreisfehler sind P3425, P3427 und P3428. Die Leuchte geht an, der Motor kann unruhig laufen oder im Vollzylinderbetrieb bleiben.","u":[["h","Verengtes Ölzulaufrohr zu den Abschaltventilen (Ford 5,0 l, TSB 26-2093)"],["m","Steuergeräte-Software mit Update-Bedarf (FCA 6,4-l-Hemi)"],["m","Zu wenig oder verbrauchtes Motoröl"],["l","Abschaltbarer Stößel von Zylinder 4 klemmt"]],"s":["Motorkontrollleuchte an","Fehlzündung auf Zylinder 4 oder unruhiger Lauf","Dröhnen oder Ruckeln bei wenig Gas"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3425","P3427","P3428","P3402","P3442","P3450","P349B","P0304"]},{"c":"P3427","t":"Zylinder 4 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 4 Deactivation/Intake Valve Control Circuit Low","d":"P3427 wird gesetzt, wenn der Kreis des Abschalt-Magnetventils von Zylinder 4 einen Weg nach Masse hat. GM nutzt ihn bei mehreren V8 des Jahrgangs 2019: DFM-Motor L84, AFM-Motor L86 und LT4 der Corvette. Bei ausgeschaltetem Low-Side-Ausgang fällt jeder Massewiderstand unter einem halben Ohm durch die Prüfung; 20 von 25 Proben, Relaisspannung mindestens 11 V, 425 U/min (L84) bzw. 400 U/min (L86, LT4), Type B. In allen drei Tabellen nennt die Spalte mit den Fehlerkriterien Zylinder 1 – offenbar ein Kopierfehler. Für Chryslers Hemi mit MDS dokumentiert ein STAR-Fall ein Krümmer-Hitzeschild, das den Ventil-Kabelbaum aufreibt; berührt eine blanke Ader dort Metall, kann genau so ein Schluss entstehen. P3428 ist der Plusschluss.","u":[["h","Steuerleitung zum Ventil von Zylinder 4 bis auf Masse durchgescheuert, etwa am Hitzeschild"],["m","Ventil von Zylinder 4 mit innerem Schluss"],["l","Feuchtigkeit oder Öl im Ventilstecker"],["l","Beschädigter Treiber im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten","V4- bzw. Sparbetrieb schaltet nie zu","Weitere Kreiscodes anderer abschaltbarer Zylinder bei beschädigtem Kabelbaum"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3425","P3426","P3428","P3431","P3419","P3403"]},{"c":"P3428","t":"Zylinder 4 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 4 Deactivation/Intake Valve Control Circuit High","d":"P3428 bedeutet, dass die Steuerleitung des Abschalt-Magnetventils von Zylinder 4 auf Spannung liegt. GMs Bulletin 20-NA-038 nennt die Zylinder 1, 4, 6 und 7 als jene, die seine AFM-V8 für den V4-Betrieb stilllegen – Zylinder 4 ist also ein Standardkandidat. Die Tabellen 2019 für L84, L86 und LT4 der Corvette bewerten den Kreis bei eingeschaltetem Low-Side-Treiber: Ein Weg zur Versorgung unter einem halben Ohm gilt als Schluss, 20 Fehler in 25 Proben ergeben einen Type-B-Eintrag und die Leuchte nach zwei Fahrten. Weil die Low-Side-Stufe den Strom nach Masse führt, kann eine auf Batteriespannung hängende Leitung den Ausgang überlasten; nach der Reparatur gehört daher auch das Steuergerät geprüft. P3427 ist der Masseschluss, P3425 die Unterbrechung. Bis zur Reparatur arbeiten alle Zylinder.","u":[["h","Steuerleitung von Zylinder 4 mit einer 12-V-Leitung verbunden"],["m","Zu niederohmige Wicklung im Ventil von Zylinder 4"],["l","Überlastete Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Kein V4- oder Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3425","P3426","P3427","P3432","P3420","P3404"]},{"c":"P3429","t":"Zylinder 4 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 4 Exhaust Valve Control Circuit/Open","d":"P3429 bezeichnet eine Unterbrechung im Kreis eines Stellglieds, das nur die Auslassventile von Zylinder 4 schaltet. Kein Hersteller dokumentiert diesen Code öffentlich, obwohl kaum ein Zylinder so oft abgeschaltet wird: GMs AFM-V8 (Bulletin 20-NA-038), der Hemi mit MDS und die Vierzylinder von Mazda CX-5 und Mazda6 mit Abschaltung legen Zylinder 4 still; Mazdas Hinweis SA-041/18 nennt die Zylinder 1 und 4 als Abschaltbereich, in dem Kipphebel herausfallen können. Bei der GM-Bauart, die NHTSA 2025 untersucht hat, betätigt ein Magnetventil pro Zylinder beide Stößel, Ein- wie Auslass,, eine unterbrochene Leitung wird daher als P3425 gemeldet. Eine Anordnung mit eigenem Auslass-Ausgang schuldete CARB dennoch eine Durchgangsprüfung. P3430 bis P3432 ergänzen diese Auslassgruppe.","u":[["m","Unterbrochener Leiter oder herausgedrückter Pin zum Auslass-Stellglied von Zylinder 4"],["m","Spule des Auslass-Stellglieds durchgebrannt"],["l","Ausgang des Steuergeräts schaltet nicht"]],"s":["Motorkontrollleuchte an","Sparmodus inaktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3430","P3431","P3432","P3425","P3421","P3437"]},{"c":"P3430","t":"Zylinder 4 Auslassventil Steuerung Funktion","e":"Cylinder 4 Exhaust Valve Control Performance","d":"P3430 deckte Auslassventile an Zylinder 4 ab, die gegen den Befehl weiter öffnen oder geschlossen bleiben, bei elektrisch intaktem Kreis. Kein Hersteller dokumentiert diesen Code öffentlich. Ford zeigt beide Seiten des Problems: In einem Ford-Patent fällt ein Auslassventil, das trotz Abschaltung öffnet, durch veränderten Abgasdruck auf; die Steuerung schaltet den Zylinder daraufhin wieder zu und legt einen Code ab; in der Praxis meldet der F-150 5,0 l (2025) einen Schaltfehler an Zylinder 4 aber als P3426 und führt ihn auf ein verengtes Ölzulaufrohr der Ventile zurück (Bulletin 26-2093). Bleibt ein Auslassventil nicht zu, gelangt Frischluft zu Katalysator und Lambdasonden – sichtbar als Gemischfehler, Fehlzündungszähler und Vibrationen.","u":[["m","Behinderte Ölversorgung der Schaltelemente von Zylinder 4"],["m","Auslassstößel oder Kipphebel von Zylinder 4 wechselt den Zustand nicht"],["l","Öl zu dünn, zu alt oder zu wenig"]],"s":["Vibrationen im Teilzylinderbetrieb","Codes für mageres oder fettes Gemisch","Motorkontrollleuchte an"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3429","P3431","P3432","P3426","P349B","P0304","P3438"]},{"c":"P3431","t":"Zylinder 4 Auslassventil Steuerkreis niedrig","e":"Cylinder 4 Exhaust Valve Control Circuit Low","d":"P3431 meldet eine Leitung zum Auslass-Stellglied von Zylinder 4 mit Masseschluss. Kein Hersteller dokumentiert diesen Code öffentlich. Zylinder 4 wird zwar beim Hemi mit MDS von Chrysler ebenso abgeschaltet wie bei GMs V8 mit AFM oder DFM, doch diese Motoren arbeiten mit einem einzigen Magnetventil je Zylinder; ihre Bulletins und Tabellen führen deshalb nur einlassseitige Kreiscodes: Das Ram-Software-Bulletin 18-002-25 von 2025 nennt P3425 neben P3401, P3441 und P3449, und GMs L84-Tabelle 2019 nutzt P3427 für einen Masseschluss unter 0,5 Ohm bei ausgeschaltetem Treiber, 20 von 25 Proben, Type B. Das ist die nächstliegende dokumentierte Prüfung; für einen eigenen Auslass-Ausgang verlangte CARB dieselbe Art der Schlusserkennung. Sichtbar wären eine Warnleuchte und keine Zylinderabschaltung.","u":[["m","Leitung des Auslass-Stellglieds von Zylinder 4 liegt an Block oder Halter auf Masse"],["m","Innerer Masseschluss im Auslass-Stellglied"],["l","Treiberfehler im Steuergerät"]],"s":["Motorkontrollleuchte an","Motor bleibt auf allen Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3429","P3430","P3432","P3427","P3423","P3439"]},{"c":"P3432","t":"Zylinder 4 Auslassventil Steuerkreis hoch","e":"Cylinder 4 Exhaust Valve Control Circuit High","d":"P3432 ist der letzte Code des Blocks für Zylinder 4 und meint ein Auslass-Stellglied, dessen Ansteuerung an Versorgungsspannung hängt. Kein Hersteller dokumentiert diesen Code öffentlich. Das einlassseitige Gegenstück P3428 ist gut belegt: In GMs Unterlagen 2019 zu L84, L86 und dem LT4 der Corvette gilt ein Versorgungsweg unter einem halben Ohm bei leitendem Low-Side-Treiber als Schluss und wird als Type B abgelegt. Die Auslassventile sind bei diesen Motoren nicht vergessen, sie schalten schlicht mit demselben Stößelöl. In einer GM-Patentanmeldung bedient ein einziges Hydraulikventil beide Seiten; die Nockensteuerzeiten lassen die Auslassseite früher aussetzen und auch früher wieder arbeiten als die Einlassseite. Ohne eigenen Auslass-Ausgang hat dieser Code nichts zu überwachen. Zu erwarten ist nur die Leuchte.","u":[["m","Leitung des Auslass-Stellglieds von Zylinder 4 hat Kontakt zur Batteriespannung"],["m","Spule des Auslass-Stellglieds mit Windungsschluss"],["l","Endstufe des Motorsteuergeräts defekt"]],"s":["Motorkontrollleuchte an","Abschaltung nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3429","P3430","P3431","P3428","P3424","P3440"]},{"c":"P3433","t":"Zylinder 5 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 5 Deactivation/Intake Valve Control Circuit/Open","d":"P3433 meldet einen unterbrochenen Steuerkreis zum Abschaltventil von Zylinder 5, und GM nutzt ihn über drei Generationen. Schon der V6 mit Displacement on Demand von 2007, der die Zylinder 1, 3 und 5 stilllegte, erkannte Schluss oder Unterbrechung nach 30 Fehlern in 100 Messungen im 250-ms-Takt oberhalb 800 U/min. Beim 3,6-l-V6 (LGX, LGZ) ist Zylinder 5 einer der abschaltbaren Zylinder; GM brachte P3433 dort mit Öl in Verbindung, das am Kipphebel-Steuerventil im Nockenwellendeckel austritt. Der V8 L84 von 2019 prüft jeden Zylinder mit einer Grenze von 200 kOhm. Jedes Mal ist es ein Type-B-Code. P3434 bis P3436 sind Funktions- und Schlusscodes desselben Zylinders.","u":[["h","Öl tritt am Steuerventil von Zylinder 5 aus und gelangt in den Stecker (GM 3,6-l-V6)"],["m","Leitungsbruch oder aufgeweiteter Kontakt im Ventilkreis"],["m","Unterbrochene Spule im Magnetventil von Zylinder 5"],["l","Ausgangsfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Ölaustritt am Steuerventil im Ventildeckel (V6)","Teilzylinderbetrieb wird nicht mehr genutzt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3434","P3435","P3436","P3437","P3409","P3400","P0305"]},{"c":"P3434","t":"Zylinder 5 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 5 Deactivation/Intake Valve Control Performance","d":"Mit P3434 hat das Steuergerät festgestellt, dass Zylinder 5 nicht richtig ab- oder zuschaltet, während der Steuerkreis in Ordnung ist. Kein Hersteller dokumentiert diesen Code öffentlich. GMs L84 führt den gleichwertigen Test unter P349C: Der Saugrohrdruck bleibt zu hoch, obwohl Zylinder 5 abgeschaltet sein soll – seine Ventile arbeiten also weiter. Für 3,6-l-V6-Motoren beschreibt GMs Bulletin 21-NA-036 das Bild aus der Werkstatt: Fehlzündungen auf Zylinder 5 (P0305), teils nur nach einer Teilzylinderphase, durch Öl, das am Steuerventil vorbeiläuft, oder nicht einrastende Kipphebel; zu prüfen ist auch eine in der Bohrung abgebrochene Ventilspitze. Leitungsfehler dieses Zylinders sind P3433, P3435 und P3436.","u":[["h","Öl läuft an der Dichtung des Steuerventils von Zylinder 5 vorbei"],["m","Schaltbarer Kipphebel oder Stößel von Zylinder 5 rastet nicht ein"],["l","Ventilspitze in der Bohrung abgebrochen"],["l","Zu wenig oder gealtertes Motoröl"]],"s":["Fehlzündungen auf Zylinder 5 (P0305)","Motorkontrollleuchte an","Schütteln nach Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3433","P3435","P3436","P3438","P349C","P0305","P3400"]},{"c":"P3435","t":"Zylinder 5 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 5 Deactivation/Intake Valve Control Circuit Low","d":"P3435 meldet einen Masseschluss an der Steuerleitung des Abschaltventils von Zylinder 5. GM belegt den Code gleich zweimal: in den Tabellen 2019 für den V8 L84 mit unter 0,5 Ohm nach Masse bei ausgeschalteter Endstufe, 20 von 25 Messungen im 250-ms-Takt und Type B, und in einer Engineering-Information zu 3,6-l-V6-Motoren (LGX, LGZ), in der P3435 neben P3433 und P3409 auftaucht, wenn am Kipphebel-Steuerventil Öl austritt. Öl, das in den Stecker kriecht, kann genau einen solchen Kriechstrompfad bilden. P3433 ist die Unterbrechung, P3436 der Plusschluss, P3434 ein mechanischer Fehler. Im Alltag bleibt der Motor einfach auf allen Zylindern.","u":[["h","Öl im Stecker des Ventils von Zylinder 5 bildet einen Kriechstrompfad (GM 3,6-l-V6)"],["m","Steuerleitung mit Masseschluss"],["m","Kurzgeschlossenes Magnetventil von Zylinder 5"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Ölfeuchte am Ventildeckel rund um das Steuerventil (V6)","Keine spritsparende Zylinderabschaltung"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3433","P3434","P3436","P3439","P3409","P3400"]},{"c":"P3436","t":"Zylinder 5 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 5 Deactivation/Intake Valve Control Circuit High","d":"P3436 ist der Plusschluss-Code für das Abschaltventil von Zylinder 5. Öffentlich belegt ist er bei GM für den V8 L84 (2019), dessen Dynamic Fuel Management für jeden der acht Zylinder ein eigenes Stößel-Öl-Magnetventil nutzt. Das Steuergerät prüft die Leitung bei eingeschalteter Low-Side-Endstufe; ein Widerstand unter 0,5 Ohm zur Versorgungsspannung gilt als Fehler, bestätigt durch 20 von 25 Messungen alle 250 ms bei mindestens 11 V und 425 U/min. Als Type-B-Code schaltet er die Lampe nach zwei Fahrten in Folge ein. Da sich das Ventil dann nicht kontrolliert schalten lässt, nimmt das Steuergerät Zylinder 5 aus der Abschaltung. Geschwister: P3433 Unterbrechung, P3435 Masseschluss, P3434 Funktion.","u":[["h","Steuerleitung berührt eine Spannungsversorgung"],["m","Windungsschluss im Magnetventil von Zylinder 5"],["l","Defekt der Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten","Dynamic Fuel Management abgeschaltet"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3433","P3434","P3435","P3440","P3400"]},{"c":"P3437","t":"Zylinder 5 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 5 Exhaust Valve Control Circuit/Open","d":"P3437 ist für eine Unterbrechung im Kreis eines gesonderten Auslassventil-Stellglieds an Zylinder 5 vorgesehen. Kein Hersteller dokumentiert diesen Code öffentlich. GM, der Hauptnutzer der Abschaltcodes für Zylinder 5 (V6 von 2007, 3,6-l-V6, V8 L84), veröffentlicht nur die Einlassgruppe P3433 bis P3436, weil seine Systeme beide Ventile eines Zylinders gemeinsam schalten; laut NHTSA-Beschreibung des Dynamic Fuel Management versorgt jedes Magnetventil Einlass- und Auslassstößel. CARB erwartet dennoch für jedes abgasrelevante Stellglied eine Durchgangsprüfung – genau das würde dieser Code melden. P3438 bis P3440 sind die übrigen Auslasscodes von Zylinder 5, P3433 die Unterbrechung auf der Einlassseite.","u":[["m","Leitungs- oder Steckerbruch zum Auslass-Stellglied von Zylinder 5"],["m","Unterbrochene Stellglied-Spule"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3438","P3439","P3440","P3433","P3400"]},{"c":"P3438","t":"Zylinder 5 Auslassventil Steuerung Funktion","e":"Cylinder 5 Exhaust Valve Control Performance","d":"P3438 beschreibt eine Auslassseite von Zylinder 5, die ab- oder zugeschaltet werden soll, aber bei intaktem Kreis nicht folgt. Kein Hersteller dokumentiert diesen Code öffentlich. Zwei Patente zeigen, warum die Auslassseite zählt: in einer GM-Patentanmeldung schaltet ein gemeinsames Ventil die Auslassventile vor den Einlassventilen ab und auch vor ihnen wieder zu, ein nachhinkender Auslassstößel bricht diese Reihenfolge; Ford erkennt ein nach der Abschaltung weiter öffnendes Auslassventil am Abgasdruck. Öffnet das Auslassventil weiter, während der Zylinder abgeschaltet ist, kann der Motor unrund laufen. GMs DFM-Motoren melden einen Zylinder, dessen Ventile aktiv bleiben, als P349C. Die elektrischen Codes dieses Kanals sind P3437, P3439 und P3440.","u":[["m","Auslass-Stößel oder -Kipphebel von Zylinder 5 schaltet träge"],["m","Zu geringer Öldruck zum Umschalten"],["l","Ventil des Auslass-Stellglieds klemmt"]],"s":["Motorkontrollleuchte an","Unruhe oder Geräusche bei abgeschalteten Zylindern"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3437","P3439","P3440","P3434","P349C"]},{"c":"P3439","t":"Zylinder 5 Auslassventil Steuerkreis niedrig","e":"Cylinder 5 Exhaust Valve Control Circuit Low","d":"P3439 würde einen Masseschluss im Steuerkreis eines eigenen Auslassventil-Stellglieds an Zylinder 5 melden. Kein Hersteller dokumentiert diesen Code öffentlich, eine Schwelle ist nicht veröffentlicht. Der nächste belegte Bezug ist das einlassseitige P3435, das GMs L84 bei unter 0,5 Ohm nach Masse und ausgeschalteter Endstufe nach 20 von 25 Messungen setzt. Die CARB-Regeln für Ausgangskomponenten verlangen genau diese Kurzschlussprüfung bei jedem abgasrelevanten Stellglied. Motoren, die beide Ventile von Zylinder 5 über ein Magnetventil schalten, melden einen Schluss nur über P3435. Auslassseitige Geschwister sind P3437 (Unterbrechung), P3438 (Funktion) und P3440 (Plusschluss).","u":[["m","Steuerleitung des Auslass-Stellglieds an Masse"],["m","Innen kurzgeschlossenes Auslass-Stellglied"],["l","Defekter Ausgang im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Motor läuft nur noch mit allen Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3437","P3438","P3440","P3435","P3400"]},{"c":"P3440","t":"Zylinder 5 Auslassventil Steuerkreis hoch","e":"Cylinder 5 Exhaust Valve Control Circuit High","d":"P3440 schließt den Block von Zylinder 5 ab und steht für ein zu hohes Signal, meist einen Schluss nach Versorgungsspannung, im Kreis eines gesonderten Auslassventil-Stellglieds. Kein Hersteller dokumentiert diesen Code öffentlich. Sinn ergibt der Code nur bei einem eigenen Auslass-Stellglied; ein Ford-Patent etwa prüft am Abgasdruck, ob ein Auslassventil nach der Abschaltung noch öffnet. Heutige Serienmotoren, die Zylinder 5 abschalten, steuern beide Ventile über ein Magnetventil; GM meldet einen Plusschluss dort als P3436, geprüft bei eingeschalteter Endstufe mit einer Grenze von 0,5 Ohm. Hätte ein eigener Auslasskanal Plusschluss, würde das Steuergerät die Abschaltung sperren und die Lampe einschalten. Vergleiche P3437, P3438 und P3439.","u":[["m","Steuerleitung des Auslass-Stellglieds mit Plus verbunden"],["m","Windungsschluss in der Stellglied-Spule"],["l","Endstufenfehler im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3437","P3438","P3439","P3436","P3400"]},{"c":"P3441","t":"Zylinder 6 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 6 Deactivation/Intake Valve Control Circuit/Open","d":"Zylinder 6 gehört zu beiden klassischen V8-Abschaltgruppen, P3441 tritt also an echten Motoren auf. Bei GMs Active Fuel Management, das die Zylinder 1, 7, 6 und 4 stilllegt, führen die Tabellen 2019 den Code für den Pick-up-Motor L86 und den LT4 der Corvette: Zeigt der Ausgang bei abgeschalteter Low-Side-Endstufe mehr als 200 kOhm gegen Masse, gilt das als Unterbrechung; 20 Fehler unter 25 Proben (alle 250 ms, ab 400 U/min) speichern einen Type-B-Code. Der L84 mit Dynamic Fuel Management prüft genauso, ab 425 U/min. Chrysler nennt P3441 beim 5,7-l-Hemi mit MDS; ein STAR-Fall macht ein Hitzeschild verantwortlich, das den Kabelbaum der Magnetventile durchscheuert. Schlüsse in diesem Kreis melden P3443 und P3444.","u":[["h","Kabelbaum der Magnetventile gebrochen oder durchgescheuert (beim 5,7-l-Hemi durch das Krümmer-Hitzeschild)"],["m","Spule im Abschalt-Magnetventil von Zylinder 6 unterbrochen"],["m","Lockerer oder korrodierter Stecker am Magnetventil von Zylinder 6"],["l","Steuergeräte-Software mit Update-Bedarf (Chrysler TSB 18-002-25)"]],"s":["Motorkontrollleuchte an","Motor wechselt nicht mehr in den Vierzylinderbetrieb","Eventuell auch Kreiscodes für Zylinder 1, 4 und 7, wenn der gemeinsame Kabelbaum beschädigt ist"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3442","P3443","P3444","P3445","P3449","P3400","P3497","P0306"]},{"c":"P3442","t":"Zylinder 6 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 6 Deactivation/Intake Valve Control Performance","d":"P3442 meldet, dass Zylinder 6 sich nicht wie befohlen ab- oder wieder zuschaltet, obwohl sein Steuerkreis elektrisch in Ordnung ist. FCA nutzt den Code als „Cylinder 6 Deactivation Control Performance“ beim 6,4-l-Heavy-Duty-Hemi mit MDS in RAM 2500 bis 5500: Die Bulletins 18-082-16 und 18-036-20 nennen ihn mit P3402, P3426 und P3450 bei leuchtender MIL und beheben ihn per neuer Motorsoftware. Ford speichert ihn beim F-150 5,0 l, gebaut Januar bis April 2025: Bulletin 25-2487, ersetzt durch 26-2093, führt P3442 und P3450 auf ein verengtes Ölzulaufrohr der Abschalt-Magnetventile der linken Bank zurück, das unter dem Ventildeckel erneuert wird. GMs L84 bewertet Zylinder 6 unter dem eigenen Code P349D. Elektrische Fehler desselben Kanals sind P3441, P3443 und P3444.","u":[["m","Veraltete Motorsoftware (FCA 6,4 l, Bulletins 18-082-16 und 18-036-20)"],["m","Verengtes Ölzulaufrohr zu den Magnetventilen der linken Bank (Ford 5,0 l, TSB 26-2093)"],["m","Zu wenig, falsches oder verbrauchtes Öl, der Druck baut sich zu langsam auf"],["l","Abschaltstößel von Zylinder 6 verriegelt oder entriegelt nicht"]],"s":["Motorkontrollleuchte an","Ruck oder Vibration beim Wechsel zwischen acht und vier Zylindern","Fehlzündungen auf Zylinder 6 (P0306)","Verbrauch steigt, weil die Abschaltung gesperrt ist"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3441","P3443","P3444","P3450","P3402","P3426","P349D","P0306"]},{"c":"P3443","t":"Zylinder 6 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 6 Deactivation/Intake Valve Control Circuit Low","d":"Hier hat das Steuergerät die Steuerleitung des Abschalt-Magnetventils von Zylinder 6 auf Masse gezogen vorgefunden. GM beschreibt die Prüfung für seine V8-Motoren 2019 (L84, L86 und LT4 der Corvette): Bei ausgeschalteter Low-Side-Endstufe ist ein Widerstand unter 0,5 Ohm gegen Masse ein Fehler; 20 Treffer unter 25 Prüfungen bei mindestens 11 V am Powertrain-Relais speichern einen Type-B-Code. Laut GM tragen manche Steuergeräte im selben Moment auch den Unterbrechungscode P3441 ein – das Paar beweist also nicht zwei getrennte Fehler. Beim L84 hat jedes Ventil zusätzlich eine High-Side-Versorgung; ein Masseschluss dort läuft unter GMs eigenem Code P3114. P3444 ist der Plusschluss dieses Kanals. Bis zur Reparatur bleibt die Zylinderabschaltung aus.","u":[["h","Isolierung der Steuerleitung von Zylinder 6 bis auf Masse durchgescheuert"],["m","Magnetventil von Zylinder 6 innen gegen sein Gehäuse kurzgeschlossen"],["l","Feuchtigkeit oder Öl überbrückt die Kontakte des Ventilsteckers"],["l","Endstufe im Motorsteuergerät beschädigt"]],"s":["Motorkontrollleuchte ab der zweiten fehlerhaften Fahrt an","Vierzylinderbetrieb nicht mehr verfügbar","Bei manchen GM-Steuergeräten gleichzeitig P3441 gespeichert"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3441","P3442","P3444","P3447","P3497"]},{"c":"P3444","t":"Zylinder 6 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 6 Deactivation/Intake Valve Control Circuit High","d":"P3444 wird gesetzt, wenn der Ausgang, der das Abschalt-Magnetventil von Zylinder 6 gegen Masse schaltet, im eingeschalteten Zustand weiterhin Versorgungsspannung sieht – die Leitung hat dann Verbindung zu Plus statt über die Spule zu führen. GM prüft das bei den V8-Motoren L84, L86 und LT4 von 2019 mit einer Grenze von 0,5 Ohm zur Versorgung, 20 Fehlern in 25 Proben im 250-ms-Abstand und Type-B-Lampenlogik. Beim L84, dessen Ventile zusätzlich eine geschaltete High-Side-Versorgung haben, trägt ein Plusschluss dort den eigenen GM-Code P3115. Weil das Steuergerät das Ventil nicht mehr bestromen kann, zündet Zylinder 6 einfach weiter, und der Motor verzichtet auf den Vierzylinderbetrieb. Vergleiche P3441 (Unterbrechung) und P3443 (Masseschluss).","u":[["h","Steuerleitung von Zylinder 6 berührt im Kabelbaum eine Versorgungsleitung"],["m","Windungsschluss in der Spule des Magnetventils von Zylinder 6"],["l","Fehlerhafte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Motor läuft dauerhaft auf allen acht Zylindern","Etwas höherer Verbrauch bei geringer Last"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3441","P3442","P3443","P3448","P3497"]},{"c":"P3445","t":"Zylinder 6 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 6 Exhaust Valve Control Circuit/Open","d":"P3445 ist für einen Bruch in der Verkabelung eines separaten Stellglieds gedacht, das die Auslassventile von Zylinder 6 steuern würde. Kein Hersteller dokumentiert diesen Code öffentlich. Die Motoren, die heute Zylinder 6 abschalten – GMs V8 mit AFM und DFM sowie Chryslers Hemi mit MDS –, veröffentlichen für diesen Zylinder nur Codes der Einlassseite (P3441, bei GM zusätzlich P3443 und P3444). Die NHTSA-Beschreibung der DFM-Technik von GM zeigt den Grund: Ein einziges Magnetventil je Zylinder leitet Öl zu Einlass- und Auslassstößel gemeinsam, die danach nacheinander entriegeln. Ein Motor mit eigenen Stellgliedern auf der Auslassseite müsste deren Leitungen nach CARB-Regeln für Ausgangskomponenten auf Durchgang prüfen – genau diesen Fehler benennt der Code. P3446 bis P3448 vervollständigen die Auslassgruppe.","u":[["m","Leitungsbruch oder lockerer Stecker am Auslass-Stellglied von Zylinder 6"],["m","Spule des Stellglieds unterbrochen"],["l","Endstufe im Steuergerät fehlerhaft"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung abgeschaltet"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3446","P3447","P3448","P3441","P3497"]},{"c":"P3446","t":"Zylinder 6 Auslassventil Steuerung Funktion","e":"Cylinder 6 Exhaust Valve Control Performance","d":"P3446 steht für ein Auslassventil an Zylinder 6, das einem Ab- oder Zuschaltbefehl nicht folgt, obwohl sein Kreis intakt ist. Kein Hersteller dokumentiert diesen Code öffentlich. GM überwacht einen eng verwandten Fehler unter eigener Nummer: Beim L84 von 2019 sucht P318E („Cylinder 6 Trapped High Pressure Exhaust Charge“) nach einem Auslassventil, das nicht öffnet und das verbrannte Gas nicht hinauslässt. Erkannt wird das an Drehungleichförmigkeiten der Kurbelwelle in 66 von 100 Proben, Type B, mit sofortiger Schutzreaktion. Ein Ford-Patent behandelt den umgekehrten Fall, ein Auslassventil, das nach dem Abschalten weiter öffnet, und erkennt ihn am Abgasdruck. Die elektrischen Codes dieses Auslasskanals sind P3445, P3447 und P3448.","u":[["m","Auslassstößel von Zylinder 6 schaltet verspätet oder gar nicht"],["m","Öldruck zu niedrig für sicheres Umschalten"],["l","Steuerventil der Auslassseite klemmt"]],"s":["Motorkontrollleuchte an","Klopfähnliches Geräusch oder Vibration beim Wiederzuschalten des Zylinders","Mögliche Fehlzündungen auf Zylinder 6 (P0306)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3445","P3447","P3448","P3442","P349D","P0306"]},{"c":"P3447","t":"Zylinder 6 Auslassventil Steuerkreis niedrig","e":"Cylinder 6 Exhaust Valve Control Circuit Low","d":"P3447 beschreibt eine Steuerleitung zu einem eigenen Auslassventil-Stellglied an Zylinder 6, die Schluss nach Masse hat. Kein Hersteller dokumentiert diesen Code öffentlich. GM, der einzige Hersteller mit vollständig veröffentlichten Kreiscodes für Zylinder 6, schaltet beide Ventile des Zylinders über ein Magnetventil und meldet einen Masseschluss als P3443 auf der Einlassseite: unter 0,5 Ohm gegen Masse bei ausgeschalteter Endstufe, 20 von 25 Proben, Type B. Eine vergleichbare Prüfung käme hier zum Einsatz, denn CARB verlangt eine Kreisüberwachung für jeden abgasrelevanten Ausgang. Laut NHTSA sperrt GM die Abschaltung, sobald ein Kreisfehler an einer Ventil-Endstufe vorliegt; praktisch läuft der Motor also auf allen Zylindern. P3445 (Unterbrechung) und P3448 (Plusschluss) sind die benachbarten Auslasscodes.","u":[["m","Leitung des Auslass-Stellglieds von Zylinder 6 am Motor durchgescheuert"],["m","Innerer Masseschluss im Auslass-Stellglied"],["l","Beschädigte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Motor bleibt im Vollzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3445","P3446","P3448","P3443","P3497"]},{"c":"P3448","t":"Zylinder 6 Auslassventil Steuerkreis hoch","e":"Cylinder 6 Exhaust Valve Control Circuit High","d":"Hätte Zylinder 6 ein eigenes Auslassventil-Stellglied, meldete P3448 einen Schluss seiner Steuerleitung nach Batteriespannung. Kein Hersteller dokumentiert diesen Code öffentlich. Eine GM-Patentanmeldung zur Zylinderabschaltung schaltet beide Seiten über ein gemeinsames Hydraulikventil und lässt die Auslassventile nur zuerst ab- und auch zuerst wieder zuschalten – eine getrennte Auslasssteuerung zeigt sie nicht. Auch GMs Serien-V8 legen beide Stößel auf ein Magnetventil und veröffentlichen für einen Plusschluss an Zylinder 6 nur P3444. Dessen Prüfung – unter 0,5 Ohm zur Versorgung bei eingeschalteter Endstufe, 20 von 25 Proben – zeigt, wie ein solcher Fehler bewertet würde. Ist das Stellglied unbrauchbar, wird die Abschaltung gesperrt. P3445 bis P3447 sind die Geschwistercodes der Auslassseite.","u":[["m","Leitung des Auslass-Stellglieds berührt eine Versorgungsleitung"],["m","Windungsschluss in der Spule des Auslass-Stellglieds von Zylinder 6"],["l","Endstufe des Motorsteuergeräts fehlerhaft"]],"s":["Motorkontrollleuchte an","Kein Wechsel in den Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3445","P3446","P3447","P3444","P3497"]},{"c":"P3449","t":"Zylinder 7 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 7 Deactivation/Intake Valve Control Circuit/Open","d":"P3449 bedeutet: Das Steuergerät findet keinen Durchgang mehr im Kreis zum Abschalt-Magnetventil von Zylinder 7. Chrysler belegt den Code beim 5,7-l-Hemi mit MDS gleich zweimal. Ein Bulletin von 2025 zum RAM 1500 eTorque (Modelljahr 2023) nennt ihn neben Fehlzündungen auf Zylinder 7 (P0307) und behebt ihn mit neuer PCM-Software. Ein STAR-Fall führt P3449 an erster Stelle, wenn das Hitzeschild des fahrerseitigen Krümmers den MDS-Kabelbaum hinten am Zylinderkopf durchgescheuert hat. GM nutzt den Code bei AFM-V8 (L86, LT4 der Corvette) und beim DFM-Motor L84: mehr als 200 kOhm im ausgeschalteten Zustand, 20 von 25 Proben, Type B. P3451 und P3452 melden Schlüsse, P3450 einen mechanischen Fehler an Zylinder 7.","u":[["h","MDS-Kabelbaum hinten am fahrerseitigen Zylinderkopf vom Krümmer-Hitzeschild durchgescheuert (5,7-l-Hemi)"],["m","Spule des Magnetventils von Zylinder 7 unterbrochen"],["m","Stecker am Magnetventil locker oder korrodiert"],["l","PCM-Kalibrierung mit Update-Bedarf (Chrysler TSB 18-002-25)"]],"s":["Motorkontrollleuchte an","Motor bleibt im Achtzylinderbetrieb","Unrunder Leerlauf oder Fehlzündungen auf Zylinder 7 (P0307) beim 5,7-l-Hemi"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3450","P3451","P3452","P3453","P3441","P3400","P3497","P0307"]},{"c":"P3450","t":"Zylinder 7 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 7 Deactivation/Intake Valve Control Performance","d":"P3450 meldet, dass Zylinder 7 sich nicht wie befohlen ab- oder zuschaltet, obwohl der Kreis seines Magnetventils in Ordnung ist. FCA führt ihn als „Cylinder 7 Deactivation Control Performance“ beim 6,4-l-Heavy-Duty-Hemi mit MDS (RAM 2500 bis 5500, Bulletins 18-082-16 und 18-036-20): Die MIL leuchtet, eine neue Motorsoftware behebt den Fehler; eine wahlweise Kalibrierung mildert zudem Dröhnen und Ruckeln im MDS-Betrieb. Beim F-150 5,0 l von 2025 nennt Fords Bulletin 26-2093, Nachfolger von 25-2487, ihn zusammen mit P3442 und lässt das Ölzulaufrohr der Magnetventile der linken Bank unter dem Ventildeckel tauschen. In GMs System verschiebt laut NHTSA Öldruck Sperrstifte, sodass sich der Stößelkörper bewegt, ohne das Ventil zu öffnen. GMs L84 nutzt P349E. Elektrische Fehler: P3449, P3451, P3452.","u":[["m","Verengtes Ölzulaufrohr zu den Magnetventilen der linken Bank (Ford 5,0 l, TSB 26-2093)"],["m","Veraltete Motorsoftware (FCA 6,4 l, Bulletins 18-082-16 und 18-036-20)"],["m","Sperrstifte in einem Stößel von Zylinder 7 klemmen durch Verschleiß oder Schmutz"],["m","Zu wenig oder gealtertes Öl verzögert das Umschalten"]],"s":["Motorkontrollleuchte an","Tickern aus dem Ventiltrieb","Fehlzündungen auf Zylinder 7 (P0307)","Teilzylinderbetrieb abgeschaltet"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3449","P3451","P3452","P3442","P3402","P3426","P349E","P0307"]},{"c":"P3451","t":"Zylinder 7 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 7 Deactivation/Intake Valve Control Circuit Low","d":"P3451 heißt, dass die geschaltete Masseleitung des Abschalt-Magnetventils von Zylinder 7 irgendwo auf ihrem Weg Kontakt zur Masse hat. GM beschreibt die Prüfung für die Pick-up-Motoren L84 und L86 sowie den LT4 der Corvette (2019): Endstufe aus, weniger als 0,5 Ohm gegen Masse, 20 Treffer in 25 Proben im 250-ms-Takt, Type B – die Lampe geht also nach der zweiten fehlerhaften Fahrt an. Nach GM-Angabe tragen bestimmte Steuergeräte den Unterbrechungscode P3449 mit ein; beide Codes zusammen müssen daher keine zwei Fehler bedeuten. Beim L84 meldet die High-Side-Versorgung desselben Ventils einen Masseschluss unter eigenem Code P3117. P3452 ist der Plusschluss dieses Kanals, P3450 der mechanische Fehler.","u":[["h","Steuerleitung von Zylinder 7 gequetscht oder bis auf Masse durchgescheuert"],["m","Innerer Schluss im Magnetventil von Zylinder 7"],["l","Öl oder Wasser im Stecker des Magnetventils"],["l","Defekte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte nach zwei Fahrten an","Eventuell zusätzlich P3449 gespeichert","Kein Vierzylinderbetrieb, höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3449","P3450","P3452","P3455","P3400"]},{"c":"P3452","t":"Zylinder 7 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 7 Deactivation/Intake Valve Control Circuit High","d":"Anders als Unterbrechung und Masseschluss kann GM P3452 nur erkennen, solange die Endstufe für Zylinder 7 eingeschaltet ist: Ein Schluss nach Versorgungsspannung zeigt sich als Ausgang, der nicht auf Masse zieht, obwohl er es soll. Die Tabellen 2019 für L84, L86 und LT4 setzen die Grenze bei 0,5 Ohm zur Versorgung und verlangen 20 Fehler aus 25 Proben, Type B. Die Prüfung hängt also davon ab, dass das Steuergerät überhaupt eine Abschaltung befiehlt; bei GMs DFM-Motoren geschieht das laut NHTSA erst ab 40 °C Kühlmittel, mehr als 20 s nach dem Start und über 13 km/h. Typisch sind ein an eine Versorgungsleitung gedrückter Kabelbaum oder ein Ventil mit Windungsschluss. P3449 und P3451 sind die übrigen Kreiscodes für Zylinder 7.","u":[["h","Steuerleitung von Zylinder 7 hat Schluss zu einer Versorgungsleitung"],["m","Zu niederohmige Spule im Magnetventil von Zylinder 7"],["l","Endstufe des Motorsteuergeräts defekt"]],"s":["Motorkontrollleuchte an, oft erst nach längeren Fahrten mit warmem Motor","Zylinderabschaltung nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3449","P3450","P3451","P3456","P3400"]},{"c":"P3453","t":"Zylinder 7 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 7 Exhaust Valve Control Circuit/Open","d":"P3453 ist der Code, den SAE einer Unterbrechung im Kreis eines eigenen Auslassventil-Stellglieds an Zylinder 7 zuweist. Kein Hersteller dokumentiert diesen Code öffentlich. GMs von der NHTSA veröffentlichte Beschreibung des Dynamic Fuel Management zeigt, wie die Auslassseite ohne solches Stellglied geschaltet wird: Dasselbe Ölsignal entriegelt den Einlassstößel sofort, während der Auslassstößel wartet, bis die Ventilfeder auf dem Grundkreis der Nocke entlastet ist. Eigene Leitungen gibt es nur bei Bauarten mit zusätzlichem Auslass-Stellglied, deren Durchgang CARB überwachen ließe. Echte Kreisfehler an Zylinder 7 von GM- und Chrysler-V8 erscheinen dagegen als P3449. P3454 bis P3456 sind die übrigen Auslasscodes, P3455 der Masseschluss.","u":[["m","Unterbrochene Leitung zum Auslass-Stellglied von Zylinder 7"],["m","Durchgebrannte Spule des Stellglieds"],["l","Korrodierter Stecker am Stellglied"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3454","P3455","P3456","P3449","P3400"]},{"c":"P3454","t":"Zylinder 7 Auslassventil Steuerung Funktion","e":"Cylinder 7 Exhaust Valve Control Performance","d":"P3454 erfasst ein Auslassventil an Zylinder 7, das nicht wie befohlen schaltet, ohne dass sein Steuerkreis einen elektrischen Fehler hat. Kein Hersteller dokumentiert diesen Code öffentlich. Warum die Auslassseite wichtig ist, zeigt GMs eigene Prüfung P318F für Zylinder 7 beim L84 von 2019: Öffnet das Auslassventil nicht und bleibt das verbrannte Gas im Zylinder, wird es erneut verdichtet, der Zylinderdruck steigt, und beim Wiederzuschalten kann die Einlassmechanik Schaden nehmen. Das Steuergerät greift deshalb sofort ein (Auswertung der Kurbelwellen-Drehungleichförmigkeit, 66 von 100 Proben, Type B). Ein Ford-Patent behandelt das umgekehrte Problem, ein nach der Abschaltung weiter öffnendes Auslassventil, erkannt über den Abgasdruck. P3453, P3455 und P3456 sind die elektrischen Codes.","u":[["m","Auslassstößel von Zylinder 7 hängt im entriegelten Zustand"],["m","Öldruck oder Ölqualität reicht zum Umschalten nicht aus"],["l","Steuerventil der Auslassseite träge oder klemmend"]],"s":["Motorkontrollleuchte an","Harter Schlag oder Ruck beim Wiederzuschalten von Zylinder 7","Mögliche Fehlzündungen auf Zylinder 7 (P0307)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3453","P3455","P3456","P3450","P349E","P0307"]},{"c":"P3455","t":"Zylinder 7 Auslassventil Steuerkreis niedrig","e":"Cylinder 7 Exhaust Valve Control Circuit Low","d":"P3455 steht für Masseschluss an der Ansteuerung eines separaten Stellglieds, das nur das Auslassventil von Zylinder 7 schaltet. Kein Hersteller dokumentiert diesen Code öffentlich. Bei GMs V8 – ob AFM oder DFM – arbeitet je Zylinder ein einziges Stößel-Ölmagnetventil für Ein- und Auslass; eine Leitung an Masse setzt dort den Einlass-Code P3451. Geprüft wird bei ausgeschalteter Low-Side-Endstufe auf unter 0,5 Ohm gegen Masse, 20 von 25 Messungen im 250-ms-Raster müssen scheitern (Type B). Beim Hemi von FCA landen durchgescheuerte MDS-Leitungen hinten am fahrerseitigen Zylinderkopf – dort liegt Zylinder 7 – unter P3449. Hat die Steuerleitung Masseschluss, zieht das Stellglied womöglich ohne Befehl an: Der Zylinder verliert seinen Ventilhub, obwohl weiter eingespritzt wird. P3453 meldet die Unterbrechung, P3456 den Plusschluss.","u":[["h","Stellglied-Leitung am Zylinderkopf oder Hitzeschild durchgescheuert"],["m","Spule des Stellglieds mit Schluss zum Gehäuse"],["l","Endstufe im Motorsteuergerät beschädigt"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt","Unruhiger Lauf oder Aussetzer an Zylinder 7, wenn das Stellglied ungewollt anzieht"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3453","P3454","P3456","P3451","P3449","P3400","P0307"]},{"c":"P3456","t":"Zylinder 7 Auslassventil Steuerkreis hoch","e":"Cylinder 7 Exhaust Valve Control Circuit High","d":"P3456 meldete ein Auslassventil-Stellglied an Zylinder 7, dessen Steuerleitung Schluss nach Versorgungsspannung hat. Kein Hersteller dokumentiert diesen Code öffentlich. Laut der NHTSA-Zusammenfassung des DFM-Systems steuert GM seine Abschaltventile mit Peak-and-Hold-Stromtreibern für schnelles, gleichmäßiges Schalten an, und ein Ventil bedient beide Ventile des Zylinders. Ein Plusschluss fällt deshalb unter den Einlass-Code P3452 (unter 0,5 Ohm zur Versorgung bei eingeschalteter Endstufe, 20 von 25 Proben, Type B). CARB verlangt eine solche Prüfung für jeden abgasrelevanten Ausgang – deshalb gibt es den Auslass-Code überhaupt. Masseschluss desselben Kanals ist P3455, Unterbrechung P3453, ein mechanischer Fehler P3454.","u":[["m","Stellglied-Leitung von Zylinder 7 mit Batteriespannung verbunden"],["m","Spule des Auslass-Stellglieds mit Windungsschluss"],["l","Stromtreiber im Steuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Motor geht nicht in den Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3453","P3454","P3455","P3452","P3400"]},{"c":"P3457","t":"Zylinder 8 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 8 Deactivation/Intake Valve Control Circuit/Open","d":"Zylinder 8 gehört nicht zu den Zylindern, die das klassische Active Fuel Management oder Chryslers MDS stilllegen (beide nutzen 1, 4, 6 und 7). P3457 ist deshalb nur für neuere Bauarten belegt. GMs Tabellen 2019 führen ihn für den L84 mit Dynamic Fuel Management, der jeden Zylinder abschalten kann: mehr als 200 kOhm bei ausgeschalteter Low-Side-Endstufe, 20 von 25 Proben im 250-ms-Takt ab 425 U/min, Type B. GMs Informations-Bulletin zu AFM und DFM ergänzt, dass die Motoren LTA und LT2 die Zylinder 2, 3, 5 und 8 abschalten. Laut GM speichern manche Steuergeräte bei einer Unterbrechung zusätzlich P3459. P3458 ist der Funktionscode für Zylinder 8, P3459 und P3460 die Schlusscodes.","u":[["h","Leitung zum Magnetventil von Zylinder 8 im Kabelbaum unter dem Ansaugkrümmer gebrochen oder durchgescheuert"],["m","Unterbrochene Wicklung im Magnetventil von Zylinder 8"],["m","Schlechter Kontakt am Ventilstecker"],["l","Endstufe des Motorsteuergeräts defekt"]],"s":["Motorkontrollleuchte an","Dynamische Zylinderabschaltung gesperrt","Bei manchen GM-Steuergeräten zusätzlich P3459 gespeichert"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3458","P3459","P3460","P3461","P3449","P3400","P3497"]},{"c":"P3458","t":"Zylinder 8 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 8 Deactivation/Intake Valve Control Performance","d":"P3458 beschreibt einen Zylinder 8, der Ab- oder Zuschaltbefehle nicht umsetzt, während sein Steuerkreis elektrisch fehlerfrei bleibt. Kein Hersteller dokumentiert diesen Code öffentlich. GM, als einziger Hersteller mit veröffentlichten Abschaltcodes für Zylinder 8, ordnet diesen Fehler beim L84 dem Code P349F zu: Bleibt der gefilterte Saugrohrdruck während eines befohlenen Aussetzers über einer Schwelle, haben Ein- und Auslassventil weitergearbeitet. Geprüft wird bei einer Zylinderfüllung über 120 mg und MAP/BARO zwischen 0,30 und 0,95; 22 Fehler in 25 Gelegenheiten ergeben einen Type-B-Code. Bulletin 20-NA-204 ergänzt, dass bei großen SUVs 2021 mit L84 und L87 ein Spannungseinbruch beim Anlassen P349F ohne Hardwarefehler setzen kann. Elektrische Fehler sind P3457, P3459 und P3460.","u":[["m","Abschaltstößel von Zylinder 8 entriegelt oder verriegelt nicht"],["m","Öldruck zu niedrig oder Öl aufgeschäumt"],["m","Magnetventil von Zylinder 8 träge oder Sieb zugesetzt"],["l","Fehleintrag nach Unterspannung beim Anlassen, behoben per Software-Update (GM-Analogie 20-NA-204)"]],"s":["Motorkontrollleuchte an, teils wieder erloschen","Schütteln oder Unruhe bei Konstantfahrt mit wenig Last","Fehlzündungen auf Zylinder 8 (P0308)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3457","P3459","P3460","P3462","P349F","P0308","P3497"]},{"c":"P3459","t":"Zylinder 8 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 8 Deactivation/Intake Valve Control Circuit Low","d":"Berührt die masseseitige Steuerleitung des Abschalt-Magnetventils von Zylinder 8 die Masse, speichert das Steuergerät P3459. GM veröffentlicht die Prüfung für den V8 L84 mit Dynamic Fuel Management (2019): Endstufe aus, Widerstand unter 0,5 Ohm gegen Masse, mindestens 11 V am Powertrain-Relais und 425 U/min, 20 Fehler in 25 Proben, Type B. Manche GM-Steuergeräte tragen gleichzeitig P3457 ein. Da ein DFM-Motor jeden Zylinder auslassen darf, legt ein Fehler an Zylinder 8 ein System still, das diesen Zylinder sonst regelmäßig nutzt; auch GMs LTA und LT2 haben Zylinder 8 in ihrer festen Abschaltgruppe. Ein Masseschluss an der High-Side-Versorgung des Ventils hat bei GM den eigenen Code P311A. P3460 ist der Plusschluss.","u":[["h","Steuerleitung von Zylinder 8 über beschädigte Isolierung an Masse"],["m","Innerer Schluss im Magnetventil von Zylinder 8"],["l","Verschmutzung im Stecker des Magnetventils"],["l","Endstufe im Motorsteuergerät beschädigt"]],"s":["Motorkontrollleuchte nach der zweiten Fahrt an","Motor läuft ständig auf allen acht Zylindern","Höherer Kraftstoffverbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3457","P3458","P3460","P3463","P3497"]},{"c":"P3460","t":"Zylinder 8 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 8 Deactivation/Intake Valve Control Circuit High","d":"P3460 meldet einen Schluss nach Versorgungsspannung im Steuerkreis des Abschalt-Magnetventils von Zylinder 8, erkannt bei eingeschaltetem Ausgang. GM führt den Code für den L84 von 2019: unter 0,5 Ohm zwischen Ausgang und Versorgung, 20 von 25 Proben im 250-ms-Abstand, Type B, mit denselben Freigaben von 11 V und 425 U/min wie die übrigen Kreisprüfungen an Zylinder 8. In GMs Tabelle steckt hier ein Versehen: Die Spalte zur Prüfstrategie spricht beim P3460 vom Ventil für Zylinder 7, Code und Bauteilname nennen Zylinder 8. Ursache sind meist Kabelschäden an einer Versorgungsleitung oder eine Spule mit Windungsschluss; sichtbar wird es daran, dass der Motor Zylinder 8 nicht mehr abschaltet. Geschwister: P3457 (Unterbrechung) und P3459 (Masseschluss).","u":[["h","Steuerleitung von Zylinder 8 berührt eine Spannungsquelle"],["m","Windungsschluss im Magnetventil von Zylinder 8"],["l","Fehlerhafte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung inaktiv, etwas höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3457","P3458","P3459","P3464","P3497"]},{"c":"P3461","t":"Zylinder 8 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 8 Exhaust Valve Control Circuit/Open","d":"Im J2012-Schema steht P3461 für fehlenden Durchgang zu einem eigenständigen Stellglied der Auslassseite an Zylinder 8. Kein Hersteller dokumentiert diesen Code öffentlich. In den veröffentlichten Quellen schalten nur GMs neuere V8 den Zylinder 8 ab (DFM beim L84 und L87, festes Muster 2-3-5-8 bei LTA und LT2), und laut NHTSA versorgen diese Motoren beide Stößel eines Zylinders aus einem Magnetventil – eine eigene Auslassleitung zum Prüfen gibt es dort nicht. Auch eine GM-Patentanmeldung nutzt ein gemeinsames Hydraulikventil und staffelt die Auslassventile nur zeitlich vor die Einlassventile; erst ein eigenes Auslass-Stellglied fiele unter die CARB-Durchgangsprüfung für Ausgangskomponenten. Zur selben Auslassgruppe gehören P3462 bis P3464; die Unterbrechung auf der Einlassseite heißt P3457.","u":[["m","Leitung oder Stecker zum Auslass-Stellglied von Zylinder 8 gebrochen"],["m","Wicklung des Auslass-Stellglieds unterbrochen"],["l","Ausgang des Steuergeräts defekt"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung nicht mehr aktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3462","P3463","P3464","P3457","P3497"]},{"c":"P3462","t":"Zylinder 8 Auslassventil Steuerung Funktion","e":"Cylinder 8 Exhaust Valve Control Performance","d":"Mit P3462 würde das Steuergerät mitteilen, dass das Auslassventil von Zylinder 8 Abschaltbefehle übergeht, obwohl elektrisch alles stimmt. Kein Hersteller dokumentiert diesen Code öffentlich. GM deckt die Auslassseite von Zylinder 8 beim L84 von 2019 mit dem eigenen Code P3190 ab („Cylinder 8 Trapped High Pressure Exhaust Charge“): Übersteigt die auf die Drehzahl bezogene Drehungleichförmigkeit der Kurbelwelle bei abgeschaltetem Zylinder eine lastabhängige Schwelle, gilt das Auslassventil als nicht geöffnet; 66 Fehler in 100 Proben setzen einen Type-B-Code. Ford hat die Gegenprüfung patentiert – ein Auslassventil, das trotz Abschaltung weiter aufgeht, erkannt am Abgasdruck. Die Folgen reichen von Vibrationen im Teilzylinderbetrieb bis zu Fehlzündungen auf Zylinder 8 (P0308).","u":[["m","Auslassstößel von Zylinder 8 verriegelt nicht rechtzeitig"],["m","Ölversorgung der Stößelkanäle unzureichend"],["l","Steuerventil der Auslassseite klemmt"]],"s":["Motorkontrollleuchte an","Vibrationen bei abgeschalteten Zylindern","Fehlzündungen auf Zylinder 8 (P0308)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3461","P3463","P3464","P3458","P349F","P0308"]},{"c":"P3463","t":"Zylinder 8 Auslassventil Steuerkreis niedrig","e":"Cylinder 8 Exhaust Valve Control Circuit Low","d":"P3463 stünde für einen Masseschluss in der Leitung eines eigenständigen Auslass-Stellglieds an Zylinder 8. Kein Hersteller dokumentiert diesen Code öffentlich. Bei den einzigen Motoren mit belegter Abschaltung von Zylinder 8, GMs L84 und seinen Verwandten, bedient ein Magnetventil beide Ventile; einen Masseschluss daran meldet GM als P3459 und prüft dafür auf weniger als 0,5 Ohm gegen Masse bei ausgeschalteter Endstufe. Die NHTSA-Zusammenfassung des Systems zählt Kreisfehler an den Ventil-Endstufen zu den Gründen, aus denen das Steuergerät die Abschaltung sperrt – genau das merkt auch der Fahrer: Der Motor läuft weiter auf allen acht Zylindern und verbraucht etwas mehr. P3461 (Unterbrechung), P3462 (Funktion) und P3464 (Plusschluss) vervollständigen diese Auslassgruppe.","u":[["m","Leitung des Auslass-Stellglieds von Zylinder 8 mit dem Motorblock kurzgeschlossen"],["m","Auslass-Stellglied innen gegen Masse kurzgeschlossen"],["l","Endstufe im Motorsteuergerät fehlerhaft"]],"s":["Motorkontrollleuchte an","Motor bleibt auf allen acht Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3461","P3462","P3464","P3459","P3497"]},{"c":"P3464","t":"Zylinder 8 Auslassventil Steuerkreis hoch","e":"Cylinder 8 Exhaust Valve Control Circuit High","d":"P3464 entsteht, sobald die Leitung zu einem gesonderten Auslass-Stellglied von Zylinder 8 einen zu hohen Pegel führt, typischerweise durch Kontakt mit Batteriespannung. Kein Hersteller dokumentiert diesen Code öffentlich. Laut GM-Bulletin 20-NA-038 legen nur DFM-Motoren sowie LTA und LT2 mit dem festen Muster 2, 3, 5 und 8 den Zylinder 8 still; das klassische AFM schaltet 1, 7, 6 und 4. Dort bewegt ein einziges Magnetventil auch den Auslassstößel, und einen Plusschluss daran führt GM als P3460: Endstufe eingeschaltet, unter 0,5 Ohm zur Versorgung, 20 von 25 Proben, Type B. Im Fehlertext der Tabelle von 2019 steht dabei Zylinder 7 – ein Kopierfehler. Weil der kurzgeschlossene Ausgang nicht schalten kann, bleibt Zylinder 8 einfach in Betrieb. Den Masseschluss meldet P3463.","u":[["m","Steuerleitung des Stellglieds von Zylinder 8 berührt eine Plusleitung"],["m","Windungsschluss in der Stellglied-Spule, Widerstand viel zu gering"],["l","Endstufe im Motorsteuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Motor läuft dauerhaft auf allen acht Zylindern, etwas höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3461","P3462","P3463","P3460","P3497"]},{"c":"P3465","t":"Zylinder 9 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 9 Deactivation/Intake Valve Control Circuit/Open","d":"Bei P3465 sieht das Steuergerät eine Unterbrechung im Kreis jenes Stellglieds, das Zylinder 9 stilllegen oder dessen Einlassventil geschlossen halten soll. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zu diesen Motoren zählt der V12 M137 von Mercedes (S 600 und CL 600, 1998 bis 2002), dessen Abschaltsystem auf einem Magnetventilblock mit Öldruckleitungen aufbaute; Audis R8-V10 legt dagegen eine komplette Bank still, indem er Einspritzung und Zündung aussetzt. Zur Einordnung: GM wertet den entsprechenden Kreis seiner V8 bei ausgeschaltetem Treiber ab 200 kOhm als offen (20 Fehler in 25 Proben). Kurzschlüsse derselben Leitung melden P3467 und P3468, mechanische Störungen P3466, die Auslassseite von Zylinder 9 P3469.","u":[["h","Leitung zum Stellglied von Zylinder 9 gebrochen oder durchgescheuert"],["m","Spule des Magnetventils von Zylinder 9 unterbrochen"],["m","Stecker am Magnetventilblock locker oder korrodiert"],["l","Endstufe im Motorsteuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung greift nicht mehr","Leicht erhöhter Verbrauch im Teillastbereich"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3466","P3467","P3468","P3469","P3400","P3497","P0309"]},{"c":"P3466","t":"Zylinder 9 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 9 Deactivation/Intake Valve Control Performance","d":"P3466 prüft die Plausibilität an Zylinder 9: Der Kreis des Stellglieds ist elektrisch in Ordnung, trotzdem wechselt der Zylinder auf Befehl nicht den Zustand. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Ventilbasierte Systeme schalten hydraulisch; die NHTSA beschreibt für GM, wie Öldruck Sperrstifte im Stößel verschiebt. Der Mercedes-V12 M137, dessen Abschaltsystem auf Magnetventilblock und Öldruckleitungen beruhte, gilt gerade an diesen Teilen als anfällig – genau solche Mängel zielt dieser Code an. Audis V10 und Bentleys W12 schalten bankweise ab, lassen die Ventile aber weiterlaufen und haben hier nichts zu überwachen. Die elektrischen Fehler von Zylinder 9 sind P3465, P3467 und P3468.","u":[["h","Ölstand, Öldruck oder Ölqualität reicht zum Umschalten von Zylinder 9 nicht"],["m","Undichtigkeit an Ölleitungen oder Magnetventilblock für Zylinder 9"],["m","Schaltstößel von Zylinder 9 klemmt"],["l","Magnetventil mechanisch träge oder klemmend"]],"s":["Motorkontrollleuchte an","Fehlzündungen auf Zylinder 9 (P0309)","Unruhiger Lauf beim Wechsel zwischen Voll- und Teilbetrieb"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3465","P3467","P3468","P3470","P3400","P0309"]},{"c":"P3467","t":"Zylinder 9 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 9 Deactivation/Intake Valve Control Circuit Low","d":"P3467 heißt: Die Steuerleitung des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 9 liegt zu niedrig, meist wegen einer Verbindung nach Masse. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zwölfzylinder mit Zylinderabschaltung gibt es durchaus, etwa den M137 von Mercedes oder den V12 des Lamborghini Aventador, eingeführt 2012, doch keine veröffentlichte Diagnoseliste ordnet ihnen diese Nummer zu. GMs gleichartige Prüfung an V8-Motoren sucht bei abgeschaltetem Treiber nach weniger als 0,5 Ohm gegen Masse und läuft nur oberhalb von 11 V und 425 U/min. Bestromt der Schluss ein masseseitig geschaltetes Ventil dauerhaft, kann der Zylinder ungewollt ausfallen. Geschwister: P3465 Unterbrechung, P3468 Schluss nach Plus.","u":[["h","Steuerleitung von Zylinder 9 mit Masseschluss"],["m","Innerer Schluss im Magnetventil von Zylinder 9"],["l","Feuchtigkeit im Stecker des Magnetventils"],["l","Fehlerhafte Endstufe im Motorsteuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt","Mögliche Fehlzündungen auf Zylinder 9, wenn das Stellglied bestromt bleibt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3465","P3466","P3468","P3471","P3497","P0309"]},{"c":"P3468","t":"Zylinder 9 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 9 Deactivation/Intake Valve Control Circuit High","d":"P3468 zeigt an, dass der Steuerkreis des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 9 nach oben gezogen wird – meist durch einen Schluss nach Batteriespannung, den das Steuergerät beim Einschalten des Ausgangs bemerkt. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Die meisten Motoren mit mehr als acht Zylindern und Abschaltung, etwa Audis R8-V10 oder Bentleys W12, legen ganze Bänke ohne eigene Ventil-Stellglieder still; der Mercedes-V12 M137 mit seinem Magnetventilblock war die Ausnahme. GM zählt bei seinen V8 unter 0,5 Ohm zur Versorgung bei eingeschaltetem Treiber, 20 von 25 Proben. Das Steuergerät schaltet den Ausgang ab und fährt mit allen Zylindern. Übrige elektrische Fehler: P3465 (offen) und P3467 (Masseschluss).","u":[["h","Steuerleitung von Zylinder 9 berührt eine Versorgungsleitung"],["m","Windungsschluss in der Spule des Magnetventils von Zylinder 9"],["l","Endstufe des Motorsteuergeräts beschädigt"]],"s":["Motorkontrollleuchte an","Motor läuft ständig mit allen Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3465","P3466","P3467","P3472","P3497"]},{"c":"P3469","t":"Zylinder 9 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 9 Exhaust Valve Control Circuit/Open","d":"P3469 setzt das Steuergerät, wenn der Kreis eines eigenen Auslassventil-Stellglieds an Zylinder 9 unterbrochen ist. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Ein eigenes Auslass-Stellglied setzt unabhängig geschaltete Ventile voraus; ein GM-Patent zeigt immerhin, dass Auslassventile eigenem Timing folgen können – sie ruhen vor den Einlassventilen und kehren vor ihnen zurück. GMs Serientechnik nutzt dagegen ein Magnetventil je Zylinder für beide Ventile, und die öffentlich beschriebenen Systeme mit zehn und zwölf Zylindern (Audi R8-V10, Bentley W12) lassen die Ventile ohnehin weiterlaufen. Der Fehler betrifft also nur Motoren mit solcher Hardware. Schlüsse melden P3471 und P3472, Funktionsfehler P3470, die Einlassseite P3465.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 9 unterbrochen oder durchgescheuert"],["m","Spule des Auslass-Stellglieds von Zylinder 9 unterbrochen"],["m","Stecker am Auslass-Stellglied locker oder korrodiert"],["l","Ausgang des Motorsteuergeräts ausgefallen"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3470","P3471","P3472","P3465","P3400","P3497"]},{"c":"P3470","t":"Zylinder 9 Auslassventil Steuerung Funktion","e":"Cylinder 9 Exhaust Valve Control Performance","d":"P3470 betrifft ein Auslassventil an Zylinder 9, das dem Abschaltbefehl nicht folgt, obwohl der Steuerkreis elektrisch einwandfrei ist. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Welches Risiko dahintersteckt, zeigt ein Ford-Patent: Öffnet das Auslassventil nach der Abschaltung weiter, geht das Gaspolster verloren, was sich an Änderungen des Abgasdrucks erkennen lässt. Bleibt es umgekehrt beim Zuschalten zu, sperrt es heißes Gas unter Druck ein. Wie die Bankabschaltung von Lamborghini Aventador (V12) und Huracán (V10) technisch arbeitet, ist nicht veröffentlicht, und Audis V10 setzt nur Einspritzung und Zündung aus – ein Anwender dieser Prüfung ist nicht bekannt. Elektrische Fehler desselben Stellglieds: P3469, P3471, P3472.","u":[["m","Schaltelement am Auslass von Zylinder 9 hängt"],["m","Zu geringer Öldruck für die Auslassumschaltung"],["l","Auslass-Stellglied schwergängig"]],"s":["Motorkontrollleuchte an","Schlag oder Ruck, wenn Zylinder 9 wieder zuschaltet","Fehlzündungen auf Zylinder 9 (P0309)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3469","P3471","P3472","P3466","P0309"]},{"c":"P3471","t":"Zylinder 9 Auslassventil Steuerkreis niedrig","e":"Cylinder 9 Exhaust Valve Control Circuit Low","d":"Ein zu niedriger Pegel an der Steuerleitung des Auslassventil-Stellglieds von Zylinder 9 löst P3471 aus, meist eine Leitung mit Masseschluss an Motor oder Karosserie. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Die bekannten Abschaltsysteme oberhalb von acht Zylindern legen entweder eine ganze Bank über Einspritzung und Zündung still (Audi R8-V10) oder schließen die Ventile mit einem gemeinsamen Stellglied je Zylinder, wie GMs Technik zeigt; ein eigens verdrahtetes Auslass-Stellglied an Zylinder 9 wäre daher ungewöhnlich. Ist ein solcher Kreis vorhanden, prüft man ihn wie den Einlasskreis: Widerstand gegen Masse bei abgezogenem Stecker, danach die Spule. Unterbrechung meldet P3469, Plusschluss P3472, die Einlassseite P3467.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 9 mit Masseschluss"],["m","Innerer Schluss im Auslass-Stellglied"],["l","Ausgang des Motorsteuergeräts beschädigt"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3469","P3470","P3472","P3467","P3497"]},{"c":"P3472","t":"Zylinder 9 Auslassventil Steuerkreis hoch","e":"Cylinder 9 Exhaust Valve Control Circuit High","d":"P3472 hält einen zu hohen Spannungspegel im Steuerkreis des Auslassventils von Zylinder 9 fest – das Bild einer Leitung mit Schluss zu einer Versorgung oder einer Spule mit Windungsschluss. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Für einen abschaltbaren Zylinder 9 kämen etwa der Mercedes-V12 M137, der V12 des Lamborghini Aventador und Bentleys W12 in Frage; bei keinem ist ein eigenes Auslass-Stellglied dokumentiert, und vom Bentley-Motor heißt es sogar, seine Ventile arbeiteten beim Abschalten weiter. Dass die Auslassseite eine eigene Schaltfolge hat, zeigt ein US-Patent von GM: Dort ruhen die Auslassventile vor den Einlassventilen und kehren auch zuerst zurück. P3469 (offen) und P3471 (niedrig) ergänzen die elektrischen Fehler.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 9 mit Plusschluss"],["m","Windungsschluss im Auslass-Stellglied"],["l","Fehlerhafter Ausgang des Motorsteuergeräts"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung vom Steuergerät abgeschaltet"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3469","P3470","P3471","P3468","P3497"]},{"c":"P3473","t":"Zylinder 10 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 10 Deactivation/Intake Valve Control Circuit/Open","d":"P3473 meldet eine Unterbrechung zum Abschalt- bzw. Einlassventil-Stellglied von Zylinder 10, beim V10 also dem letzten Zylinder. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Als V10 mit Zylinderabschaltung bekannt sind Audis 5,2 FSI im R8 und der Motor des Lamborghini Huracán ab Modelljahr 2016. Laut Audi legt das System in den vier oberen Gängen eine Bank still, indem es Einspritzung und Zündung abschaltet – ein Ventil-Stellglied, das dieser Code überwachen könnte, gibt es dort nicht. Bei einem Zwölfzylinder mit Ventilabschaltung stünde der Code für eine gebrochene Leitung, eine offene Spule oder einen schlechten Stecker an Zylinder 10. Schlüsse behandeln P3475 und P3476, die mechanische Seite P3474, das Auslassventil P3477.","u":[["h","Leitung zum Stellglied von Zylinder 10 unterbrochen oder durchgescheuert"],["m","Spule des Magnetventils von Zylinder 10 offen"],["m","Korrodierter oder lockerer Stecker an Zylinder 10"],["l","Treiber im Motorsteuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Motor wechselt nicht mehr in den Teilzylinderbetrieb"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3474","P3475","P3476","P3477","P3400","P3497","P0310"]},{"c":"P3474","t":"Zylinder 10 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 10 Deactivation/Intake Valve Control Performance","d":"Bei P3474 geht es um die Funktion, nicht um die Verkabelung: Zylinder 10 soll abschalten oder zurückkommen, das gemessene Motorverhalten spricht aber dagegen, während der Steuerkreis intakt ist. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Audis R8-V10, einer der wenigen Zehnzylinder mit Abschaltung, kommt ohne Ventilschaltung aus; das Schließen der Ventile mit Nullhub-Nocken auf axial verschiebbaren Hülsen setzt Audi beim 4.0-TFSI-V8 ein. Wo Ventile abgeschaltet werden, liegen die Ursachen in der Ölversorgung oder in einem klemmenden Schaltelement; wie empfindlich das ist, zeigt die NHTSA-Beschreibung von GMs Stößeln mit öldruckbetätigten Sperrstiften. Die elektrischen Codes von Zylinder 10 sind P3473, P3475 und P3476.","u":[["h","Öldruck oder Ölzustand reicht zum Umschalten von Zylinder 10 nicht"],["m","Stößel oder Nockenhülse an Zylinder 10 klemmt"],["m","Ölsieb oder Kanal zum Stellglied von Zylinder 10 zugesetzt"],["l","Undichte Dichtung am Stellglied"]],"s":["Motorkontrollleuchte an","Fehlzündungen auf Zylinder 10 (P0310)","Klappern aus dem Ventiltrieb"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3473","P3475","P3476","P3478","P0310","P3497"]},{"c":"P3475","t":"Zylinder 10 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 10 Deactivation/Intake Valve Control Circuit Low","d":"P3475 deutet auf einen Masseschluss im Kreis, der Abschaltung bzw. Einlassventil von Zylinder 10 steuert. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Der V10 des Lamborghini Huracán läuft bei geringer Last auf fünf Zylindern, der V12 des Aventador unter 135 km/h auf sechs, doch keiner der beiden Hersteller veröffentlicht Diagnose bis auf Code-Ebene, und Audis baugleicher V10 kommt ohne Ventil-Stellglieder aus. Zur Einordnung der Prüfung: GMs Achtzylinder-Fassung verlangt unter 0,5 Ohm gegen Masse bei abgeschaltetem Ausgang, abgetastet alle 250 ms. Zuerst die Leitung zu Zylinder 10 auf Scheuerstellen untersuchen, danach das Stellglied. Eine offene Leitung meldet P3473, Plusschluss P3476, das Auslass-Gegenstück P3479.","u":[["h","Steuerleitung von Zylinder 10 durch Scheuern an Masse"],["m","Stellglied von Zylinder 10 mit innerem Schluss"],["l","Wasser im Stecker des Stellglieds"],["l","Defekte Endstufe im Steuergerät"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb nicht verfügbar","Mögliche Fehlzündungen auf Zylinder 10"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3473","P3474","P3476","P3479","P0310","P3400"]},{"c":"P3476","t":"Zylinder 10 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 10 Deactivation/Intake Valve Control Circuit High","d":"P3476 wird gespeichert, wenn der Steuerkreis des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 10 zu hoch liegt – in der Regel ein Schluss zu einer batteriegespeisten Leitung, der bei aktivem Ausgang auffällt. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bei den V10 mit Abschaltung beschreibt Audi, dass die Bank in den oberen Gängen über das Abschalten von Einspritzung und Zündung ruht; Zylinder 10 hat dort kein Ventil-Stellglied. Für Konstruktionen wie den Mercedes-V12 M137 mit öldruckgesteuertem Magnetventilblock ist dieser Code gedacht. Meist sperrt das Steuergerät die Abschaltung danach für den Rest der Fahrt. Elektrische Geschwister: P3473 und P3475.","u":[["h","Steuerleitung von Zylinder 10 mit Schluss zur Versorgung"],["m","Spule des Stellglieds von Zylinder 10 mit Windungsschluss"],["l","Endstufe des Steuergeräts defekt"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung für die Fahrt gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3473","P3474","P3475","P3480","P3497"]},{"c":"P3477","t":"Zylinder 10 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 10 Exhaust Valve Control Circuit/Open","d":"P3477 gehört zu Motoren, die das Auslassventil von Zylinder 10 über ein eigenes Stellglied schalten, und meldet einen offenen Kreis dieses Stellglieds. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Die Zehnzylinder mit Abschaltung, Audi R8-V10 und Lamborghini Huracán, legen eine Bank still statt einzelner Ventile; Audi nennt Einspritzung und Zündung als das, was ruht. Dass die Auslassseite eigene Zeitvorgaben hat, zeigt GMs Patent zur Ventilabschaltung: Magnetbetätigte Hydraulikventile legen dort die Auslassventile vor den Einlassventilen still und holen sie auch vorher zurück. Diagnose wie bei jeder Unterbrechung – Stecker, Leitung, Spule. Schlüsse melden P3479 und P3480, Funktionsfehler P3478, den Einlasskreis P3473.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 10 unterbrochen"],["m","Spule des Auslass-Stellglieds von Zylinder 10 offen"],["m","Korrodierter Stecker am Stellglied"],["l","Ausgang des Steuergeräts ausgefallen"]],"s":["Motorkontrollleuchte an","Motor hält alle Zylinder aktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3478","P3479","P3480","P3473","P3400","P3497"]},{"c":"P3478","t":"Zylinder 10 Auslassventil Steuerung Funktion","e":"Cylinder 10 Exhaust Valve Control Performance","d":"P3478 beschreibt ein Auslassventil an Zylinder 10, das nicht wie befohlen schaltet, obwohl der Kreis seines Stellglieds in Ordnung ist. Arbeitet ein Auslassventil nach der Abschaltung weiter, wird das eingeschlossene Gas ausgeschoben und der Zylinder kühlt aus; ein Ford-Patent will das über den Abgasdruck erkennen. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Gegen Auskühlen wechselt Bentley beim W12 die ruhende Bank und schützt so Zylinder und Katalysator; wie Audi beim R8-V10 legt Bentley Bänke still, keine einzelnen Ventile. Der Code betrifft daher nur Motoren mit schaltbaren Auslassventilen, die keines der bekannten V10- oder V12-Systeme öffentlich nutzt. Elektrische Fehler: P3477, P3479, P3480.","u":[["m","Schaltelement am Auslass von Zylinder 10 klemmt"],["m","Öldruck für die Auslassumschaltung zu niedrig"],["l","Auslass-Stellglied reagiert träge"]],"s":["Motorkontrollleuchte an","Harter Ruck beim Zuschalten von Zylinder 10","Fehlzündungen auf Zylinder 10 (P0310)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3477","P3479","P3480","P3474","P0310"]},{"c":"P3479","t":"Zylinder 10 Auslassventil Steuerkreis niedrig","e":"Cylinder 10 Exhaust Valve Control Circuit Low","d":"P3479 zeigt einen Masseschluss oder eine andere Ursache für ein zu niedriges Signal an der Steuerleitung des Auslassventil-Stellglieds von Zylinder 10. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zu den Motoren mit zehn oder mehr Zylindern und Abschaltung zählen Audis R8-V10, der V10 des Lamborghini Huracán und der V12 des Aventador sowie Bentleys W12; deren veröffentlichte Beschreibungen sprechen durchweg von ganzen Bänken, nicht von einem Ventil-Stellglied je Zylinder. Hat ein Motor doch eines, ähnelt die Prüfung dem Einlass-Test von GMs V8: Widerstand gegen Masse bei abgeschaltetem Ausgang. Zu reparieren sind Leitungen oder das Stellglied an Zylinder 10. Geschwister: P3477 (offen), P3480 (hoch), P3475 (Einlass niedrig).","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 10 mit Masseschluss"],["m","Auslass-Stellglied mit innerem Schluss"],["l","Endstufe des Steuergeräts fehlerhaft"]],"s":["Motorkontrollleuchte an","Spritsparende Zylinderabschaltung inaktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3477","P3478","P3480","P3475","P3497"]},{"c":"P3480","t":"Zylinder 10 Auslassventil Steuerkreis hoch","e":"Cylinder 10 Exhaust Valve Control Circuit High","d":"Liegt die Steuerleitung des Auslassventil-Stellglieds von Zylinder 10 nahe der Versorgungsspannung, speichert das Motorsteuergerät P3480. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Ein Zehnzylinder hat keinen Zylinder 11 oder 12; P3480 ist damit der letzte Auslassventil-Code, den ein V10 überhaupt nutzen könnte. Der R8-V10 braucht ihn trotzdem nicht, weil seine Abschaltung über Einspritzung und Zündung läuft. Bei einem zu hohen Kreis sucht man nach einer Leitung, die an einer Versorgung scheuert, nach einer im Stecker vergessenen Messspitze oder nach einer Spule mit Windungsschluss. Die anderen elektrischen Fehler dieses Stellglieds sind P3477 (offen) und P3479 (niedrig), das Einlass-Gegenstück an Zylinder 10 ist P3476.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 10 mit Schluss zur Versorgung"],["m","Windungsschluss in der Spule des Auslass-Stellglieds"],["l","Ausgang des Motorsteuergeräts defekt"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung deaktiviert"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3477","P3478","P3479","P3476","P3497"]},{"c":"P3481","t":"Zylinder 11 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 11 Deactivation/Intake Valve Control Circuit/Open","d":"P3481 kennzeichnet eine Unterbrechung zum Stellglied für Abschaltung bzw. Einlassventil von Zylinder 11 – einen Zylinder, den nur V12- und W12-Motoren haben. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bentleys W12, der am besten belegte Zwölfzylinder mit Abschaltung, legt eine komplette Sechserbank still und lässt dabei nach Aussage seines Entwicklungsvorstands die Ventile weiterarbeiten; das Steuergerät wechselt anhand von Sensordaten aus Ansaug- und Abgasseite zwischen Bank A und B, damit Zylinder und Katalysator warm bleiben. Ohne Ventil-Stellglied gibt es keinen Kreis, den P3481 prüfen könnte. Sonst stehen Leitung, Stecker oder Spule im Verdacht. Schlüsse melden P3483 und P3484, die Funktion P3482, die Auslassseite P3485.","u":[["h","Leitung zum Stellglied von Zylinder 11 gebrochen"],["m","Spule des Stellglieds von Zylinder 11 offen"],["m","Stecker am Stellglied von Zylinder 11 locker oder korrodiert"],["l","Treiberstufe im Motorsteuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Motor bleibt auf allen zwölf Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3482","P3483","P3484","P3485","P3400","P3497","P0311"]},{"c":"P3482","t":"Zylinder 11 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 11 Deactivation/Intake Valve Control Performance","d":"P3482 ist die Funktionsprüfung für Zylinder 11: Der Kreis des Stellglieds ist elektrisch in Ordnung, doch der Zylinder ruht nicht oder erwacht nicht, wenn er soll. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bentleys Bentayga und Continental mit W12 können auf sechs von zwölf Zylindern fahren, die veröffentlichte Beschreibung lässt die Ventile dabei aber weiterarbeiten – ein Fehler der Ventilumschaltung kann dort nicht auftreten. Motoren, die Ventile schließen, brauchen Öldruck an schaltbaren Stößeln, wie die NHTSA-Untersuchung zu GMs Stößeln zeigt. Verschmutztes oder zu wenig Öl und abgenutzte Sperrstifte sind die üblichen Gründe für ein verpasstes Umschalten. Elektrische Gegenstücke an Zylinder 11: P3481, P3483, P3484.","u":[["h","Verschmutztes oder zu wenig Öl zum Umschalten von Zylinder 11"],["m","Abgenutzte oder klemmende Sperrstifte an Zylinder 11"],["m","Ölsieb zum Stellglied von Zylinder 11 verstopft"],["l","Dichtung am Stellglied verliert Druck"]],"s":["Motorkontrollleuchte an","Fehlzündungen auf Zylinder 11 (P0311)","Spürbares Rütteln beim Wechsel der Betriebsart"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3481","P3483","P3484","P3486","P0311","P3400"]},{"c":"P3483","t":"Zylinder 11 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 11 Deactivation/Intake Valve Control Circuit Low","d":"P3483 wird für ein zu niedriges Signal im Steuerkreis des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 11 gespeichert, praktisch also einen Masseschluss. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zylinder 11 gibt es nur bei Zwölfzylindern; Abschaltung haben etwa Bentleys W12, der V12 des Lamborghini Aventador und früher der M137 von Mercedes. GMs entsprechender V8-Test wertet unter 0,5 Ohm gegen Masse bei abgeschaltetem Treiber als Fehler, sobald 20 von 25 Proben übereinstimmen; Freigabe ab 11 V Bordspannung und 425 U/min. Eine Leitung an Masse kann das Stellglied dauerhaft bestromen und Zylinder 11 zur falschen Zeit stilllegen. Geschwister: P3481 (offen) und P3484 (hoch).","u":[["h","Steuerleitung von Zylinder 11 mit Masseschluss"],["m","Stellglied von Zylinder 11 mit innerem Schluss"],["l","Feuchtigkeit am Stecker des Stellglieds"],["l","Ausgang des Motorsteuergeräts fehlerhaft"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung abgeschaltet","Mögliche Fehlzündungen auf Zylinder 11"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3481","P3482","P3484","P3487","P0311","P3497"]},{"c":"P3484","t":"Zylinder 11 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 11 Deactivation/Intake Valve Control Circuit High","d":"P3484 signalisiert einen zu hohen Pegel im Steuerkreis des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 11, etwa weil die Leitung Schluss zu einer Batterieleitung hat und das Steuergerät das beim Einschalten des Ausgangs bemerkt. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zwölfzylinder mit Abschaltung wie Bentleys W12 in Bentayga und Continental GT oder der V12 des Lamborghini Aventador beschreiben ihre Systeme als Abschaltung einer ganzen Bank; Bentley betont, dass die Ventile in Bewegung bleiben. P3484 passt also nur zu einer Konstruktion mit eigenem Ventil-Stellglied an Zylinder 11. Das Steuergerät bricht die Abschaltung dann meist ab und fährt mit allen Zylindern. Die übrigen elektrischen Fehler sind P3481 und P3483.","u":[["h","Steuerleitung von Zylinder 11 berührt Batteriespannung"],["m","Spule des Stellglieds von Zylinder 11 mit Windungsschluss"],["l","Treiber im Steuergerät beschädigt"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb abgebrochen"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3481","P3482","P3483","P3488","P3497"]},{"c":"P3485","t":"Zylinder 11 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 11 Exhaust Valve Control Circuit/Open","d":"P3485 löst eine Unterbrechung am Kreis eines eigenen Auslassventil-Stellglieds von Zylinder 11 aus. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bentleys Ingenieure sagen, ihre W12-Abschaltung lasse beide Ventilsätze weiterarbeiten, und sie wechseln die ruhende Bank, damit sie warm bleibt; auch Lamborghini beim Aventador-V12 und der Konzern-V10 sprechen nur von Bänken. Kein veröffentlichtes System dieser Motorgröße schaltet das Auslassventil eines einzelnen Zylinders. Warum der Auslass ein eigenes Thema ist, erklärt ein GM-Patent: Seine hydraulischen Steuerventile schalten die Auslassventile zuerst ab und zuerst wieder zu. Elektrisch gilt P3485 als gewöhnliche Unterbrechung. Schlüsse melden P3487 und P3488, Funktionsfehler P3486.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 11 offen"],["m","Spule des Auslass-Stellglieds von Zylinder 11 offen"],["m","Stecker am Auslass-Stellglied korrodiert"],["l","Ausgang des Motorsteuergeräts defekt"]],"s":["Motorkontrollleuchte an","Motor schaltet nicht mehr auf die Hälfte der Zylinder"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3486","P3487","P3488","P3481","P3400","P3497"]},{"c":"P3486","t":"Zylinder 11 Auslassventil Steuerung Funktion","e":"Cylinder 11 Exhaust Valve Control Performance","d":"P3486 meldet ein Funktionsproblem am Auslassventil von Zylinder 11: Der Kreis ist gesund, das Ventil erreicht den befohlenen Zustand aber nicht. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Öffnet bei einem Zwölfzylinder ein Auslassventil weiter, pumpt der Zylinder kalte Luft ins Abgas und der Katalysator kühlt aus – genau das umgeht Bentley beim W12 durch das Wechseln der Bänke. Wie sich ein solches undichtes Auslassventil am Abgasdruck erkennen lässt, zeigt ein Ford-Patent. Der umgekehrte Fehler, ein geschlossen bleibendes Ventil, verdichtet beim Zuschalten das eingeschlossene Gas. Da keines der bekannten V12- oder W12-Systeme Ventile einzeln schaltet, ist kein Anwender belegt. Die elektrischen Fehler sind P3485, P3487 und P3488.","u":[["m","Schaltelement am Auslass von Zylinder 11 verklemmt"],["m","Ölversorgung für die Auslassumschaltung unzureichend"],["l","Auslass-Stellglied reagiert langsam"]],"s":["Motorkontrollleuchte an","Schlag beim Zuschalten von Zylinder 11","Fehlzündungen auf Zylinder 11 (P0311)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3485","P3487","P3488","P3482","P0311"]},{"c":"P3487","t":"Zylinder 11 Auslassventil Steuerkreis niedrig","e":"Cylinder 11 Exhaust Valve Control Circuit Low","d":"P3487 zeigte an, dass die Ansteuerleitung eines separaten Auslass-Stellglieds an Zylinder 11 Masse bekommt. Kein Hersteller dokumentiert diesen Code öffentlich; Zylinder 9 bis 12 gibt es erst ab neun Zylindern, für solche Motoren hält J2012 diese Codes bereit. Am nächsten kommt ihm die Active Cylinder Control des V12 in CL 600 und S 600 um das Jahr 2000: Sie legte eine Bank still, und laut Wikipedia entkoppelten zwei Magnetventile die Auslassventile dieser Bank, damit in den ruhenden Zylindern Druck blieb. Das ist ein Kreis je Bank, nicht je Zylinder. GMs V8-Gegenstück erkennt einen Masseschluss unter 0,5 Ohm bei ausgeschaltetem Treiber. Eine Leitung an Masse könnte das Stellglied ohne Befehl anziehen und Zylinder 11 abschalten, obwohl er zünden soll. Geschwister: P3485 (offen), P3488 (hoch).","u":[["h","Stellglied-Leitung zur Motormasse durchgescheuert"],["m","Spule des Stellglieds mit Schluss zum Gehäuse"],["l","Feuchtigkeit im Stellglied-Stecker überbrückt nach Masse"]],"s":["Motorkontrollleuchte an","Bankabschaltung wird nicht mehr angeboten","Mögliche Aussetzer an Zylinder 11 (P0311)"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3485","P3486","P3488","P3483","P0311","P3497"]},{"c":"P3488","t":"Zylinder 11 Auslassventil Steuerkreis hoch","e":"Cylinder 11 Exhaust Valve Control Circuit High","d":"P3488 betrifft einen zu hoch liegenden Kreis des Auslass-Stellglieds von Zylinder 11, meist weil die Steuerleitung Batteriespannung abbekommt. Kein Hersteller dokumentiert diesen Code öffentlich; Zylinder 9 bis 12 gibt es erst ab neun Zylindern, für solche Motoren hält J2012 diese Codes bereit. Spätere Zwölfzylinder mit Abschaltung haben dafür keine Verwendung: Bentleys W12 legt eine Sechserbank still, deren Ventile weiterlaufen, und Lamborghini nimmt beim Aventador unter 135 km/h eine komplette Bank vom Netz. Nur der Mercedes-V12 um 2000 entkoppelte Auslassventile, mit zwei Magnetventilen für die Bank. GMs vergleichbare V8-Prüfung wertet unter 0,5 Ohm zur Versorgung bei eingeschalteter Endstufe als Fehler, 20 von 25 Proben, Type B. Das Stellglied bleibt dann aus, alle zwölf Zylinder arbeiten weiter. Masseschluss: P3487.","u":[["h","Steuerleitung des Stellglieds von Zylinder 11 berührt eine Plusleitung"],["m","Windungsschluss in der Stellglied-Spule"],["l","Endstufe im Motorsteuergerät ausgefallen"]],"s":["Motorkontrollleuchte an","Motor bleibt auf allen zwölf Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3485","P3486","P3487","P3484","P3497"]},{"c":"P3489","t":"Zylinder 12 Abschaltung/Einlassventil Steuerkreis/Unterbrechung","e":"Cylinder 12 Deactivation/Intake Valve Control Circuit/Open","d":"P3489 meldet eine Unterbrechung im Kreis zum Stellglied für Abschaltung bzw. Einlassventil von Zylinder 12, der höchsten Zylindernummer dieser Code-Reihe. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Zwölfzylinder mit Abschaltung reichen vom Mercedes-V12 der späten 1990er, der jeden zweiten Zylinder der Zündfolge stilllegte, über den V12 des Lamborghini Aventador, der unter 135 km/h eine Bank abschaltet, bis zu Bentleys W12. Der Mercedes-Motor nutzte einen hydraulischen Magnetventilblock, wie ihn ein solcher Kreis ansteuert; die bankweisen Systeme veröffentlichen nichts dergleichen. GM wertet an V8 einen Kreis ab 200 kOhm bei ruhendem Ausgang als offen. Schlüsse melden P3491 und P3492, Funktionsfehler P3490, das Auslassventil P3493.","u":[["h","Leitung zum Stellglied von Zylinder 12 offen oder durchgescheuert"],["m","Spule des Stellglieds von Zylinder 12 unterbrochen"],["m","Lockerer oder korrodierter Stecker an Zylinder 12"],["l","Endstufe des Steuergeräts ausgefallen"]],"s":["Motorkontrollleuchte an","Motor fährt nicht mehr im Teilzylinderbetrieb","Etwas höherer Verbrauch auf der Autobahn"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3490","P3491","P3492","P3493","P3400","P3497","P0312"]},{"c":"P3490","t":"Zylinder 12 Abschaltung/Einlassventil Steuerung Funktion","e":"Cylinder 12 Deactivation/Intake Valve Control Performance","d":"P3490 betrifft das mechanische Ergebnis an Zylinder 12: Der Kreis des Stellglieds besteht die elektrischen Prüfungen, der Zylinder schaltet aber nicht wie vorgesehen ab oder zu. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bei einem V12 lassen sich bis zu sechs Zylinder stilllegen; bei Ventilabschaltung muss dafür Öldruck die Schaltteile erreichen. Genau dort hatte der M137 von Mercedes Schwächen, mit Ausfällen an Magnetventilblock und Öldruckleitungen. Die Zwölfzylinder von Lamborghini und Bentley schalten ganze Bänke und veröffentlichen keine Ventilüberwachung. Was klemmen kann, erklärt die NHTSA-Beschreibung von GMs Stößeln: federbelastete Sperrstifte, die Öl verschiebt. Elektrische Fehler an Zylinder 12: P3489, P3491, P3492.","u":[["h","Öldruck oder Ölqualität reicht zum Umschalten von Zylinder 12 nicht"],["m","Leck in der Ölversorgung zum Stellglied von Zylinder 12"],["m","Sperrstifte an Zylinder 12 klemmen"],["l","Ventil des Stellglieds mechanisch schwergängig"]],"s":["Motorkontrollleuchte an","Fehlzündungen auf Zylinder 12 (P0312)","Vibrationen bei geringer Last"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3489","P3491","P3492","P3494","P0312","P3497"]},{"c":"P3491","t":"Zylinder 12 Abschaltung/Einlassventil Steuerkreis niedrig","e":"Cylinder 12 Deactivation/Intake Valve Control Circuit Low","d":"Ein Masseschluss an der Steuerleitung des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 12 erzeugt P3491. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Die Zylinderabschaltung des Aventador, eingeführt 2012, legt unter 135 km/h eine Bank mit sechs Zylindern still, Bentleys W12 eine Bank; Zylindercodes veröffentlicht keiner der beiden. An GM-V8 sucht der entsprechende Test bei abgeschaltetem Ausgang alle 250 ms nach unter 0,5 Ohm gegen Masse und braucht 20 Treffer in 25 Proben. Weil eine masseseitig geschaltete Leitung mit Masseschluss das Stellglied bestromt, kann der Zylinder gegen den Willen des Steuergeräts abschalten. Die anderen Kreisfehler sind P3489 (offen) und P3492 (hoch), Auslass niedrig ist P3495.","u":[["h","Steuerleitung von Zylinder 12 mit Masseschluss"],["m","Innerer Schluss im Stellglied von Zylinder 12"],["l","Wassereintritt am Stecker"],["l","Fehlerhafter Treiber im Steuergerät"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt","Mögliche Fehlzündungen auf Zylinder 12"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3489","P3490","P3492","P3495","P0312","P3400"]},{"c":"P3492","t":"Zylinder 12 Abschaltung/Einlassventil Steuerkreis hoch","e":"Cylinder 12 Deactivation/Intake Valve Control Circuit High","d":"P3492 hält einen zu hohen Zustand im Steuerkreis des Abschalt- bzw. Einlassventil-Stellglieds von Zylinder 12 fest, meist einen Schluss zur Versorgung, der bei eingeschaltetem Ausgang auffällt. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Ein V12 kann bis zu sechs Zylinder stilllegen; die Serienmotoren dafür (Mercedes M137, Lamborghini Aventador, Bentley W12) gehen verschieden vor, vom hydraulischen Magnetventilblock (M137) bis zur Bankabschaltung mit weiterlaufenden Ventilen (Bentley). Ein Stellglied an Zylinder 12 gibt es nur bei einer Bauart mit Ventil-Stellgliedern. Das Steuergerät sperrt dann die Abschaltung, der Motor läuft auf allen zwölf. Elektrische Geschwister: P3489 und P3491, Auslass hoch ist P3496.","u":[["h","Steuerleitung von Zylinder 12 mit Schluss zur Versorgungsspannung"],["m","Windungsschluss im Stellglied von Zylinder 12"],["l","Ausgang des Motorsteuergeräts beschädigt"]],"s":["Motorkontrollleuchte an","Motor läuft dauerhaft auf zwölf Zylindern"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3489","P3490","P3491","P3496","P3497"]},{"c":"P3493","t":"Zylinder 12 Auslassventil Steuerkreis/Unterbrechung","e":"Cylinder 12 Exhaust Valve Control Circuit/Open","d":"P3493 gilt für ein getrennt gesteuertes Auslassventil an Zylinder 12 und meldet eine Unterbrechung im Kreis seines Stellglieds. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bentleys W12 und der V12 des Lamborghini Aventador legen Bänke still; Bentley lässt die Ventile ausdrücklich weiterarbeiten, Lamborghini beschreibt nur den Wechsel auf sechs Zylinder unter 135 km/h. Ein GM-Patent behandelt die Auslassventile als eigenen Schritt und legt sie vor den Einlassventilen still; GMs spätere Serientechnik betätigt beide Ventile eines Zylinders über ein Magnetventil. Ein offener Auslasskreis an Zylinder 12 deutet daher auf eine seltene Bauart. Schlüsse melden P3495 und P3496, die Funktion P3494, die Einlassseite P3489.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 12 offen"],["m","Spule des Auslass-Stellglieds von Zylinder 12 unterbrochen"],["m","Stecker am Auslass-Stellglied korrodiert"],["l","Ausgang des Steuergeräts ausgefallen"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb nicht verfügbar"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3494","P3495","P3496","P3489","P3400","P3497"]},{"c":"P3494","t":"Zylinder 12 Auslassventil Steuerung Funktion","e":"Cylinder 12 Exhaust Valve Control Performance","d":"P3494 wird gesetzt, wenn das Auslassventil von Zylinder 12 seinem Befehl nicht folgt, obwohl der Kreis des Stellglieds elektrisch intakt ist. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bei Ventilabschaltung bleibt eine Ladung im Zylinder eingeschlossen. Öffnet das Auslassventil weiter, entweicht dieses Polster, was ein Ford-Patent über den Abgasdruck erkennen will; klemmt es beim Zuschalten geschlossen, belastet verdichtetes Gas den Ventiltrieb. Aventador-V12 und Bentley-W12 schalten Bänke ohne veröffentlichte Ventilschaltung. Für den M137 von Mercedes mit seinem hydraulischen Magnetventilblock ist keine öffentliche Codezuordnung bekannt. Elektrische Fehler dieses Stellglieds: P3493, P3495, P3496; Einlassfunktion: P3490.","u":[["m","Schaltelement am Auslass von Zylinder 12 klemmt"],["m","Öldruck oder Ölqualität für die Auslassumschaltung ungenügend"],["l","Auslass-Stellglied träge"]],"s":["Motorkontrollleuchte an","Ruck oder Schlag beim Zuschalten von Zylinder 12","Fehlzündungen auf Zylinder 12 (P0312)"],"k":["cylinder_deactivation_solenoid","lifter","engine_oil"],"r":["hard",0,[100,3500],[0.5,12]],"f":"MED","x":["P3493","P3495","P3496","P3490","P0312"]},{"c":"P3495","t":"Zylinder 12 Auslassventil Steuerkreis niedrig","e":"Cylinder 12 Exhaust Valve Control Circuit Low","d":"P3495 weist auf ein zu niedriges Signal, meist einen Masseschluss, an der Steuerleitung des Auslassventil-Stellglieds von Zylinder 12 hin. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Für die Zwölfzylinder mit Abschaltung (Bentley W12, Lamborghini Aventador V12, Mercedes M137) ist kein eigenes Auslass-Stellglied je Zylinder dokumentiert; die jüngeren legen ganze Bänke still und lassen die Ventile laufen, wie Bentley für den W12 erklärt. Gibt es ein solches Stellglied doch, folgt die Diagnose dem üblichen Weg: Stecker abziehen, Widerstand der Leitung gegen Masse messen, dann die Spule prüfen. Unterbrechung ist P3493, Plusschluss P3496, der niedrige Fehler der Einlassseite von Zylinder 12 P3491.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 12 an Masse"],["m","Auslass-Stellglied mit innerem Schluss"],["l","Ausgang des Steuergeräts fehlerhaft"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung inaktiv"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3493","P3494","P3496","P3491","P3497"]},{"c":"P3496","t":"Zylinder 12 Auslassventil Steuerkreis hoch","e":"Cylinder 12 Exhaust Valve Control Circuit High","d":"P3496 ist der letzte Code des zylinderweisen Ventilblocks: Er meldet den Steuerkreis des Auslassventils von Zylinder 12 als zu hoch, typischerweise ein Schluss zur Batteriespannung oder eine Spule mit Windungsschluss. Kein Hersteller dokumentiert diesen Code öffentlich; die Codes für Zylinder 9 bis 12 sind in J2012 für Motoren mit mehr als acht Zylindern reserviert. Bentleys W12, gebaut bis 2024, legte bei Teillast oder im Schiebebetrieb eine Sechserbank still. Der V12 des Lamborghini Aventador legte unter 135 km/h eine Bank still. Keiner dokumentiert ein Auslass-Stellglied für Zylinder 12; eine eigene Schaltfolge der Auslassventile zeigt öffentlich vor allem ein GM-Patent. Tritt der Code auf, sperrt das Steuergerät die Abschaltung. P3493 (offen) und P3495 (niedrig) ergänzen die Reihe, P3497 ist der Systemcode für Bank 2.","u":[["m","Leitung zum Auslass-Stellglied von Zylinder 12 mit Schluss zur Batteriespannung"],["m","Windungsschluss in der Spule des Auslass-Stellglieds"],["l","Ausgang des Motorsteuergeräts beschädigt"]],"s":["Motorkontrollleuchte an","Zylinderabschaltung gesperrt"],"k":["cylinder_deactivation_solenoid","wiring_harness","ecm"],"r":["medium",1,[60,900],[0.5,4]],"f":"ME","x":["P3493","P3494","P3495","P3492","P3497"]},{"c":"P3497","t":"Zylinderabschaltsystem Bank 2","e":"Cylinder Deactivation System Bank 2","d":"P3497 ist das Gegenstück zu P3400 für Bank 2, also die Zylinderreihe ohne Zylinder 1: Das Steuergerät stellt fest, dass die Abschaltung dort insgesamt nicht wie befohlen arbeitet, ohne einen Einzelkreis zu benennen. Honda ordnet den Code beim VCM-V6 dem Öldruckschalter C der Kipphebel zu, P3400 dem Schalter B. Laut Bulletin 13-055 (Odyssey und Pilot 2013) entstanden beide nach Kaltstarts mit über 92 psi Öldruck: Die Schieberventile schalteten, und Zylinder fielen ungewollt aus. Abhilfe war eine neue Feder des Überdruckventils. Ram nennt P3497 beim 5,7-l-Hemi eTorque 2023 und behebt ihn per PCM-Software (18-002-25). Typisch sind Warnleuchte, Fehlzündungen und unrunder Warmlauf.","u":[["m","Zu hoher Öldruck beim Kaltstart, etwa durch schwache Überdruckventilfeder"],["h","Zu wenig Öl, falsche Sorte oder überfälliger Ölwechsel"],["m","Schaltbarer Kipphebel oder Stößel auf Bank 2 klemmt oder rastet nicht"],["l","Öldruckschalter der Kipphebel auf Bank 2 meldet falsch"],["l","Motorsteuergeräte-Software, die ein Update braucht"]],"s":["Motorkontrollleuchte an","Fehlzündungscodes auf Zylindern der Bank 2, meist nach Kaltstart","Unruhiger Leerlauf während der Warmlaufphase","Teilzylinderbetrieb entfällt, höherer Verbrauch"],"k":["cylinder_deactivation_solenoid","lifter","oil_control_valve","oil_pressure_switch"],"r":["hard",0,[80,4000],[0.5,12]],"f":"MED","x":["P3400","P3409","P3410","P0300","P2652"]},{"c":"P3498","t":"Zylinder 1 Abschaltung/Einlassventil Funktion","e":"Cylinder 1 Deactivation/Intake Valve Performance","d":"P3498 meldet einen mechanischen Fehler an Zylinder 1: Das Steuergerät hat ihn abgeschaltet, seine Ventile öffnen aber weiter. Damit unterscheidet sich der Code von P3402, der die Ansteuerung betrifft, und von den Kreiscodes P3401, P3403 und P3404. GM prüft das bei den DFM-V8 L84 (5,3 l) und L87 (6,2 l) über den gefilterten Saugrohrdruck, alle 90 Grad Kurbelwinkel; bleibt er über der Schwelle, obwohl Zylinder 1 ruhen soll, führen 22 Fehler in 25 Gelegenheiten zu einem Type-B-Code. Bei Mazdas 2,5-l-Motoren, die Zylinder 1 und 4 abschalten, erscheint er mit P349B, wenn ein Kipphebel herausgefallen oder gebrochen ist (SA-041/18, SA-022/19); Mazda gibt dann einen Austauschmotor frei. Spürbar: Leuchte, unrunder Lauf, Leistungsverlust.","u":[["h","Schaltbarer Kipphebel an Zylinder 1 herausgefallen oder gebrochen (Mazda)"],["m","Abschaltstößel von Zylinder 1 bleibt verriegelt (GM DFM)"],["m","Ölmagnetventil von Zylinder 1 klemmt oder Polkern steht über"],["m","Überfällige Ölwechsel oder falsche Ölsorte"]],"s":["Motorkontrollleuchte an","Unruhiger Leerlauf oder Fehlzündungen auf Zylinder 1 (P0301)","Klappern aus dem Zylinderkopf und Leistungsverlust","Zylinderabschaltung entfällt, höherer Verbrauch"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["hard",0,[100,6000],[0.5,16]],"f":"MED","x":["P3402","P3401","P3400","P349B","P3499","P0301","P0340"]},{"c":"P3499","t":"Zylinder 2 Abschaltung/Einlassventil Funktion","e":"Cylinder 2 Deactivation/Intake Valve Performance","d":"P3499 bedeutet: Zylinder 2 hat beim Abschaltbefehl nicht aufgehört, Luft durchzusetzen. Bei GMs DFM-V8 (L84, L87) versorgt ein Ölmagnetventil im Motor-V beide Stößel des Zylinders; Öldruck schiebt federbelastete Riegel nach innen, sodass der Stößelkörper dem Nocken folgt und das Ventil zu bleibt. Rasten die Riegel nicht aus, misst das Steuergerät während der ausgelassenen Takte zu hohen Saugrohrdruck und legt nach 22 Fehlversuchen in 25 Gelegenheiten diesen Type-B-Code ab. GMs Information PIP5584 zu Silverado und Sierra 2019 nennt ein defektes Ölsteuerventil als eine Ursache. Elektrische Fehler laufen als P3409, P3411 und P3412, die Ansteuerungsfunktion als P3410. Folgen: Leuchte und höherer Verbrauch.","u":[["h","Riegel in den Stößeln von Zylinder 2 fahren nicht ein"],["m","Ölmagnetventil von Zylinder 2 gibt keinen Öldruck weiter"],["m","Zu wenig, aufgeschäumtes oder gealtertes Öl"],["l","Code ohne echten Defekt gespeichert, ECM-Software-Update nötig"]],"s":["Motorkontrollleuchte an","Höherer Verbrauch, weil Zylinder 2 nicht mehr ausgeblendet wird","Ticken aus dem Bereich der Stößel"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["hard",0,[100,4500],[0.5,14]],"f":"MED","x":["P3410","P3409","P3411","P3412","P3498","P349A","P0302"]},{"c":"P349A","t":"Zylinder 3 Abschaltung/Einlassventil Funktion","e":"Cylinder 3 Deactivation/Intake Valve Performance","d":"P349A sagt aus, dass Zylinder 3 seine Ventile weiter betätigt hat, obwohl das Steuergerät ihn abgeschaltet hatte. GM erkennt das bei L84 und L87 an einem Saugrohrdruck, der in den ausgelassenen Takten zu hoch bleibt (Type B nach 22 Fehlprüfungen in 25). Nicht jeder gespeicherte P349A bedeutet einen verschlissenen Stößel: Für Tahoe, Suburban, Yukon und Escalade 2021 beschreibt GM (PIP5731, danach Bulletin 20-NA-204), dass ein Spannungseinbruch beim Anlassen die Abschaltausgänge für einen Fahrzyklus sperren und den Code ohne echten Defekt im Speicher hinterlassen konnte; Abhilfe sind neue ECM-Software und eine Probefahrt mit warmem Motor bei rund 50 bis 70 km/h. Kehrt er zurück, sind Stößel und Magnetventil von Zylinder 3 zu prüfen. Die Ansteuerung betrifft P3418.","u":[["m","Spannungseinbruch beim Start sperrte die Ausgänge, ECM-Software veraltet"],["m","Abschaltstößel von Zylinder 3 entriegelt nicht"],["m","Ölmagnetventil von Zylinder 3 klemmt"],["l","Zu wenig oder gealtertes Öl verzögert das Umschalten"]],"s":["Code im Fehlerspeicher, ohne dass etwas auffällt","Motorkontrollleuchte an, wenn der Fehler echt ist","Tickgeräusch oder höherer Verbrauch"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","ecm"],"r":["hard",0,[0,4500],[0.5,14]],"f":"MED","x":["P3418","P3417","P3419","P3420","P3499","P349B","P0303"]},{"c":"P349B","t":"Zylinder 4 Abschaltung/Einlassventil Funktion","e":"Cylinder 4 Deactivation/Intake Valve Performance","d":"P349B fällt, wenn Zylinder 4 seine Ventile trotz Befehl nicht stilllegt. Beim 2,5-l-Skyactiv-G mit Zylinderabschaltung (CX-5 und Mazda6, 2018–2019) lassen sich die Zylinder 1 und 4 abschalten; die Service-Alerts SA-041/18 und SA-022/19 verbinden P349B mit P3498, P3400, P0304 und P0340 und führen sie auf einen verrutschten oder gebrochenen Kipphebel zurück. Die Werkstatt soll dabei auch die Ölwechsel-Nachweise prüfen; Mazda löst solche Fälle mit einem Tauschmotor. GM verwendet den Code bei L84 und L87 für Zylinder 4 mit demselben Saugrohrdruck-Test wie bei den übrigen sieben Zylindern (Type B). Kreisfehler wären P3425, P3427 und P3428, die Ansteuerungsfunktion P3426. Typisch: Geräusche aus dem Zylinderkopf, unrunder Leerlauf, schwacher Durchzug.","u":[["h","Kipphebel an Zylinder 4 verrutscht oder gebrochen (Mazda)"],["m","Zu lange Ölwechselintervalle oder ungeeignetes Öl"],["m","Abschaltstößel von Zylinder 4 hängt verriegelt (GM DFM)"],["l","Ölmagnetventil von Zylinder 4 defekt"]],"s":["Unruhiger Leerlauf und Fehlzündungen auf Zylinder 4 (P0304)","Klappern oder Klopfen aus dem Bereich des Ventildeckels","Leistungsmangel","Motorkontrollleuchte an"],"k":["valve_train","lifter","cylinder_deactivation_solenoid","engine_oil"],"r":["shop_only",0,[100,6000],[0.5,16]],"f":"MED","x":["P3426","P3425","P3400","P3498","P349A","P349C","P0304","P0340"]},{"c":"P349C","t":"Zylinder 5 Abschaltung/Einlassventil Funktion","e":"Cylinder 5 Deactivation/Intake Valve Performance","d":"P349C heißt: Zylinder 5 ist aktiv geblieben, obwohl das Steuergerät ihn aussetzen lassen wollte. Belegt ist der Code bei GMs Dynamic-Fuel-Management-V8 (L84 mit 5,3 l, L87 mit 6,2 l), die jeden Zylinder abschalten können; die klassischen AFM-V8 legen nur die Zylinder 1, 7, 6 und 4 still. Erkannt wird der Fehler am gefilterten Saugrohrdruck, der über einer Abschaltschwelle bleibt; 22 Fehler in 25 Gelegenheiten ergeben einen Type-B-Code. Für Silverado und Sierra 2019 nennt GM in PIP5584 das Stößel-Ölmagnetventil des Zylinders als Ursache: tauschen und bei den übrigen Ventilen prüfen, ob der Polkern übersteht. Elektrische Fehler dieses Kanals sind P3433, P3435 und P3436. Der Fahrer sieht die Leuchte und merkt Mehrverbrauch.","u":[["h","Ölmagnetventil von Zylinder 5 defekt, Polkern steht über"],["m","Stößel von Zylinder 5 entriegeln nicht"],["l","Schmutz im Öl setzt Magnetventil oder Stößelbohrungen zu"]],"s":["Motorkontrollleuchte an","Motor blendet keine Zylinder mehr aus, Verbrauch steigt","Vibrationen bei geringer Last"],"k":["cylinder_deactivation_solenoid","lifter","valve_train","engine_oil"],"r":["hard",0,[100,4500],[0.5,14]],"f":"MED","x":["P3434","P3433","P3435","P3436","P349B","P349D","P0305"]},{"c":"P349D","t":"Zylinder 6 Abschaltung/Einlassventil Funktion","e":"Cylinder 6 Deactivation/Intake Valve Performance","d":"P349D zeigt an, dass Zylinder 6 in Takten Luft angesaugt und ausgestoßen hat, in denen er dicht bleiben sollte. Die Prüflogik nutzt einen einfachen Effekt: Jeder Ansaugtakt hinterlässt eine Delle im Saugrohrdruck, ein ruhender Zylinder also keine. Fords Patent US8667835B2 und Delphis US7314034B1 beschreiben, wie man diese Pulse Takt für Takt verfolgt. GM wendet das bei L84 und L87 über den gefilterten Saugrohrdruck an (22 Fehler aus 25, Type B). Auch die älteren AFM-V8 von GM schalten Zylinder 6 ab, melden Störungen dort aber über den Bankcode P3400. Mögliche Ursachen sind ein Stößel, dessen Riegel nicht freigeben, ein klemmendes Magnetventil oder schlechtes Öl. Geschwister: P3442 (Ansteuerung), P0306 (Fehlzündung dieses Zylinders).","u":[["h","Riegel der Stößel von Zylinder 6 geben nicht frei"],["m","Ölmagnetventil von Zylinder 6 klemmt"],["m","Zu wenig oder gealtertes Öl"],["l","Falschluft oder MAP-Sensorfehler verfälscht die Druckpulse"]],"s":["Motorkontrollleuchte an","Mehrverbrauch bei Konstantfahrt mit wenig Last","Ticken aus dem Motor-V"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["hard",0,[100,4500],[0.5,14]],"f":"MED","x":["P3442","P3441","P3400","P349C","P349E","P0306","P0106"]},{"c":"P349E","t":"Zylinder 7 Abschaltung/Einlassventil Funktion","e":"Cylinder 7 Deactivation/Intake Valve Performance","d":"P349E betrifft Zylinder 7: Die Abschaltung war befohlen, der Zylinder hat seine Ventile aber weiter bewegt. Bei GMs DFM wird zuerst der Einlassstößel entriegelt; der Auslassstößel kann erst freigeben, wenn sein Nocken wieder auf dem Grundkreis läuft. Ein schwergängiger Riegel lässt deshalb oft die Auslassseite arbeiten. GM erkennt das bei L84 und L87 am Saugrohrdruck, ausgewertet alle 90 Grad Kurbelwinkel, und speichert nach 22 Fehlversuchen aus 25 einen Type-B-Code. Tula Technology, Spezialist für Zylinderausblendung, hat zusätzlich eine Prüfung über Druckpulse im Saugrohr und gemessene gegen modellierte Kurbelwellenbeschleunigung patentiert (US9891137B2). Kreisfehler von Zylinder 7: P3449, P3451, P3452. Spürbar sind Ticken und Warnleuchte.","u":[["h","Schwergängiger Riegel, meist im Auslassstößel von Zylinder 7"],["m","Ölmagnetventil von Zylinder 7 öffnet nicht vollständig"],["m","Zu wenig, zu dünnes oder aufgeschäumtes Öl"]],"s":["Ticken aus dem Ventiltrieb","Motorkontrollleuchte an","Zylinderabschaltung gesperrt, höherer Verbrauch"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["hard",0,[100,4500],[0.5,14]],"f":"MED","x":["P3450","P3449","P3451","P3452","P349D","P349F","P0307"]},{"c":"P349F","t":"Zylinder 8 Abschaltung/Einlassventil Funktion","e":"Cylinder 8 Deactivation/Intake Valve Performance","d":"P349F meldet, dass Zylinder 8 auf Befehl nicht stillgelegt wurde. Die kalifornische OBD-Vorschrift verlangt von den Herstellern, jeden denkbaren hydraulischen oder mechanischen Fehler variabler Ventilsysteme zu analysieren, und nennt als Beispiel einen einzelnen zylinderbezogenen Stift, der nicht in Position geht; aus dieser Pflicht stammen Codes wie dieser. GM setzt ihn bei den DFM-V8 L84 und L87 für Zylinder 8 um: gefilterter Saugrohrdruck über der Abschaltschwelle, 22 von 25 Gelegenheiten, Type B mit Leuchte nach zwei Fahrten. Auch LT2 und LTA legen Zylinder 8 still, eine öffentliche GM-Tabelle mit P349F gibt es für sie aber nicht. Ursachen sind meist ein verriegelt hängender Stößel, ein schwaches Ölmagnetventil oder Ölschlamm. Verwandt: P3458 (Ansteuerung), P0308 (Fehlzündung).","u":[["h","Stößel von Zylinder 8 hängt im verriegelten Zustand"],["m","Schwaches oder klemmendes Ölmagnetventil von Zylinder 8"],["m","Ölschlamm oder Fremdkörper in den Ölkanälen der Stößel"],["l","Nach Spannungseinbruch beim Start gespeichert, ECM-Update nötig"]],"s":["Motorkontrollleuchte nach zwei Fahrten an","Motor läuft dauerhaft auf allen Zylindern, Verbrauch steigt","Tickgeräusch im Leerlauf"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["hard",0,[100,4500],[0.5,14]],"f":"MED","x":["P3458","P3457","P349E","P34A0","P3400","P0308"]},{"c":"P34A0","t":"Zylinder 9 Abschaltung/Einlassventil Funktion","e":"Cylinder 9 Deactivation/Intake Valve Performance","d":"P34A0 ist für einen Zylinder 9 vorgesehen, der nach dem Abschaltbefehl weiter Ventilhub macht; das setzt einen Motor mit mindestens neun Zylindern und Ventilabschaltung je Zylinder voraus. Kein Hersteller dokumentiert diesen Code öffentlich. Die bekannten Zwölfzylinder mit Abschaltung arbeiten bankweise, etwa Bentleys W12 im Bentayga Speed von 2020, der zwischen zwei kompletten Sechserbänken wechselt. Eine Überwachung liefe wie GMs Tests für die Zylinder 1 bis 8 (P3498 bis P349F): Bleibt der Saugrohrdruck in ausgelassenen Takten zu hoch, ist der Zylinder nicht dicht. Die CARB verlangt solche mechanischen Prüfungen für Ventilsteuerungen. Die Ansteuerungsfunktion von Zylinder 9 meldet P3466.","u":[["h","Schaltstößel oder Schaltkipphebel von Zylinder 9 klemmt"],["m","Ölsteuerventil der Abschaltung schaltet nicht"],["m","Zu wenig oder gealtertes Öl"]],"s":["Motorkontrollleuchte an","Unrunder Lauf im Teilzylinderbetrieb","Höherer Verbrauch"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["shop_only",0,[150,6000],[1,16]],"f":"MED","x":["P3466","P3465","P349F","P34A1","P0309"]},{"c":"P34A1","t":"Zylinder 10 Abschaltung/Einlassventil Funktion","e":"Cylinder 10 Deactivation/Intake Valve Performance","d":"P34A1 hieße, dass Zylinder 10 seine Ventile weiter öffnet, während er abgeschaltet sein soll. Kein Hersteller dokumentiert diesen Code öffentlich; sinnvoll ist er nur bei V10-, V12- oder W12-Motoren. Lamborghini hat etwa den Aventador LP 700-4 mit einem Cylinder Deactivation System ausgestattet, das unter 135 km/h eine Bank ruhen lässt, eine öffentliche Diagnosetabelle mit P34A1 gibt es aber nicht. Die Prüfphysik ist dieselbe wie bei kleineren Motoren: Fords Patent US8667835B2 verfolgt Anstieg und Abfall des Saugrohrdrucks über aufeinanderfolgende Ansaugtakte und vergleicht sie mit dem befohlenen Muster. Ursachen wären wie bei den V8-Codes P3498 bis P349F ein klemmendes Schaltelement, ein defektes Ölsteuerventil oder schlechtes Öl. Die Ansteuerung betrifft P3474.","u":[["h","Schaltelement von Zylinder 10 entriegelt nicht"],["m","Ölsteuerventil der Abschaltung klemmt"],["m","Ölstand zu niedrig oder Öl gealtert"]],"s":["Motorkontrollleuchte an","Teilzylinderbetrieb wird nicht mehr genutzt","Ungleichmäßiger Lauf bei geringer Last"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["shop_only",0,[150,6000],[1,16]],"f":"MED","x":["P3474","P3473","P34A0","P34A2","P0310"]},{"c":"P34A2","t":"Zylinder 11 Abschaltung/Einlassventil Funktion","e":"Cylinder 11 Deactivation/Intake Valve Performance","d":"P34A2 benennt einen mechanischen Abschaltfehler an Zylinder 11: Die Ventile arbeiteten weiter, obwohl der Zylinder abgeschaltet war. Kein Hersteller dokumentiert diesen Code öffentlich. Am nächsten kommt ihm Mercedes' Active Cylinder Control am 5,8-l-V12 von CL 600 und S 600 ab 2001: Sie legte eine Bank still und koppelte deren Auslassventile über zwei Magnetventile ab – ein hängendes Schaltelement ergäbe dort genau das Fehlerbild dieses Codes. Bei Achtzylindern nutzt GM dafür P3498 bis P349F, wertet den Saugrohrdruck aus und speichert Type B nach 22 Fehlern in 25 Prüfungen. Die Ansteuerungsfunktion von Zylinder 11 meldet P3482, eine Fehlzündung dort P0311.","u":[["h","Ventilschaltelement von Zylinder 11 klemmt"],["m","Öldruckversorgung der Schaltelemente gestört"],["l","Zu wenig oder gealtertes Öl"]],"s":["Motorkontrollleuchte an","Unrunder Lauf, wenn eine Bank abgeschaltet ist","Höherer Verbrauch"],"k":["valve_train","lifter","cylinder_deactivation_solenoid","engine_oil"],"r":["shop_only",0,[150,6000],[1,16]],"f":"MED","x":["P3482","P3481","P34A1","P34A3","P0311"]},{"c":"P34A3","t":"Zylinder 12 Abschaltung/Einlassventil Funktion","e":"Cylinder 12 Deactivation/Intake Valve Performance","d":"P34A3 schließt die Reihe mit dem letzten Zylinder eines Zwölfzylinders ab: Zylinder 12 sollte abschalten, seine Ventile liefen aber weiter. Kein Hersteller dokumentiert diesen Code öffentlich. Eine eigene Prüfung braucht es, weil die CARB absichtlich stillgelegte Zylinder aus der Definition der Fehlzündung herausnimmt; die Aussetzerüberwachung übersieht also einen Zylinder, der ohne Kraftstoff weiter Luft pumpt. Delphis Patent US7314034B1 bestimmt den Zustand jedes Zylinders aus dem Muster der Druckpulse im Saug- oder Abgaskrümmer, ähnlich dem Prinzip, das GM für die Zylinder 1 bis 8 nutzt. Bei bankweise schaltenden V12 fiele ein Defekt zuerst durch unrunden Lauf und die Warnleuchte auf. Die Ansteuerung betrifft P3490.","u":[["h","Schaltelement an Stößel oder Kipphebel von Zylinder 12 klemmt"],["m","Ölsteuerventil der Abschaltung klemmt"],["m","Zu wenig oder gealtertes Öl"]],"s":["Motorkontrollleuchte an","Unrunder Lauf bei geringer Last","Höherer Verbrauch"],"k":["lifter","valve_train","cylinder_deactivation_solenoid","engine_oil"],"r":["shop_only",0,[150,6000],[1,16]],"f":"MED","x":["P3490","P3489","P34A2","P34A0","P0312"]},{"c":"P34A4","t":"Nockenwellenversteller A Temperaturfühler Stromkreis Bank 1","e":"A Camshaft Position Actuator Temperature Sensor Circuit Bank 1","d":"P34A4 meldet einen allgemeinen elektrischen Fehler am Temperaturfühler des Einlass-Nockenwellenverstellers A auf Bank 1, etwa eine gebrochene Leitung, einen abgezogenen Stecker bzw. einen Wert ohne gültiges Fenster. Einen solchen Fühler haben elektrisch angetriebene Versteller: Ein Patent von Aisin setzt ihn auf die Treiberplatine des Stellmotors und nimmt den Motorstrom zurück, wenn die Platine dauerhaft heiß bleibt. NTN-SNR führt P34A4 als Temperaturfühler der Einlassverstellung mit elektrischem Fehler. Nissan nutzt die Familie bei der elektrischen Einlass-Ventilsteuerung von Pathfinder und QX60 (2018), veröffentlicht aber nur die Plausibilitätscodes P34A5 und P34A9. Ohne gültige Temperatur kann das Steuergerät den Motor nicht mehr schützen und schränkt die Verstellung meist ein. Zu niedrig und zu hoch sind P34A6 und P34A7.","u":[["h","Stecker am Versteller locker oder korrodiert, Fühlerleitung gebrochen"],["m","Temperaturfühler im Versteller bzw. dessen Elektronik ausgefallen"],["l","Fehler im Steuergerät, das den elektrischen Versteller ansteuert"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 1 eingeschränkt oder in Grundstellung gehalten","Beim Fahren oft kein spürbarer Unterschied"],"k":["cam_actuator_a_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,700],[0.5,3]],"f":"MEL","x":["P34A5","P34A6","P34A7","P34A8","P34B4"]},{"c":"P34A5","t":"Nockenwellenversteller A Temperaturfühler Bereich/Funktion Bank 1","e":"A Camshaft Position Actuator Temperature Sensor Range/Performance Bank 1","d":"Bei P34A5 ist der Temperaturwert des Einlassverstellers A (Bank 1) elektrisch gültig, passt aber nicht ins Bild. Nissan belegt den Code für Pathfinder (R52) und Infiniti QX60 des Modelljahres 2018, gebaut vor dem 18. Dezember 2017: Nach Starts bei Außentemperaturen um oder unter 0 °C ging die Motorkontrollleuchte an. Bulletin NTB18-016 ließ das Steuergerät der elektrischen Einlass-Ventilsteuerung gegen eines mit neuer Software tauschen und danach die Lage des Stellers anlernen; die Neufassung NTB18-016a verweist stattdessen auf die Umprogrammier-Aktion NTB18-072. Andere Verstellcodes wie P0011 sind vorher zu klären. Außerhalb dieses Softwarefalls kommen ein driftender Fühler oder ein Wackelkontakt infrage. Fahrer merken meist nichts. Bank 2 meldet P34A9.","u":[["h","Software des Steuergeräts der elektrischen Ventilsteuerung (Nissan 2018: Fehlalarm beim Kaltstart)"],["m","Temperaturfühler driftet aus seinem erwarteten Bereich"],["l","Wackelkontakt am Stecker des Verstellers"]],"s":["Motorkontrollleuchte an, oft nach einem Kaltstart","Meist keine Auffälligkeit im Fahrverhalten"],"k":["cam_actuator_a_temp_sensor_b1"],"r":["medium",0,[80,900],[0.5,2.5]],"f":"MEDL","x":["P34A4","P34A6","P34A7","P34A9","P0011"]},{"c":"P34A6","t":"Nockenwellenversteller A Temperaturfühler Stromkreis zu niedrig Bank 1","e":"A Camshaft Position Actuator Temperature Sensor Circuit Low Bank 1","d":"P34A6 heißt: Das Temperatursignal des Einlassverstellers auf Bank 1 unterschreitet seinen Mindestwert. Welcher Fühlertyp verbaut ist, nennt keine uns vorliegende Quelle. Beim üblichen NTC-Heißleiter bedeutet wenig Spannung viel Wärme; liegt die Signalleitung an Masse oder ist der Fühler innen kurzgeschlossen, hält das Steuergerät den Versteller deshalb für überhitzt. Elektrische Versteller schützen Motor und Endstufe vor Hitze – Aisin beschreibt, den Strom stufenweise zu senken, solange die Platine heiß bleibt –, ein falscher Heißwert kann die Verstellung also bremsen. NTN-SNR führt P34A6 als zu kleines Signal des Einlass-Temperaturfühlers. Ein Hersteller beschreibt den Code nicht näher. Zu hoch ist P34A7, Bank 2 P34AA.","u":[["h","Signalleitung mit Masseschluss (am Zylinderkopf durchgescheuert)"],["m","Fühler intern kurzgeschlossen"],["l","Versteller durch schwergängige Mechanik tatsächlich überhitzt"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 1 begrenzt, weniger Durchzug"],"k":["cam_actuator_a_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,700],[0.5,3]],"f":"MEL","x":["P34A4","P34A5","P34A7","P34AA","P34B6"]},{"c":"P34A7","t":"Nockenwellenversteller A Temperaturfühler Stromkreis zu hoch Bank 1","e":"A Camshaft Position Actuator Temperature Sensor Circuit High Bank 1","d":"P34A7 setzt das Steuergerät, wenn der Temperaturfühler des Einlass-Nockenwellenverstellers A auf Bank 1 eine Spannung über seiner oberen Grenze liefert. Meist ist die Fühlerleitung oder deren Masse unterbrochen, oder das Signal hat Kontakt zu einer Versorgungsspannung; bei einem NTC-Fühler wirkt das wie ein unplausibel kalter Versteller. Damit fehlt dem Steuergerät ein brauchbarer Wert für den Hitzeschutz, und es verstellt nur noch vorsichtig. NTN-SNR ordnet P34A7 der Einlassverstellung mit zu hohem Signal zu. Nissan verbaut solche Fühler am elektrischen Einlassversteller von Pathfinder und QX60 (2018), hat diesen Code aber nicht veröffentlicht. Zuerst Stecker am Versteller und Kabelführung über dem Motor prüfen. Zu niedrig ist P34A6.","u":[["h","Signal- oder Masseleitung des Fühlers unterbrochen"],["m","Signalleitung mit Schluss gegen eine Versorgungsspannung"],["m","Fühler intern unterbrochen"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 1 reduziert","Meist kaum Auswirkung beim Fahren"],"k":["cam_actuator_a_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,700],[0.5,3]],"f":"MEL","x":["P34A4","P34A5","P34A6","P34AB","P34B7"]},{"c":"P34A8","t":"Nockenwellenversteller A Temperaturfühler Stromkreis Bank 2","e":"A Camshaft Position Actuator Temperature Sensor Circuit Bank 2","d":"P34A8 ist das Gegenstück zu P34A4 auf Bank 2: Das Steuergerät erkennt am Temperaturfühler des Einlassverstellers A auf der Seite ohne Zylinder 1 eine Unterbrechung oder einen anderen Kreisfehler. Diese Bank gibt es nur bei V- und Boxermotoren. Der einzige belegte Nutzer der Familie, Nissans elektrische Einlass-Ventilsteuerung in Pathfinder und QX60 (2018), überwacht beide Bänke getrennt (Plausibilitätscodes P34A5 und P34A9); P34A8 selbst steht in keiner öffentlichen Herstellerunterlage. Bei NTN-SNR steht er als elektrischer Fehler des einlassseitigen Temperaturfühlers der zweiten Bank. Häufig sind ein korrodierter Stecker, ein am Zylinderkopf aufgescheuerter Kabelbaum oder ein defekter Fühler. Bereich, zu niedrig und zu hoch melden P34A9, P34AA und P34AB.","u":[["h","Stecker am Versteller von Bank 2 korrodiert oder nicht eingerastet"],["m","Kabelbaum am Zylinderkopf aufgescheuert"],["m","Temperaturfühler defekt"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 2 eingeschränkt"],"k":["cam_actuator_a_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,750],[0.5,3]],"f":"MEL","x":["P34A9","P34AA","P34AB","P34A4","P34B8"]},{"c":"P34A9","t":"Nockenwellenversteller A Temperaturfühler Bereich/Funktion Bank 2","e":"A Camshaft Position Actuator Temperature Sensor Range/Performance Bank 2","d":"P34A9 betrifft die Plausibilitätsprüfung des Temperaturfühlers am Einlassversteller A auf Bank 2. Nissan nennt ihn zusammen mit P34A5 in den Bulletins NTB18-016 (Pathfinder 2018) und ITB18-009 (QX60 2018): Fahrzeuge, die vor dem 18. Dezember 2017 gebaut wurden, konnten nach einem Start bei Frost einen oder beide Codes speichern und die Kontrollleuchte einschalten. Ursache war das Steuergerät der elektrischen Einlass-Ventilsteuerung; Nissan tauschte es zunächst gegen eines mit neuerer Software und stellte später auf eine Umprogrammierung um. Sind P0021 oder andere Verstellcodes gespeichert, haben sie Vorrang. Ohne diesen Softwarebezug kommen ein Fühler mit wanderndem Wert oder ein schlechter Kontakt am Versteller von Bank 2 infrage. Bank 1 meldet P34A5.","u":[["h","Steuergeräte-Software (Nissan Pathfinder/QX60 2018, Umprogrammierung)"],["m","Fühlerwert wandernd oder träge"],["l","Schlechter Kontakt am Stecker des Verstellers von Bank 2"]],"s":["Motorkontrollleuchte nach einem Start bei Frost","Motor läuft meist normal"],"k":["cam_actuator_a_temp_sensor_b2"],"r":["medium",0,[80,900],[0.5,2.5]],"f":"MEDL","x":["P34A8","P34AA","P34AB","P34A5","P0021"]},{"c":"P34AA","t":"Nockenwellenversteller A Temperaturfühler Stromkreis zu niedrig Bank 2","e":"A Camshaft Position Actuator Temperature Sensor Circuit Low Bank 2","d":"Mit P34AA meldet der Temperaturfühler am Einlassversteller von Bank 2 eine Spannung unterhalb des erlaubten Bereichs. Ob das einem Heißwert entspricht, hängt von der Bauart ab, die keine öffentliche Quelle nennt; bei einem gängigen NTC-Heißleiter sähe es wie Überhitzung aus, und das Steuergerät könnte den Stellerstrom begrenzen oder die Verstellung dieser Bank aussetzen. In der Praxis kommen eine am Zylinderkopf an Masse liegende Signalleitung, bei früheren Motorarbeiten eingeklemmte Kabel oder ein kurzgeschlossener Fühler infrage. NTN-SNR führt P34AA als zu kleines Signal des Einlass-Temperaturfühlers der zweiten Bank; einen Herstellertext gibt es nicht öffentlich. Vergleiche Bank 1 (P34A6) und den Hoch-Code P34AB.","u":[["h","Signalleitung am Zylinderkopf an Masse"],["m","Kabel bei früheren Motorarbeiten eingeklemmt"],["m","Fühler intern kurzgeschlossen"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 2 ausgesetzt, etwas weniger Leistung"],"k":["cam_actuator_a_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,750],[0.5,3]],"f":"MEL","x":["P34A8","P34A9","P34AB","P34A6","P34BA"]},{"c":"P34AB","t":"Nockenwellenversteller A Temperaturfühler Stromkreis zu hoch Bank 2","e":"A Camshaft Position Actuator Temperature Sensor Circuit High Bank 2","d":"P34AB steht für eine Spannung über der oberen Grenze am Temperaturfühler des Einlassverstellers A auf Bank 2. Klassisch sind unterbrochene Signal- oder Masseleitungen, ebenso ein Schluss gegen höhere Spannung; oft wurde bei einem Werkstattbesuch ein Stecker abgezogen und nicht wieder eingerastet. Weil sich der Stellmotor unter Last erwärmt, braucht das Steuergerät diesen Wert – das Aisin-Patent senkt den Strom schrittweise, solange es heiß bleibt –, und ohne ihn hält es den Versteller von Bank 2 meist zurück. NTN-SNR ordnet den Code der Einlassseite der zweiten Bank zu; kein Hersteller veröffentlicht ihn. Auf Bank 1 entspricht ihm P34A7, zu niedrig ist P34AA.","u":[["h","Stecker am Versteller nach Wartung ab oder nicht eingerastet"],["m","Signal- oder Masseleitung unterbrochen"],["l","Signal mit Schluss gegen höhere Spannung"]],"s":["Motorkontrollleuchte an","Einlassverstellung auf Bank 2 zurückgehalten"],"k":["cam_actuator_a_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,750],[0.5,3]],"f":"MEL","x":["P34A8","P34A9","P34AA","P34A7","P34BB"]},{"c":"P34AC","t":"Nockenwellenversteller A Positionssensor A Stromkreis Bank 1","e":"A Camshaft Position Actuator Position Sensor A Circuit Bank 1","d":"P34AC erfasst jeden elektrischen Fehler im Kreis von Positionssensor A des Einlassverstellers auf Bank 1. Bei Motoren mit elektrischem Einlassversteller meldet dieser Sensor dem Steuergerät, wo der Stellmotor gerade steht. Mitsubishi belegt den Code für den Outlander 2022: Das Steuergerät der elektrischen Einlass-Ventilsteuerung speichert ihn, wenn die Sensorspannung eine Sekunde oder länger unter- oder oberhalb ihres Fensters liegt; als Ursachen nennt es Leitungen mit Unterbrechung oder Kurzschluss sowie den Steller selbst. Im Notlauf bleibt der Versteller in Grundstellung, die Saugrohrklappe öffnet, die Abgasrückführung ruht und der geschichtete Kaltstart entfällt. Geprüft wird, sobald der Motor eine Sekunde über 2000/min lief; zuerst erscheint ein vorläufiger Code. Zu niedrig und zu hoch melden P34AE und P34AF.","u":[["h","Kabelbaum zum Steller unterbrochen oder kurzgeschlossen, Stecker locker"],["m","Positionssensor im elektrischen Steller defekt (Steller tauschen)"],["l","Steuergerät der elektrischen Ventilsteuerung defekt"]],"s":["Motorkontrollleuchte an","Einlassnocke in Grundstellung, weniger Drehmoment untenherum","Rauerer Kaltstart, etwas höherer Verbrauch"],"k":["cam_actuator_a_pos_sensor_b1","sensor_wiring"],"r":["medium",0,[80,900],[0.5,3]],"f":"MEL","x":["P34AD","P34AE","P34AF","P34B0","P34C8","P2B3F"]},{"c":"P34AD","t":"Nockenwellenversteller A Positionssensor A Bereich/Funktion Bank 1","e":"A Camshaft Position Actuator Position Sensor A Range/Performance Bank 1","d":"P34AD ist ein Plausibilitätsfehler: Das Signal von Positionssensor A des Einlassverstellers auf Bank 1 ist elektrisch vorhanden, stimmt aber nicht mit den übrigen Informationen des Steuergeräts überein. Beim Mitsubishi Outlander 2022, der seinen Einlassversteller elektrisch dreht, vergleicht das Steuergerät die Lage des Stellmotors mit der Phase, die der Einlass-Nockenwellensensor liefert, und speichert P34AD bei Widerspruch; als Ursachen nennt es Leitungsfehler und den Steller. Praktisch stehen ein verschlissener oder durchrutschender Steller, eine nach Reparaturen nicht neu angelernte Lage oder ein gestörtes Nockenwellensignal vorn; Nissan verlangt bei seiner gleichartigen elektrischen Einlass-Ventilsteuerung nach einem Steuergerätetausch das Anlernen der Stellerlage. Der Versteller bleibt dann in Grundstellung.","u":[["h","Elektrischer Steller verschlissen, schwergängig oder durchrutschend"],["m","Stellerlage nach Reparatur nicht neu angelernt"],["m","Signal des Einlass-Nockenwellensensors oder Steuertrieb gestört"],["l","Sporadischer Leitungsfehler"]],"s":["Motorkontrollleuchte an","Einlass-Steuerzeit fest, schwächeres Ansprechen untenherum","Ggf. begleitende Verstellcodes wie P0011"],"k":["cam_actuator_a_pos_sensor_b1"],"r":["hard",0,[100,1000],[1,4]],"f":"MEDL","x":["P34AC","P34AE","P34AF","P34B1","P0011","P2B40"]},{"c":"P34AE","t":"Nockenwellenversteller A Positionssensor A Stromkreis zu niedrig Bank 1","e":"A Camshaft Position Actuator Position Sensor A Circuit Low Bank 1","d":"P34AE heißt: Die Spannung von Positionssensor A an der Einlassseite von Bank 1 erreicht ihren Mindestwert nicht. Der Mitsubishi Outlander 2022 bewegt die Einlassnocke mit einem Elektromotor, wertet den Code im Steuergerät der elektrischen Ventilsteuerung aus und verweist auf einen unterbrochenen oder kurzgeschlossenen Stellerkreis oder einen defekten Steller; eine Verzögerungszeit nennt er hier, anders als beim Kreis- und beim Hoch-Code, nicht. Häufig liegt die Signalleitung an Masse, fehlt die Sensorversorgung oder ist ein Hallelement im Motor kurzgeschlossen. Das Steuergerät stellt die Verstellung dann ein und hält die Nocke in Grundstellung; das kostet Drehmoment untenherum, und weil der geschichtete Kaltstart entfällt, kann der Motor kalt unruhiger anspringen. Zu hoch ist P34AF, Bank 2 P34B2.","u":[["h","Signalleitung mit Masseschluss"],["m","Sensorversorgung unterbrochen oder kurzgeschlossen"],["m","Hallsensor im Stellmotor kurzgeschlossen (Steller tauschen)"]],"s":["Motorkontrollleuchte an","Weniger Durchzug bei niedriger Drehzahl","Unruhiger Lauf nach dem Kaltstart"],"k":["cam_actuator_a_pos_sensor_b1","sensor_wiring"],"r":["medium",0,[60,900],[0.5,3]],"f":"MEL","x":["P34AC","P34AD","P34AF","P34B2","P2B41"]},{"c":"P34AF","t":"Nockenwellenversteller A Positionssensor A Stromkreis zu hoch Bank 1","e":"A Camshaft Position Actuator Position Sensor A Circuit High Bank 1","d":"P34AF wird gespeichert, wenn Positionssensor A des Einlassverstellers auf Bank 1 mindestens eine Sekunde lang eine Spannung über der oberen Grenze liefert. Für den Outlander 2022 belegt Mitsubishi den Code und nennt neben dem Kabelbaum den Hallsensor von Motor 1 im elektrischen Steller – ein Hinweis, dass Positionssensor A ein Hallelement im Stellmotor ist. Üblich: Sensormasse unterbrochen, Signal mit Schluss gegen Versorgungsspannung oder Hallsensor ausgefallen; weil der Sensor im Steller sitzt, bedeutet ein Sensordefekt meist einen neuen Steller. Im Notlauf bleibt der Einlassversteller in Grundstellung, die Saugrohrklappe öffnet und die Abgasrückführung wird abgeschaltet. Zu niedrig ist P34AE, Bank 2 P34B3.","u":[["h","Sensormasse unterbrochen oder Stecker korrodiert"],["m","Signalleitung mit Schluss gegen Versorgungsspannung"],["m","Hallsensor des Stellmotors ausgefallen (Steller tauschen)"]],"s":["Motorkontrollleuchte an","Einlassversteller in Grundstellung, weniger Leistung","Etwas höherer Kraftstoffverbrauch"],"k":["cam_actuator_a_pos_sensor_b1","sensor_wiring"],"r":["medium",0,[60,900],[0.5,3]],"f":"MEL","x":["P34AC","P34AD","P34AE","P34B3","P2B42"]},{"c":"P34B0","t":"Nockenwellenversteller A Positionssensor A Stromkreis Bank 2","e":"A Camshaft Position Actuator Position Sensor A Circuit Bank 2","d":"P34B0 ist der Kreiscode für Positionssensor A am Einlassversteller von Bank 2 und betrifft damit nur V- und Boxermotoren. Kein Hersteller veröffentlicht ihn. Mitsubishi belegt für den Outlander 2022, der nur die Codes von Bank 1 nutzt, das Gegenstück P34AC: Dort meldet der Sensor den Winkel des elektrischen Stellmotors, und eine Spannung außerhalb des Fensters über eine Sekunde löst den Fehler aus. Ein zweibankiger Motor mit elektrischen Verstellern würde seinen zweiten Steller ebenso überwachen. Mercedes dagegen führt die Sensoren seiner CAMTRONIC-Hubsteller unter den Positionssensor-A-Codes von Nockenwelle B (P34BD, P34BE); was als Steller gilt, hängt also vom Hersteller ab. Zu prüfen sind Stecker, Kabelbaum und Steller auf Bank 2.","u":[["h","Stecker oder Kabelbaum zum Steller von Bank 2 unterbrochen oder kurzgeschlossen"],["m","Positionssensor im Steller defekt"],["l","Steuergerät defekt"]],"s":["Motorkontrollleuchte an","Einlassverstellung von Bank 2 in Grundstellung","Ggf. weniger Leistung und ungleicher Lauf zwischen den Bänken"],"k":["cam_actuator_a_pos_sensor_b2","sensor_wiring"],"r":["medium",0,[80,950],[0.5,3.5]],"f":"MEL","x":["P34B1","P34B2","P34B3","P34AC","P2B43"]},{"c":"P34B1","t":"Nockenwellenversteller A Positionssensor A Bereich/Funktion Bank 2","e":"A Camshaft Position Actuator Position Sensor A Range/Performance Bank 2","d":"P34B1: Positionssensor A des Einlassverstellers auf Bank 2 liefert ein elektrisch intaktes, aber unplausibles Signal. Keine öffentliche Herstellerunterlage verwendet diesen Code. Am nächsten kommt der Bank-1-Code P34AD beim Mitsubishi Outlander 2022: Dort gleicht das Steuergerät des elektrischen Verstellers die Motorlage mit dem Einlass-Nockenwellensensor ab und meldet Abweichungen. Mercedes nutzt denselben Fehlertyp auf der Auslassseite für die CAMTRONIC-Hubsteller (P34BD, P34C1); Bulletin LI05.20-P-080192 behebt ihn mit neuer Motorsoftware und Stellern mit neuerer Teilenummer. Auf Bank 2 sind ein schwergängiger oder abgenutzter Steller, eine verlorene angelernte Lage oder ein Problem mit dem Nockenwellensignal (siehe P0021) wahrscheinlich. Der Versteller bleibt dann in Grundstellung.","u":[["h","Steller auf Bank 2 klemmend oder verschlissen"],["m","Angelernte Stellerlage verloren oder Software veraltet"],["m","Signal der Einlassnockenwelle von Bank 2 gestört"]],"s":["Motorkontrollleuchte an","Einlass-Steuerzeit von Bank 2 fest, weniger Leistung","Ggf. weitere Verstellcodes wie P0021"],"k":["cam_actuator_a_pos_sensor_b2"],"r":["hard",0,[100,1100],[1,4.5]],"f":"MEDL","x":["P34B0","P34B2","P34B3","P34AD","P0021","P2B44"]},{"c":"P34B2","t":"Nockenwellenversteller A Positionssensor A Stromkreis zu niedrig Bank 2","e":"A Camshaft Position Actuator Position Sensor A Circuit Low Bank 2","d":"P34B2 wird gesetzt, wenn die Spannung von Positionssensor A am Einlassversteller von Bank 2 das zulässige Fenster nach unten verlässt. Öffentlich dokumentiert kein Hersteller diesen Code. Beim Mitsubishi Outlander 2022 wertet das Steuergerät der elektrischen Ventilsteuerung die Bank-1-Fassung P34AE aus und führt sie auf den Stellerkreis oder den Steller zurück. Bei Mercedes steht der passende Niedrig-Code der CAMTRONIC-Auslasssensoren auf Bank 2 (P34C2) für einen Masseschluss; laut Bulletin LI05.20-P-080192 soll die Werkstatt den Motorkabelbaum nahe der Stirnwand auf Hitzespuren ansehen. Auf Bank 2 zuerst eine an Masse liegende Signalleitung, eine fehlende Sensorversorgung oder einen kurzgeschlossenen Sensor ausschließen. Zu hoch ist P34B3, Bank 1 P34AE.","u":[["h","Signalleitung an Masse, Kabelbaum durch Hitze beschädigt"],["m","Sensorversorgung unterbrochen"],["m","Sensor im Steller kurzgeschlossen"]],"s":["Motorkontrollleuchte an","Einlassverstellung von Bank 2 abgeschaltet","Ggf. Codes weiterer Sensoren an derselben Versorgung"],"k":["cam_actuator_a_pos_sensor_b2","sensor_wiring"],"r":["medium",0,[60,950],[0.5,3.5]],"f":"MEL","x":["P34B0","P34B1","P34B3","P34AE","P2B45"]},{"c":"P34B3","t":"Nockenwellenversteller A Positionssensor A Stromkreis zu hoch Bank 2","e":"A Camshaft Position Actuator Position Sensor A Circuit High Bank 2","d":"P34B3 kennzeichnet ein Signal über der oberen Grenze von Positionssensor A am Einlassversteller von Bank 2. Typisch sind eine unterbrochene Masse, ein Signal, das Versorgungsspannung abbekommt, oder ein ausgefallener Sensor. Eine Herstellerbeschreibung des Codes ist nicht öffentlich. Am nächsten liegt Mitsubishis Bank-1-Code P34AF beim Outlander 2022: Der zu hohe Wert muss mindestens eine Sekunde anstehen, und als mögliche Ursache steht der Hallsensor des Stellmotors. Bei elektrischen Verstellern steckt der Sensor also im Steller, ein Sensorfehler bedeutet meist einen neuen Steller. NTN-SNR führt P34B3 als einlassseitigen Positionssensor A der zweiten Bank mit zu hohem Signal. Der Motor läuft weiter, der Versteller von Bank 2 bleibt in Grundstellung.","u":[["h","Sensormasse unterbrochen"],["m","Signalleitung mit Kontakt zu einer Versorgungsspannung"],["m","Hallsensor im Steller defekt (Steller tauschen)"]],"s":["Motorkontrollleuchte an","Einlassversteller von Bank 2 in Grundstellung gehalten"],"k":["cam_actuator_a_pos_sensor_b2","sensor_wiring"],"r":["medium",0,[60,950],[0.5,3.5]],"f":"MEL","x":["P34B0","P34B1","P34B2","P34AF","P2B46"]},{"c":"P34B4","t":"Nockenwellenversteller B Temperaturfühler Stromkreis Bank 1","e":"B Camshaft Position Actuator Temperature Sensor Circuit Bank 1","d":"Mit P34B4 stellt das Steuergerät fest, dass sich der Kreis des Temperaturfühlers am Nockenwellenversteller B (Bank 1) nicht auswerten lässt – wegen einer Unterbrechung, eines gelösten Steckers oder eines Werts ohne gültigen Zustand. NTN-SNR ordnet den Buchstaben B der Auslassnockenwelle zu; gemeint ist also ein Auslassversteller mit Elektromotor, dessen Elektronik vor Überhitzung bewahrt werden muss. Ein Aisin-Patent setzt einen solchen Fühler auf die Steuerplatine des Motors und nennt die Einlasswelle nur beispielhaft. Öffentlich beschreibt kein Hersteller P34B4; der Mitsubishi Outlander 2022 etwa verstellt nur den Einlass elektrisch, den Auslass dagegen hydraulisch über ein Magnetventil. Bis zur Reparatur ist die Auslassverstellung meist eingeschränkt. Zu niedrig bzw. zu hoch: P34B6, P34B7.","u":[["h","Stecker am Auslassversteller nicht eingerastet oder Leitung gebrochen"],["m","Temperaturfühler in der Elektronik des Verstellers ausgefallen"],["l","Eingangsstufe im ansteuernden Steuergerät defekt"]],"s":["Motorkontrollleuchte leuchtet","Auslass-Steuerzeit auf Bank 1 fest oder begrenzt","Fahrbetrieb meist unauffällig"],"k":["cam_actuator_b_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,800],[0.5,3]],"f":"MEL","x":["P34B5","P34B6","P34B7","P34B8","P34A4","P34C8"]},{"c":"P34B5","t":"Nockenwellenversteller B Temperaturfühler Bereich/Funktion Bank 1","e":"B Camshaft Position Actuator Temperature Sensor Range/Performance Bank 1","d":"P34B5 ist die Plausibilitätsprüfung für den Temperaturwert des Auslassverstellers B auf Bank 1: Der Kreis ist in Ordnung, Wert oder Verlauf wirken aber unglaubwürdig. CARB verlangt solche Prüfungen für Eingangsfühler der Ventilverstellung, soweit machbar, und zwar möglichst in beide Richtungen. Nach welchen Kriterien ein Hersteller hier urteilt, ist nicht veröffentlicht; P34B5 selbst dokumentiert keiner. Ein Hinweis kommt vom Einlass-Gegenstück P34A5: Nissan führte Fehlmeldungen nach Kaltstarts beim Pathfinder 2018 auf die Software des Steuergeräts zurück und behob sie per Update. Wichtig ist der Wert, weil Aisins Patent den Versteller von seinem Anschlag wegdreht, sobald die Platine eine Zeit lang über einer Schwelle liegt, damit der Haltestrom sinkt. Bank 2: P34B9.","u":[["m","Steuergeräte-Software bewertet den Wert falsch (Update vorhanden?)"],["m","Temperaturfühler im Versteller driftet"],["l","Wackelkontakt verfälscht den Messwert"]],"s":["Motorkontrollleuchte, teils nur nach einem Kaltstart","Motorverhalten in den meisten Fällen unverändert"],"k":["cam_actuator_b_temp_sensor_b1"],"r":["medium",0,[80,900],[0.5,3]],"f":"MEDL","x":["P34B4","P34B6","P34B7","P34B9","P34A5"]},{"c":"P34B6","t":"Nockenwellenversteller B Temperaturfühler Stromkreis zu niedrig Bank 1","e":"B Camshaft Position Actuator Temperature Sensor Circuit Low Bank 1","d":"Zu niedrig heißt hier: Die Spannung auf der Signalleitung des Temperaturfühlers am Auslassversteller B (Bank 1) bleibt unter ihrer Untergrenze. Welche Temperatur dem entspricht, hängt von einer Kennlinie ab, deren Werte nirgends öffentlich stehen. Nimmt man einen Heißleiter an, dessen Widerstand mit der Wärme sinkt, sähe ein Masseschluss wie starke Hitze aus. Was ein Heißwert auslöst, zeigt das Aisin-Patent: Das Steuergerät senkt den Motorstrom und kann den Motor ab einer festen Schwelle sogar abschalten – die Auslassverstellung verliert dann an Wirkung. Im Katalog von NTN-SNR erscheint P34B6 als zu kleines Signal der Auslassseite. Verdächtig sind vor allem am Zylinderkopf scheuernde Leitungen und ein innen kurzgeschlossener Fühler. Kein Hersteller dokumentiert P34B6. Zu hoch: P34B7, Bank 2: P34BA.","u":[["h","Signalleitung durchgescheuert, Kontakt mit Masse"],["m","Fühlerelement im Versteller kurzgeschlossen"],["l","Treiber des Verstellers wegen schwergängiger Mechanik wirklich überhitzt"]],"s":["Motorkontrollleuchte leuchtet","Auslassverstellung auf Bank 1 reduziert, Leerlauf ggf. etwas unruhiger"],"k":["cam_actuator_b_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,800],[0.5,3]],"f":"MEL","x":["P34B4","P34B5","P34B7","P34BA","P34A6"]},{"c":"P34B7","t":"Nockenwellenversteller B Temperaturfühler Stromkreis zu hoch Bank 1","e":"B Camshaft Position Actuator Temperature Sensor Circuit High Bank 1","d":"P34B7 wird gesetzt, wenn das Temperatursignal des Auslassverstellers B auf Bank 1 über seiner Obergrenze liegt. Elektrisch spricht das für eine offene Signalleitung, eine gelöste Fühlermasse oder einen Schluss nach Versorgungsspannung; bei einem Heißleiter sähe das Steuergerät einen unglaubhaft kalten Versteller. Ein Kaltwert schadet für sich genommen nicht, nimmt dem Regler aber den Hitzeschutz: Im Aisin-Konzept entscheidet gerade dieser Wert, wann der Haltestrom am Anschlag zurückgenommen wird. Das Steuergerät verzichtet daher in der Regel auf die elektrische Verstellung. NTN-SNR nennt P34B7 ein zu hohes Signal der Auslassseite. Herstellertexte zu dem Code gibt es nicht. CARB fordert, solche Kreisfehler zu erkennen. Zu niedrig: P34B6.","u":[["h","Signalleitung oder Fühlermasse unterbrochen, Stecker korrodiert"],["m","Signalleitung mit Schluss zu einer Versorgungsleitung"],["m","Fühlerelement im Versteller hochohmig"]],"s":["Motorkontrollleuchte leuchtet","Auslassnocke auf Bank 1 in Standardlage gehalten"],"k":["cam_actuator_b_temp_sensor_b1","sensor_wiring"],"r":["medium",1,[50,800],[0.5,3]],"f":"MEL","x":["P34B4","P34B5","P34B6","P34BB","P34A7"]},{"c":"P34B8","t":"Nockenwellenversteller B Temperaturfühler Stromkreis Bank 2","e":"B Camshaft Position Actuator Temperature Sensor Circuit Bank 2","d":"P34B8 meldet einen Kreisfehler am Temperaturfühler des Auslassverstellers B auf Bank 2 – bei V- oder Boxermotoren die Reihe ohne Zylinder 1. Steht zugleich P34B4 im Speicher, liegt eine gemeinsame Versorgung, Masse oder das Steuergerät näher als zwei gleichzeitig defekte Fühler. Die Codefamilie setzt einen elektrisch angetriebenen Auslassversteller mit eigenem, wärmeempfindlichem Treiber voraus: NTN-SNR ordnet sie der Auslass-Nockenwellenverstellung zu, das Aisin-Patent begründet, wozu ein solcher Treiber überhaupt einen Fühler trägt. Einen Hersteller, der P34B8 verwendet, fanden wir weder in Bulletins noch in offiziellen Werkstattinformationen. Praktisch heißt das: zuerst Stecker und Kabelbaum auf Bank 2 prüfen, danach den Versteller. Signal zu klein bzw. zu groß auf Bank 2: P34BA, P34BB.","u":[["h","Stecker oder Kabelbaum am Auslassversteller von Bank 2 unterbrochen"],["m","Gemeinsame Versorgung oder Masse fehlerhaft (wenn Bank 1 ebenfalls meldet)"],["m","Temperaturfühler im Versteller von Bank 2 defekt"]],"s":["Motorkontrollleuchte leuchtet","Auslassverstellung auf Bank 2 eingeschränkt, Bänke laufen ggf. leicht ungleich"],"k":["cam_actuator_b_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,850],[0.5,3.5]],"f":"MEL","x":["P34B4","P34B9","P34BA","P34BB","P34A8"]},{"c":"P34B9","t":"Nockenwellenversteller B Temperaturfühler Bereich/Funktion Bank 2","e":"B Camshaft Position Actuator Temperature Sensor Range/Performance Bank 2","d":"Bei P34B9 meldet der Auslassversteller auf Bank 2 eine Temperatur, die elektrisch gültig, aber nicht stimmig ist. Ein Motor mit zwei Bänken bietet einen naheliegenden Maßstab: Nach langer Standzeit in der Kälte sollten beide Auslassversteller fast gleich anzeigen und sich bei gleicher Last ähnlich erwärmen. Ob ein Hersteller P34B9 so prüft, ist nicht veröffentlicht; der Code steht nur in Listen wie der von NTN-SNR. CARB verlangt für Eingangsbauteile der Ventilverstellung, wo machbar, eine Plausibilitätsprüfung zusätzlich zur Kontrolle auf Unterbrechung und Kurzschluss. In Frage kommen ein driftender Fühler, ein Übergangswiderstand, der den Wert verschiebt, oder veraltete Software. Im Aisin-Konzept würde ein falscher Heißwert den Motorstrom grundlos senken. Bank 1: P34B5.","u":[["m","Temperaturfühler des Verstellers auf Bank 2 driftet"],["m","Übergangswiderstand am Stecker verschiebt den Wert"],["l","Software des Steuergeräts veraltet"]],"s":["Motorkontrollleuchte leuchtet","Fahrverhalten meist unverändert"],"k":["cam_actuator_b_temp_sensor_b2"],"r":["medium",0,[80,900],[0.5,3]],"f":"MEDL","x":["P34B5","P34B8","P34BA","P34BB","P34A9"]},{"c":"P34BA","t":"Nockenwellenversteller B Temperaturfühler Stromkreis zu niedrig Bank 2","e":"B Camshaft Position Actuator Temperature Sensor Circuit Low Bank 2","d":"P34BA zeigt an, dass das Temperatursignal am Auslassversteller von Bank 2 unter seine Untergrenze gezogen wird. Häufig hat eine Signalleitung Masse gefunden, etwa dort, wo der Kabelbaum nahe an heißen Abgasteilen verläuft, oder das Fühlerelement ist im Versteller kurzgeschlossen. Deutet das Steuergerät die niedrige Spannung als Hitze, schützt es den Versteller durch weniger Strom, wie Aisin es beschreibt; die Auslass-Steuerzeit von Bank 2 folgt dann womöglich nicht mehr dem Sollwert, und Verstellcodes wie P0024 können hinzukommen. Im Katalog von NTN-SNR steht der Code, ein Hersteller veröffentlicht ihn nicht – Schwellen bleiben daher unbekannt. Die Reparatur reicht vom geflickten Kabel bis zum neuen Versteller, da der Fühler in dessen Elektronik sitzt. Bank 1 zu niedrig: P34B6, Bank 2 zu hoch: P34BB.","u":[["h","Kabelbaum nahe Abgasteilen beschädigt, Signal an Masse"],["m","Fühlerelement im Versteller von Bank 2 kurzgeschlossen"],["l","Eingang des ansteuernden Steuergeräts defekt"]],"s":["Motorkontrollleuchte leuchtet","Auslass-Steuerzeit von Bank 2 begrenzt, ggf. mit weiteren Verstellcodes"],"k":["cam_actuator_b_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,850],[0.5,3.5]],"f":"MEL","x":["P34B6","P34B8","P34B9","P34BB","P0024"]},{"c":"P34BB","t":"Nockenwellenversteller B Temperaturfühler Stromkreis zu hoch Bank 2","e":"B Camshaft Position Actuator Temperature Sensor Circuit High Bank 2","d":"P34BB wird gespeichert, sobald der Temperaturwert vom Auslassversteller der Bank 2 oberhalb seines Fensters bleibt – meist wegen einer gebrochenen Signalleitung, einer gelösten Masse oder Berührung mit einer Versorgungsleitung. Weil das Steuergerät nicht mehr erkennt, wie warm der Treiber des Verstellers ist, fehlt ihm die Grundlage, ihn zu schützen; im Aisin-Konzept etwa endet die Stromabsenkung erst, wenn der Wert eine Weile unter einer Rückkehrschwelle lag. Ohne Messwert hält das System den Auslassversteller dieser Bank meist in sicherer Lage, sodass oft nur die Warnleuchte auffällt. Kein Hersteller veröffentlicht P34BB; NTN-SNR spricht knapp von einem zu hohen Signal der Auslassseite, zweite Bank. Zu hoch auf Bank 1: P34B7, zu niedrig auf Bank 2: P34BA.","u":[["h","Signalleitung gebrochen oder Fühlermasse lose"],["m","Signalleitung berührt eine Versorgungsleitung"],["l","Fühler im Versteller von Bank 2 innen unterbrochen"]],"s":["Motorkontrollleuchte leuchtet","Auslassnocke von Bank 2 in sicherer Lage gehalten"],"k":["cam_actuator_b_temp_sensor_b2","sensor_wiring"],"r":["medium",1,[50,850],[0.5,3.5]],"f":"MEL","x":["P34B7","P34B8","P34B9","P34BA","P34AB"]},{"c":"P34BC","t":"Nockenwellenversteller B Positionssensor A Stromkreis Bank 1","e":"B Camshaft Position Actuator Position Sensor A Circuit Bank 1","d":"P34BC bedeutet: Mit der Verkabelung von Sensor A, der die Lage von Versteller B auf Bank 1 meldet, kann das Steuergerät nichts anfangen. Nach der NTN-SNR-Liste ist Versteller B der auf der Auslassseite. Wo solche Steller elektrisch arbeiten, meldet Sensor A den Winkel von Motor bzw. Versteller; Mitsubishi beschreibt das Einlass-Gegenstück P34AC, das nach mindestens einer Sekunde Spannung außerhalb des Fensters gesetzt wird. Mercedes-Benz ordnet die Rückmeldung seines CAMTRONIC-Auslass-Stellers bei den Achtzylindern M176/M177 genau dieser Gruppe zu, nennt im Bulletin aber nur P34BD und P34BE, nicht den allgemeinen Kreiscode. Zu P34BC selbst gibt es keine öffentliche Quelle; die Diagnose folgt daher dem üblichen Weg: Stecker, Leitungen, Sensorversorgung, zuletzt der Steller. Gegenstück auf Bank 2: P34C0.","u":[["h","Stecker am Auslass-Steller gelöst oder korrodiert, Leitung gebrochen"],["m","Versorgung oder Masse des Sensors fehlt"],["m","Im Steller integrierter Sensor defekt (Steller tauschen)"]],"s":["Motorkontrollleuchte leuchtet","Verstellung auf der Auslassseite von Bank 1 abgeschaltet","Ggf. leicht erhöhter Verbrauch"],"k":["cam_actuator_b_pos_sensor_b1","sensor_wiring"],"r":["medium",0,[80,1200],[0.5,4]],"f":"MEL","x":["P34BD","P34BE","P34BF","P34C0","P34AC","P2B47"]},{"c":"P34BD","t":"Nockenwellenversteller B Positionssensor A Bereich/Funktion Bank 1","e":"B Camshaft Position Actuator Position Sensor A Range/Performance Bank 1","d":"Für P34BD gibt es einen belegten Anwender. Mercedes-Benz nennt P34BD09 im Bulletin LI05.20-P-080192 vom Januar 2026 für die V8-Motoren M176/M177 mit CAMTRONIC, eingebaut etwa in AMG-63-Modellen, S 580, G 550 und GLS 600. Laut Fehlertext ist die Rückmeldung des CAMTRONIC-Stellers 1 (Auslass, Bank 1) gestört, eingestuft als Bauteilfehler. Als Ursache gibt Mercedes Software und Hardware an: Motorsteuergerät ME aktualisieren, die Teilenummern aller CAMTRONIC-Steller prüfen und ältere ersetzen (A177 982 03 03 bzw. 17 00 durch 19 00, 02 03 bzw. 16 00 durch 18 00) sowie nach Hitzespuren am Kabelbaum nahe der Stirnwand sehen. Häufig erscheinen dazu P005A (Auslass-Steller 1 hängt in Aus-Stellung) und der Notlaufcode P164B. Bank 2: P34C1.","u":[["h","Software des Motorsteuergeräts veraltet (Mercedes M176/M177: Update)"],["h","CAMTRONIC-Steller mit überholter Teilenummer"],["m","Kabelbaum über der Stirnwand durch Hitze geschädigt"]],"s":["Motorkontrollleuchte an","CAMTRONIC im Notlauf, oft mit weiteren CAMTRONIC-Codes"],"k":["cam_actuator_b_pos_sensor_b1"],"r":["hard",0,[150,1500],[1,5]],"f":"MEDL","x":["P34BC","P34BE","P34BF","P34C1","P005A","P2B48"]},{"c":"P34BE","t":"Nockenwellenversteller B Positionssensor A Stromkreis zu niedrig Bank 1","e":"B Camshaft Position Actuator Position Sensor A Circuit Low Bank 1","d":"Auch zu P34BE gibt es einen Mercedes-Text: Das CAMTRONIC-Bulletin zu den Achtzylindern M176 und M177 beschreibt P34BE00 als Masseschluss im Sensorsignal von Auslass-Steller 1, Bank 1. Das deckt sich mit der allgemeinen Bedeutung, einem Signal unter der Untergrenze. Mercedes verweist auf Motorabdeckung und Kabelbaum über der Stirnwand nahe der Frontscheibe, wo Hitzeschäden auftraten; beschädigte Leitungen sind mit Fotos und einem Lambda-Diagramm zu melden. Neben der Verkabelung gehören neuere Teilenummern der CAMTRONIC-Steller und ein Software-Update zur Abhilfe. Fehlt die Rückmeldung, kann das System in den Notlauf gehen (P164B), und das Auslass-Nockenprofil dieser Bank bleibt fest. Zu hoch auf Bank 1: P34BF, zu niedrig auf Bank 2: P34C2.","u":[["h","Hitzegeschädigter Kabelbaum über der Stirnwand, Signal an Masse"],["m","Sensor im CAMTRONIC-Steller kurzgeschlossen (ältere Teilenummer)"],["l","Software des Motorsteuergeräts nicht aktuell"]],"s":["Motorkontrollleuchte an","CAMTRONIC-Notlauf, Auslass-Ventilhub auf Bank 1 wird nicht mehr umgeschaltet"],"k":["cam_actuator_b_pos_sensor_b1","sensor_wiring"],"r":["hard",0,[100,1500],[1,5]],"f":"MEL","x":["P34BC","P34BD","P34BF","P34C2","P2B49"]},{"c":"P34BF","t":"Nockenwellenversteller B Positionssensor A Stromkreis zu hoch Bank 1","e":"B Camshaft Position Actuator Position Sensor A Circuit High Bank 1","d":"P34BF: Am Auslass-Steller der Bank 1 (Nockenwelle B) liefert Positionssensor A ein Signal über der Obergrenze. Üblich sind eine unterbrochene Masse, eine Signalleitung, die an einer Versorgung anliegt, oder ein innen offener Sensor. Mercedes-Benz belegt für diesen Sensor am CAMTRONIC-V8 zu niedrige und unplausible Signale (P34BE, P34BD), aber keinen Hochfehler; auch andere Hersteller erwähnen den Code nicht. Bei Mitsubishis elektrischem Einlassversteller setzt der entsprechende Hochcode P34AF den Motor in seine Referenzlage, und ein elektrischer Auslass-Steller dürfte ähnlich reagieren. CARB zählt die Sensoren der Ventilverstellung zu den umfassend zu überwachenden Bauteilen, deren Werte außerhalb des Bereichs erkannt werden müssen. Zu niedrig auf Bank 1: P34BE, zu hoch auf Bank 2: P34C3.","u":[["h","Sensormasse unterbrochen oder Stecker korrodiert"],["m","Signalleitung mit Schluss zu einer Versorgungsleitung"],["m","Sensor im Auslass-Steller innen unterbrochen"]],"s":["Motorkontrollleuchte leuchtet","Auslassverstellung auf Bank 1 in Referenzlage gehalten"],"k":["cam_actuator_b_pos_sensor_b1","sensor_wiring"],"r":["medium",0,[80,1200],[0.5,4]],"f":"MEL","x":["P34BC","P34BD","P34BE","P34C3","P34AF","P2B4A"]},{"c":"P34C0","t":"Nockenwellenversteller B Positionssensor A Stromkreis Bank 2","e":"B Camshaft Position Actuator Position Sensor A Circuit Bank 2","d":"P34C0 ist der allgemeine Kreisfehler von Positionssensor A am Nockenwellenversteller B auf Bank 2 und kommt daher nur an Zweibank-Motoren vor. Mercedes-Benz führt die Auslass-Rückmeldung von Bank 2 seines CAMTRONIC-V8 (M176/M177) unter benachbarten Codes – P34C1 bei unplausiblem Signal, P34C2 bei Masseschluss –, P34C0 selbst steht nicht im Bulletin, und auch sonst hat ihn kein Hersteller veröffentlicht. Die Diagnose bleibt deshalb allgemein: Versorgung, Masse und Signalleitung zwischen Steuergerät und Steller, danach der Steller mit eingebautem Sensor. Ist zugleich P34BC gesetzt, verdienen gemeinsame Versorgungen und Massen einen Blick, bevor Teile getauscht werden. NTN-SNR nennt den Code einen elektrischen Fehler der Auslassseite. Die übrigen Fehlerarten dieses Sensors: P34C1 bis P34C3.","u":[["h","Leitung oder Stecker am Auslass-Steller von Bank 2 unterbrochen"],["m","Gemeinsame Sensorversorgung oder Masse fehlerhaft (wenn auch P34BC gespeichert)"],["m","Sensor im Steller von Bank 2 defekt"]],"s":["Motorkontrollleuchte leuchtet","Auslassverstellung auf Bank 2 deaktiviert"],"k":["cam_actuator_b_pos_sensor_b2","sensor_wiring"],"r":["medium",0,[80,1300],[0.5,4.5]],"f":"MEL","x":["P34BC","P34C1","P34C2","P34C3","P34B0","P2B4B"]},{"c":"P34C1","t":"Nockenwellenversteller B Positionssensor A Bereich/Funktion Bank 2","e":"B Camshaft Position Actuator Position Sensor A Range/Performance Bank 2","d":"Mercedes-Benz nennt P34C109 für die Auslassseite von Bank 2 seiner CAMTRONIC-V8: Das Signal des Sensors an Steller 1 ist falsch, obwohl der Kreis intakt ist, eingetragen als Bauteilfehler. Warum es diese Prüfung gibt, erklärt CARB: Schon ein einzelner Zylinderstift eines Hubmechanismus, der seine Stellung nicht erreicht, ist ein Fehlerfall, den die Überwachung der Ventilverstellung erfassen muss. Dasselbe Bulletin LI05.20-P-080192 führt außerdem P005C (Auslass-Steller 1, Bank 2: Fehlfunktion oder in Stellung AUS festsitzend) und P164B (CAMTRONIC im Notlauf). Abhilfe laut Mercedes: Motorsoftware, aktuelle Teilenummern der Steller, Kabelbaum auf Hitzeschäden prüfen. Weil der Sensor zum Steller gehört, ist bei bestätigtem Fehler ein neuer Steller fällig. Gegenstück auf Bank 1: P34BD.","u":[["h","CAMTRONIC-Steller mit älterer Teilenummer (Mercedes: ersetzen)"],["h","Software des Motorsteuergeräts braucht ein Update"],["m","Stift des Stellers klemmt oder bewegt sich zu langsam"]],"s":["Motorkontrollleuchte an","CAMTRONIC-Notlauf, oft zusammen mit P005C"],"k":["cam_actuator_b_pos_sensor_b2"],"r":["hard",0,[150,1500],[1,5]],"f":"MEDL","x":["P34BD","P34C0","P34C2","P34C3","P005C","P2B4C"]},{"c":"P34C2","t":"Nockenwellenversteller B Positionssensor A Stromkreis zu niedrig Bank 2","e":"B Camshaft Position Actuator Position Sensor A Circuit Low Bank 2","d":"Mercedes-Benz belegt diesen Code als P34C200: Auf Zylinderbank 2 liegt die Rückmeldeleitung des CAMTRONIC-Auslass-Stellers 1 an Masse. Der Code gehört zu sechzehn, die das Bulletin LI05.20-P-080192 für die Motoren M176 und M177 zusammenfasst – zu finden in AMG-63-Modellen sowie in S-Klasse, G-Klasse und GLS. Weil an Leitungen, die über die Spritzwand neben der Windschutzscheibe laufen, Hitzeschäden auftraten, kommt die Sichtprüfung des Kabelbaums vor jedem Teiletausch; außerdem sollen Steller mit den älteren Nummern auf 02 03, 16 00, 03 03 und 17 00 gegen aktuelle Ausführungen getauscht und die Motorsoftware aktualisiert werden. Ein zu niedriges Signal kann auch von einem innen beschädigten Steller stammen. Bank 1 zu niedrig: P34BE, Bank 2 zu hoch: P34C3.","u":[["h","Kabelbaum nahe der Frontscheibe hitzegeschädigt, Signal an Masse"],["m","Sensor im CAMTRONIC-Steller von Bank 2 kurzgeschlossen"],["l","Software des Motorsteuergeräts veraltet"]],"s":["Motorkontrollleuchte an","CAMTRONIC-Notlauf, Auslasshub auf Bank 2 fest"],"k":["cam_actuator_b_pos_sensor_b2","sensor_wiring"],"r":["hard",0,[100,1500],[1,5]],"f":"MEL","x":["P34BE","P34C0","P34C1","P34C3","P2B4D"]},{"c":"P34C3","t":"Nockenwellenversteller B Positionssensor A Stromkreis zu hoch Bank 2","e":"B Camshaft Position Actuator Position Sensor A Circuit High Bank 2","d":"P34C3 schließt die Sensorgruppe von Versteller B ab: Auf Bank 2 meldet Positionssensor A des Auslass-Stellers eine Spannung über dem zulässigen Bereich. Üblich sind eine gebrochene Sensormasse, ein offener Signalweg oder ein Schluss zu einer Versorgungsleitung. Veröffentlicht hat P34C3 kein Hersteller. Mercedes-Benz, dessen CAMTRONIC-V8 auf dieser Bank die Nachbarcodes P34C1 und P34C2 nutzt, nennt keinen Hochfehler, und der Mitsubishi Outlander 2022 hat gar keinen elektrischen Auslass-Steller – seine Auslassnocke bewegt ein Ölsteuerventil, das der Notlauf zusammen mit dem elektrischen Einlassmotor in Referenzlage festhält. Bis die Ursache gefunden ist, bleibt die Auslassverstellung von Bank 2 in Grundstellung; Fahrer sehen vor allem die Warnleuchte. Bank 1: P34BF.","u":[["h","Sensormasse auf Bank 2 unterbrochen"],["m","Signalleitung in Kontakt mit einer Versorgungsleitung"],["m","Sensor im Auslass-Steller von Bank 2 fehlerhaft"]],"s":["Motorkontrollleuchte leuchtet","Auslassverstellung von Bank 2 in Grundstellung"],"k":["cam_actuator_b_pos_sensor_b2","sensor_wiring"],"r":["medium",0,[80,1300],[0.5,4.5]],"f":"MEL","x":["P34BF","P34C0","P34C1","P34C2","P34B3","P2B4E"]},{"c":"P34C4","t":"Nockenwellenversteller A Steuerkreis Treiberstrom/-temperatur zu hoch Bank 1","e":"A Camshaft Position Actuator Control Circuit Driver Current/Temperature Too High Bank 1","d":"P34C4 steht, wenn die Endstufe des Einlassverstellers A (Bank 1) meldet, dass ihr Strom oder ihre eigene Temperatur über der Grenze liegt. Gemeint sind elektrische Versteller, bei denen ein kleiner Motor statt eines Ölventils die Nockenwelle verdreht. Ein Aisin-Patent beschreibt den Schutz: Auf der Treiberplatine sitzen ein Stromsensor und ein Temperaturfühler; bleibt die Platine heiß, löst das Steuergerät den Versteller zuerst vom Anschlag und nimmt später den Strom ganz weg. NTN-SNR ordnet P34C4 der Einlassverstellung von Bank 1 zu. Nissan verstellt beim Pathfinder 2018 beide Einlassnocken elektrisch über ein eigenes Steuergerät (NTB18-016); eine öffentliche Herstellerbeschreibung zu P34C4 gibt es aber nicht. Häufige Auslöser sind ein schwergängiger Versteller, verschlammtes Öl oder eine Windung mit Schluss. Bank 2 meldet P34C5.","u":[["h","Versteller schwergängig oder am Anschlag, Motor zieht lange hohen Strom"],["m","Zu wenig oder verschlammtes Motoröl, Versteller dreht schwer"],["m","Windung oder Motorleitung des Stellers auf Bank 1 mit Schluss"],["l","Endstufe oder deren Sensoren im Verstellersteuergerät defekt"]],"s":["Motorkontrollleuchte an","Einlasssteuerzeit auf Bank 1 wird nicht mehr verstellt, bleibt fest","Weniger Zug untenherum, unruhigerer Leerlauf bei kaltem Motor"],"k":["cam_actuator_a_driver_b1","cam_actuator_a_b1"],"r":["hard",0,[80,1200],[0.5,4]],"f":"MEL","x":["P34C5","P34C6","P34C8","P34A4","P34AC","P0010"]},{"c":"P34C5","t":"Nockenwellenversteller A Steuerkreis Treiberstrom/-temperatur zu hoch Bank 2","e":"A Camshaft Position Actuator Control Circuit Driver Current/Temperature Too High Bank 2","d":"P34C5 ist das Gegenstück auf Bank 2: Die Endstufe, die den elektrischen Einlassversteller A der zweiten Zylinderbank antreibt, hat zu viel Strom gemessen oder ist zu warm geworden und schützt sich. Möglich ist das nur bei V- oder Boxermotoren mit je einem elektrischen Einlassversteller pro Bank. Zwei Bänke erlauben einen einfachen Gegentest: Bleibt der Fehler nach dem Tausch der Stellmotoren auf Bank 2, liegen Leitungen oder Steuergerät nahe; wandert er mit, ist es der Motor. Warum Wärme und Strom gemeinsam bewertet werden, zeigt das Aisin-Patent: Drückt der Motor den Versteller fest an den Anschlag, steigen beide zugleich. NTN-SNR führt den Code für die Einlassseite von Bank 2. Kein Autohersteller veröffentlicht P34C5; Nissans Bulletin NTB18-016 zum Pathfinder 2018 zeigt nur die Bauart. Bank 1: P34C4.","u":[["h","Versteller auf Bank 2 schwergängig oder am Endanschlag fest"],["m","Motorleitung zum Steller auf Bank 2 durchgescheuert oder kurzgeschlossen"],["m","Elektromotor des Stellers auf Bank 2 verschlissen oder innen kurzgeschlossen"],["l","Endstufe für Bank 2 im Verstellersteuergerät defekt"]],"s":["Motorkontrollleuchte an","Einlasssteuerzeit von Bank 2 eingefroren, Bänke laufen ungleich","Leicht unruhiger Leerlauf, weniger Drehmoment bei niedriger Drehzahl"],"k":["cam_actuator_a_driver_b2","cam_actuator_a_b2"],"r":["hard",0,[80,1200],[0.5,4]],"f":"MEL","x":["P34C4","P34C7","P34C8","P34A8","P34A9","P0020"]},{"c":"P34C6","t":"Nockenwellenversteller B Steuerkreis Treiberstrom/-temperatur zu hoch Bank 1","e":"B Camshaft Position Actuator Control Circuit Driver Current/Temperature Too High Bank 1","d":"P34C6 betrifft Versteller B, den NTN-SNR der Auslassnockenwelle zuordnet, auf Bank 1: Dessen Endstufe meldet Überstrom oder Übertemperatur. Voraussetzung wäre ein Auslassversteller mit Elektromotor, und ein solcher ist in öffentlichen Quellen nicht beschrieben. Der Mitsubishi Outlander 2022 verstellt die Auslassnocke über ein Ölsteuerventil, das im Notlauf in Referenzlage bleibt; Mercedes-Benz nutzt beim V8 M176/M177 Codes der B-Seite nur für die Lagerückmeldung von CAMTRONIC, nicht für die Belastung einer Endstufe. Ein Anwender ist daher nicht bekannt. Tritt der Code auf, gilt das Prinzip aus dem Aisin-Patent: Eine heiße Treiberplatine oder ein Motor gegen einen schwergängigen Versteller treibt den Strom hoch, worauf das Steuergerät zurückregelt oder abschaltet. Die Auslasssteuerzeit bleibt dann in Grundstellung. Bank 2: P34C7.","u":[["m","Auslassversteller auf Bank 1 schwergängig, Motor überlastet"],["m","Schluss in der Motorleitung von Steller B, Bank 1"],["l","Endstufe für Steller B beschädigt oder überhitzt"]],"s":["Motorkontrollleuchte an","Auslasssteuerzeit auf Bank 1 in Grundstellung festgehalten","Etwas höherer Verbrauch, leicht unruhigerer Lauf"],"k":["cam_actuator_b_driver_b1","cam_actuator_b_b1"],"r":["hard",0,[80,1300],[0.5,4]],"f":"MEL","x":["P34C7","P34C4","P34C8","P34B4","P34BC","P0013"]},{"c":"P34C7","t":"Nockenwellenversteller B Steuerkreis Treiberstrom/-temperatur zu hoch Bank 2","e":"B Camshaft Position Actuator Control Circuit Driver Current/Temperature Too High Bank 2","d":"P34C7 schließt die Vierergruppe der Endstufencodes ab: Für Bank 2 meldet der Treiber des auslassseitigen Verstellers B Strom oder Temperatur über dem Grenzwert. NTN-SNR führt ihn unter der Auslassverstellung der zweiten Bank. Er ist der seltenste der Gruppe, denn elektrische Versteller gibt es bislang auf der Einlassseite; ein öffentliches Herstellerdokument zu P34C7 existiert nicht. Der Fehlertyp zeigt Selbstschutz an; fehlerhafte Lage- oder Temperaturfühler dieses Verstellers haben eigene Codes (P34C0 bis P34C3, P34B8). Denkbar sind ein Motor, der gegen einen festsitzenden oder schlecht geschmierten Versteller arbeitet, ein Schluss in seiner Leitung oder ein Treiber, der nahe der heißen Auslassseite überhitzt. Der Motor läuft mit fester Auslasssteuerzeit weiter. Bank 1: P34C6.","u":[["m","Auslassversteller auf Bank 2 festsitzend oder schlecht geschmiert"],["m","Motorleitung von Steller B, Bank 2, kurzgeschlossen oder hitzegeschädigt"],["l","Treiber überhitzt wegen schlechter Kühlung oder Steuergerätefehler"]],"s":["Motorkontrollleuchte an","Auslasssteuerzeit von Bank 2 wird nicht mehr verändert","Meist nur geringe Änderungen im Motorlauf"],"k":["cam_actuator_b_driver_b2","cam_actuator_b_b2"],"r":["hard",0,[80,1300],[0.5,4]],"f":"MEL","x":["P34C6","P34C5","P34C8","P34B8","P34C0","P0023"]},{"c":"P34C8","t":"Steuergerät Nockenwellenverstellung Funktion","e":"Camshaft Position Control Module Performance","d":"P34C8 betrifft keinen einzelnen Versteller, sondern das eigene Steuergerät der Nockenwellenverstellung, das intern gestört ist. Mitsubishi dokumentiert ihn im Outlander 2022: Bei eingeschalteter Zündung erkennt das Modul des elektrischen Einlassverstellers einen Fehler seines Prozessors; als Ursache steht allein dieses Steuergerät. Im Notlauf bleiben elektrischer Einlassmotor und Ölsteuerventil der Auslassseite in Referenzlage, die Saugrohrklappe geht auf, die AGR wird abgeschaltet, der geschichtete Kaltstart entfällt und der Leerlauf läuft mit fester Drehzahl. Mercedes-Benz führt P34C800 bei den V8 M176/M177 als allgemeinen CAMTRONIC-Fehler (LI05.20-P-080192) und nennt Software-Update, neuere Steller und eine Prüfung des Kabelbaums auf Hitzeschäden. Anders als P34C4 bis P34C7 betrifft der Code das Steuergerät insgesamt.","u":[["h","Interner Prozessorfehler im Steuergerät der Nockenwellenverstellung"],["m","Veraltete Steuersoftware (Mercedes M176/M177: Update)"],["l","Versorgung oder Kabelbaum des Steuergeräts hitzegeschädigt bzw. mit schlechtem Kontakt"]],"s":["Motorkontrollleuchte an","Nockenwellenverstellung in Referenzlage festgehalten","Rauerer Kaltstart und fest eingestellte Leerlaufdrehzahl","Spürbar weniger Drehmoment, höherer Verbrauch"],"k":["cam_position_control_module"],"r":["medium",0,[100,1000],[0.5,2.5]],"f":"MEDL","x":["P34C4","P34C5","P34C6","P34C7","P0606","P34AC"]}];
